window.PACK={"book":{"id":"shafiya","title":"الشافية في علم التصريف","type":"lughabook","ilm":"sarf","author":"ابن الحاجب (ت ٦٤٦هـ)","source":"المكتبة الشاملة / هنداوي عبر مشروع OpenITI","edition":"المكتبة المكية - مكة","optional":true,"packVersion":"d732a3725156"},"items":[{"id":"shafiya:1","bookId":"shafiya","type":"section","seq":1,"chapter":"مقدمة","title":"مقدمة","page":"ص0","text":"بسم الله الرحمن الرحيم رب تمم بالخير\nالحمد لله رب العالمين وصلى الله على سيدنا محمد خاتم النبيين وعلى آله وصحبه أجمعين\nسألني من لا يسعني مخالفته أن ألحق بمقدمتي في الإعراب مقدمة في التصريف على نحوها ومقدمة في الخط فأجبته سائلا متضرعا أن ينفع بهما كما نفع بأختهما والله الموفق"},{"id":"shafiya:2","bookId":"shafiya","type":"section","seq":2,"chapter":"تعريف التصريف","title":"تعريف التصريف","page":"ج1 ص5","text":"التصريف علم بأصول يعرف بها أحوال أبنية الكلم التي ليست بإعراب"},{"id":"shafiya:3","bookId":"shafiya","type":"section","seq":3,"chapter":"تعريف التصريف","title":"أنواع الأبنية","page":"ج1 ص5","text":"وأبنية الاسم الأصول ثلاثية ورباعية وخماسية\nوأبنية الفعل ثلاثية ورباعية"},{"id":"shafiya:4","bookId":"shafiya","type":"section","seq":4,"chapter":"تعريف التصريف","title":"الميزان الصرفي","page":"ج1 ص5","text":"ويعبر عنها بالفاء والعين واللام وما زاد بلام ثانية وثالثة ويعبر عن الزائد بلفظه إلا المبدل من تاء الافتعال فإنه بالتاء وإلا المكرر للإلحاق أو لغيره فإنه بما تقدمه وإن كان من حروف الزيادة إلا بثبت ومن ثم كان حلتيت فعليلا لا فعليتا وسحنون وعثنون فعلولا لا فعلونا لذلك ولعدمه وسحنون إن صح الفتح ففعلون\nلا فعلول كحمدون وهو مختص بالعلم لندور فعلول وهو صعفوق وخرنوب ضعيف وسمنان فعلان\nوخزعال نادر وبطنان فعلان وقرطاس ضعيف مع أنه نقيض ظهران\nثم إن كان قلب في الموزون قلبت الزنة مثله كقولك في آدر أعفل"},{"id":"shafiya:5","bookId":"shafiya","type":"section","seq":5,"chapter":"تعريف التصريف","title":"القلب المكاني","page":"ج1 ص7","text":"ويعرف القلب بأصله كناء يناء مع النأي وبأمثلة اشتقاقه\nكالجاه والحادي والقسي وبصحته كأيس وبقلة استعماله كآرام وآدر وبأداء تركه إلى همزتين عند الخليل نحو جاء أو إلى منع الصرف بغير علة على الأصح نحو أشياء فإنها لفعاء وقال الكسائي أفعال وقال الفراء أفعاء وأصلها أفعلاء\nوكذلك الحذف كقولك في قاض فاع إلا أن يبين فيهما"},{"id":"shafiya:6","bookId":"shafiya","type":"section","seq":6,"chapter":"تعريف التصريف","title":"الصحيح والمعتل","page":"ج1 ص8","text":"وتنقسم إلى صحيح ومعتل فالمعتل ما فيه حرف علة والصحيح بخلافه فالمعتل بالفاء مثال وبالعين أجوف وذو الثلاثة وباللام منقوص وذو الأربعة وبالفاء والعين أو بالعين واللام لفيف مقرون وبالفاء واللام لفيف مفروق"},{"id":"shafiya:7","bookId":"shafiya","type":"section","seq":7,"chapter":"تعريف التصريف","title":"أبنية الاسم الثلاثي المجرد","page":"ج1 ص8","text":"وللاسم الثلاثي المجرد عشرة أبنية والقسمة تقتضي اثني عشر سقط منها فعل وفعل استثقالا وجعل الدئل منقولا والحبك إن ثبت\nفعلى تداخل اللغتين في حرفي الكلمة وهي فلس وفرس\nصفحة فارغة\nوكتف وعضد وحبر وعنب وإبل وقفل وصرد وعنق"},{"id":"shafiya:8","bookId":"shafiya","type":"section","seq":8,"chapter":"تعريف التصريف","title":"رد بعض الأبنية إلى بعض","page":"ج1 ص11","text":"وقد يرد بعض إلى بعض ففعل مما ثانيه حرف حلق كفخذ يجوز فيه فخذ وفخذ وفخذ وكذلك الفعل كشهد ونحو كتف\nيجوز فيه كتف وكتف ونحو عضد يجوز فيه عضد ونحو عنق يجوز فيه عنق ونحو إبل وبلز يجوز فيهما إبل وبلز ولا ثالث لهما ونحو قفل يجوز فيه قفل على رأي لمجيء عسر ويسر"},{"id":"shafiya:9","bookId":"shafiya","type":"section","seq":9,"chapter":"تعريف التصريف","title":"أبنية الاسم الرباعي المجرد","page":"ج1 ص13","text":"وللرباعي المجرد خمسة جعفر وزبرج وبرثن ودرهم وقمطر\nوزاد الأخفش نحو جخدب\nوأما جندل وعلبط فتوالي الحركات حملهما على باب جنادل وعلابط"},{"id":"shafiya:10","bookId":"shafiya","type":"section","seq":10,"chapter":"تعريف التصريف","title":"أبنية الاسم الخماسي المجرد","page":"ج1 ص13","text":"وللخماسي المجرد أربعة سفرجل وقرطعب وجحمرش وقذعمل"},{"id":"shafiya:11","bookId":"shafiya","type":"section","seq":11,"chapter":"تعريف التصريف","title":"أبنية الاسم المزيد فيه","page":"ج1 ص14","text":"وللمزيد فيه أبنية كثيرة ولم يجيء في الخماسي إلا عضرفوط وخزعبيل وقرطبوس وقبعثرى وخندريس على الأكثر"},{"id":"shafiya:12","bookId":"shafiya","type":"section","seq":12,"chapter":"تعريف التصريف","title":"أحوال الأبنية","page":"ج1 ص14","text":"وأحوال الأبنية قد تكون للحاجة ك"},{"id":"shafiya:13","bookId":"shafiya","type":"section","seq":13,"chapter":"تعريف التصريف","title":"الماضي","page":"ج1 ص14","text":"والمضارع والأمر واسم الفاعل واسم المفعول والصفة المشبهة وافعل التفضيل والمصدر واسمي الزمان والمكان والآلة والمصغر والمنسوب والجمع والتقاء الساكنين والابتداء والوقف وقد تكون للتوسع كالمقصور والممدود وذي الزيادة وقد تكون للمجانسة\nكالإمالة وقد تكون للاستثقال كتخفيف الهمزة والإعلال والإبدال والإدغام والحذف"},{"id":"shafiya:14","bookId":"shafiya","type":"section","seq":14,"chapter":"تعريف التصريف","title":"الماضي","page":"ج1 ص16","text":"للثلاثي المجرد ثلاثة أبنية فعل وفعل وفعل نحو ضربه وقتله وجلس وقعد وشربه وومقه وفرح ووثق وكرم\nوللمزيد فيه خمسة وعشرون\nملحق بدحرج نحو شملل وحوقل وبيطر وجهور وقلنس وقلسى\nوتكلم ملحق بتدحرج نحو تجلبب وتجورب وتشيطن وترهوك وتمسكن وتغافل وتكلم\nوملحق باحرنجم نحو اقعنسس واسلنقى\nوغير ملحق نحو أخرج وجرب وقاتل وانطلق واقتدر واستخرج واشهاب واشهب واغدودن واعلوط\nواستكان قيل افتعل من السكون فالمد شاذ وقيل استفعل من كان فالمد قياسي\nففعل لمعان كثيرة وباب المغالبة يبنى على فعلته أفعله بالضم نحو كارمني فكرمته أكرمه إلا باب وعدت وبعت ورميت فإنه أفعله بالكسر وعن الكسائي في نحو شاعرته فشعرته أشعره بالفتح\nوفعل يكثر فيه العلل والأحزان وأضدادها كسقم ومرض وبريء وحزن وفرح\nوتجيء الألوان والعيوب والحلي كلها عليه وقد جاء أدم وسمر وعجف وحمق وخرق وعجم ورعن بالكسر والضم\nوفعل لافعال الطبائع ونحوها كحسن وقبح وكبر وصغر فمن ثم كان لازما\nوشذ رحبتك الدار أي رحبت بك\nوأما باب سدته فالصحيح أن الضم لبيان بنات الواو لا للنقل وكذلك باب بعته وراعوا في باب خفت بيان البنية\nوأفعل للتعدية غالبا نحو أجلسته وللتعريض نحو أبعته ولصيرورته ذا كذا نحو أغد البعير ومنه أحصد الزرع ولوجوده على صفة نحو أحمدته وأبخلته وللسلب نحو أشكيته وبمعنى فعل نحو قلته وأقلته\nوفعل للتكثير غالبا نحو غلقت وقطعت وجولت وطوفت\nوموت المال أو للتعدية نحو فرحته ومنه فسقته وللسلب نحو جلدت البعير وقردته وبمعنى فعل نحو زلته وزيلته\nوفاعل لنسبة أصله إلى أحد الأمرين متعلقا بالآخر للمشاركة صريحا فيجيء العكس ضمنا نحو ضاربته وشاركته ومن ثم جاء غير المتعدي متعديا نحو كارمته وشاعرته والمتعدي إلى واحد مغاير للمفاعل متعديا إلى اثنين نحو جاذبته الثوب بخلاف شاتمته وبمعنى فعل نحو ضاعفت وبمعنى فعل نحو سافرت\nوتفاعل لمشاركة أمرين فصاعدا في اصله صريحا نحو تشاركا ومن ثم نقص مفعولا عن فاعل وليدل على أن الفاعل أظهر أن أصله حاصل له وهو منتف نحو تجاهل وتغافل وبمعنى فعل نحو توانيت ومطاوع فاعل نحو باعدته فتباعد\nوتفعل لمطاوعة فعل نحو كسرته فتكسر وللتكلف نحو تشجع وتحلم وللاتخاذ نحو توسد وللتجنب نحو تأثم\nوتحرج وللعمل المتكرر في مهلة نحو تجرعته ومنه تفهم وبمعنى استفعل نحو تكبر وتعظم\nوانفعل لازم مطاوع فعل نحو كسرته فانكسر وقد جاء مطاوع افعل محو اسفقته فانسفق وأزعجته فانزعج قليلا ويختص بالعلاج والتأثير ومن ثم قيل انعدم خطأ\nوافتعل للمطاوعة غالبا نحو غممته فاغتم وللاتخاذ نحو اشتوى وللمفاعلة نحو اجتوروا واختصموا وللتصرف نحو اكتسب\nواستفعل للسؤال غالبا إما صريحا نحو استكتبته أو تقديرا نحو استخرجته وللتحول نحو استحجر الطين\nو (إن البغاث بأرضنا تستنسر ... )\nوبمعنى فعل نحو قر واستقر"},{"id":"shafiya:15","bookId":"shafiya","type":"section","seq":15,"chapter":"تعريف التصريف","title":"بناء الفعل الرباعي","page":"ج1 ص21","text":"وللرباعي المجرد بناء واحد نحو دحرجته ودربخ أي ذل\nوللمزيد فيه ثلاثة نحو تدحرج واحرنجم واقشعر وهي لازمة\nالمضارع\nالمضارع بزيادة حرف"},{"id":"shafiya:16","bookId":"shafiya","type":"section","seq":16,"chapter":"تعريف التصريف","title":"المضارع","page":"ج1 ص22","text":"ة على الماضي\nفإن كان مجردا على فعل كسرت عينه أو ضمت أو فتحت إن كان العين أو اللام حرف حلق غير ألف وشذ أبي يأبى وأما قلى يقلى فعامرية وركن يركن من التداخل ولزموا الضم في الأجوف بالواو والمنقوص بها والكسر فيهما بالياء ومن قال طوحت وأطوح وتوهت وأتوه فطاح يطيح وتاه يتيه شاذ عنده أو من التداخل ولم يضموا في المثال ووجد يجد ضعيف ولرموا الضم في المضاعف المتعدي نحو يشد ويمد وجاء بالكسر في يشده ويعله وينمه ويبته ولزموه في حبه يحبه وهو قليل\nوإن كان على فعل فتحت عينه أو كسرت إن كان مثالا وطيئ\nتقول في باب بقي يبقى بقى يبقى وأما فضل يفضل ونعم ينعم فمن التداخل\nوإن كان على فعل ضمت عينه\nوإن كان غير ذلك كسر ما قبل الآخر ما لم يكن أول ماضيه تاء زائدة نحو تعلم وتجاهل فلا يغير أو لم تكن اللام مكررة نحو احمر واحمار فتدغم ومن ثم كان أصل مضارع أفعل يؤفعل إلا أنه رفض لما لزم من توالي همزتين في المتكلم فخفف الجميع وقوله\n(فإنه أهل لأن يؤكرما ... )\nشاذ\nوالأمر واسم الفاعل واسم المفعول وأفعل التفضيل تقدمت"},{"id":"shafiya:17","bookId":"shafiya","type":"section","seq":17,"chapter":"تعريف التصريف","title":"الصفة المشبهة","page":"ج1 ص24","text":"من نحو فرح على فرح غالبا وقد جاء معه في بعضها الضم نحو ندس وحذر وعجل وجاءت على سليم وشكس وحر وصفر وغيور ومن الألوان والعيوب والحلي على أفعل\nومن نحو كرم على كريم غالبا وجاءت على خشن وحسن وصعب وصلب وجبان وشجاع ووقور وجنب\nوهي من فعل قليلة وقد جاء نحو حريص وأشيب وضيق\nوتجيء من الجميع بمعنى الجوع والعطش وضدهما على فعلان نحو جوعان وشبعان وعطشان وريان"},{"id":"shafiya:18","bookId":"shafiya","type":"section","seq":18,"chapter":"تعريف التصريف","title":"المصدر","page":"ج1 ص25","text":"أبنية الثلاثي المجرد كثيرة نحو\nقتل وفسق وشغل ورحمة ونشدة وكدرة ودعوى وذكرى وبشرى وليان وحرمان وغفران ونزوان وطلب وخنق وصغر وهدى وغلبة وسرقة وذهاب وصراف وسؤال وزهادة ودراية ودخول وقبول ووجيف وصهوبة ومدخل ومرجع ومسعاة ومحمدة وبغاية وكراهية\nإلا أن الغالب في فعل اللازم نحو ركع على ركوع وفي المتعدي نحو ضرب على ضرب وفي الصنائع ونحوها نحو كتب على كتابة وفي الاضطراب نحو خفق على خفقان وفي الأصوات نحو صرخ على صراخ\nوقال الفراء إذا جاءك فعل مما لم يسمع مصدره فاجعله فعلا للحجاز وفعولا لنجد ونحو هدى وقرى مختص بالمنقوص\nونحو طلب مختص بيفعل إلا جلب الجرح والغلب\nوفعل اللازم نحو فرح على فرح والمتعدي نحو جهل على جهل وفي الألوان والعيوب نحو سمر وأدم على سمرة وأدمة\nوفعل نحو كرم على كرامة غالبا وعظم كثيرا وكرم نحوه\nوالمزيد فيه والرباعي قياس فنحو أكرم على إكرام ونحو كرم على تكريم وتكرمة وجاء كذاب وكذاب والتزموا الحذف والتعويض في نحو تعزية وإجازة واستجازة ونحو ضارب على مضاربة وضراب ومراء شاذ وجاء قيتال ونحو تكرم على تكرم وجاء تملاق والباقي واضح ونحو الترداد والتجوال والحثيثى والرميا للتكثير"},{"id":"shafiya:19","bookId":"shafiya","type":"section","seq":19,"chapter":"تعريف التصريف","title":"المصدر الميمي","page":"ج1 ص27","text":"ويجيء المصدر من الثلاثي المجرد أيضا على مفعل قياسا مطردا ك مقتل ومضرب وأما مكرم ومعون ولا غيرهما فنادران حتى جعلهما الفراء جمعا لمكرمة ومعونة\nومن غيره جاء على زنة المفعول ك مخرج ومستخرج وكذلك الباقي\nوأما ما جاء على مفعول ك الميسور والمعسور والمجلود والمفتون فقليل وفاعلة ك العافية والعاقبة والباقية والكاذبة أقل\nونحو دحرج على دحرجة ودرحاج بالكسر ونحو زلزل على زلزال بالفتح والكسر"},{"id":"shafiya:20","bookId":"shafiya","type":"section","seq":20,"chapter":"تعريف التصريف","title":"اسم المرة","page":"ج1 ص28","text":"والمرة من الثلاثي المجرد مما لا تاء فيه على فعلة نحو ضربة وقتلة وما عداه على المصدر المستعمل نحو إناخة فإن لم تكن تاء زدتها\n(وأتيته إتيانة ولقيته لقاءة شاذ ... )"},{"id":"shafiya:21","bookId":"shafiya","type":"section","seq":21,"chapter":"تعريف التصريف","title":"أسماء الزمان والمكان","page":"ج1 ص29","text":"أسماء الزمان والمكان مما مضارعه مفتوح العين أو مضمومها ومن المنقوص على مفعل نحو مشرب ومقتل ومرمى ومن مكسورها والمثال على مفعل نحو مضرب وموعد\nوجاء المنسك والمجزر والمنبت والمطلع والمشرق والمغرب والمفرق والمسقط والمسكن والمرفق والمسجد والمنخر\nوأما منخر ففرع ك منتن ولا غيرهما\nونحو المظنة والمقبرة فتحا وضما ليس بقياس\nوما عداه فعلى لفظ المفعول"},{"id":"shafiya:22","bookId":"shafiya","type":"section","seq":22,"chapter":"تعريف التصريف","title":"اسم الالة","page":"ج1 ص30","text":"الآلة على مفعل ومفعال ومفعلة ك المحلب والمفتاح والمكسحة\nونحو المسعط والمنخل والمدق والمدهن والمكحلة والمحرضة ليس بقياس"},{"id":"shafiya:23","bookId":"shafiya","type":"section","seq":23,"chapter":"تعريف التصريف","title":"التصغير","page":"ج1 ص31","text":"المصغر المزيد فيه ليدل على تقليل فالمتمكن يضم أوله ويفتح ثانية وبعدهما ياء ساكنة ويكسر ما بعدها في الأربعة إلا في تاء التأنيث وألفي التأنيث والألف والنون المشبهتين بهما وألف أفعال جمعا\nولا يزاد على أربعة فلذلك لم يجيء في غيرها إلا فعيل وفعيعل وفعيعيل وإذا صغر الخماسي على ضعفه فالأولى حذف الخامس وقيل ما أشبه الزائد وسمع الأخفش سفيرجل\nويرد نحو باب وناب وميزان وموقظ إلى أصله لذهاب المقتضي بخلاف قائم وتراث وأدد وقالوا عييد لقولهم أعياد\nفإن كانت مدة ثانية فالواو نحو ضويرب في ضارب وضويريب في ضيراب\nوالاسم على حرفين يرد محذوفة تقول في عدة وكل اسما وعيدة وأكيل وفي سه ومذ اسما ستيهة ومنيذ\nوفي دم وحر دمي وحريح وكذلك باب ابن واسم وأخت وبنت وهنت بخلاف باب ميت وهار وناس\nوإذا ولي ياء التصغير واو أو ألف منقلبة أو زائدة قلبت ياء وكذلك الهمزة المنقلبة بعدها نحو عرية وعصية ورسيلة وتصحيحه في باب أسيد وجديل قليل فإن اتفق اجتماع ثلاث ياءات حذفت الأخيرة نسيا على الأفصح كقولك في عطاء وإداوة وغاوية ومعاوية عطي وأدية وغوية ومعية وقياس أحوى أحي غير منصرف وعيسى يصرفه وقال أبو عمرو أحي وعلى قياس أسيود أحيو\nويزاد للمؤنث الثلاثي بغير تاء تاء ك عيينة وأذينة وعريب وعريس شاذ بخلاف الرباعي ك عقيرب\nوقديديمة ووريئة شاذ\nوتحذف الف التأنيث المقصورة غير الرابعة ك جحيجب وحويلي في جحجبى وحولايا وتثبت الممدودة مطلقا ثبوت الثاني في بعلبك\nوالمدة الواقعة بعد كسرة التصغير تنقلب ياء إن لم تكن إياها نحو مفيتيح وكريديس وذو الزيادتين غيرها من الثلاثي تحذف أقلهما فائدة ك مطيلق ومغيلم ومضيرب ومقيدم في منطلق ومغتلم ومضارب ومقدم فإن تساويا فمنحير ك قلينسة وقليسية وحبينط وحبيط وذو الثلاث غيرها تبقى الفضلى منها ك مقيعس في مقعنسس وتحذف زيادات الرباعي كلها مطلقا غير المدة ك قشيعر في مقشعر وحريجيم في احرنجام ويجوز التعويض عن حذف الزيادة بمدة بعد الكسرة فيما ليست فيه ك مغيليم في مغتلم\nويرد جمع الكثرة لا اسم الجمع إلى جمع قلته فيصغر نحو غليمة في غلمان إو إلى واحده فيصغر ثم يجمع جمع السلامة نحو غليمون ودويرات\nوما جاء على غير ما ذكر ك أنيسيان وعشيشية وأغيلمة وأصيبية شاذ\nوما جاء على غير ما ذكر ك أنيسيان وعشيشية وأغيلمة وأصيبية شاذ\nوقولهم أصيغر منك ودوين هذا وفويق هذا لتقليل\nما بينهما ونحو ما أحيسنه شاذ والمراد المتعجب منه ونحو جميل وكعيت لطائرين وكميت للفرس موضوع على التصغير\nوتصغير الترخيم تحذف منه كل الزوائد ثم يصغر ك حميد في أحمد\nوخولف بالإشارة والموصول فالحقت قبل آخرهما ياء وزيدت بعد آخرهما ألف فقيل ذيا وتيا واللذيا واللتيا واللذيان واللتيان واللذيون واللتيات\nورفضوا تصغير الضمائر ونحو أين ومتى ومن وما وحيث ومنذ ومع وغير وحسبك والاسم عاملا عمل الفعل فمن ثم جاز ضويرب زيد وامتنع ضويرب زيدا"},{"id":"shafiya:24","bookId":"shafiya","type":"section","seq":24,"chapter":"تعريف التصريف","title":"النسب","page":"ج1 ص36","text":"المنسوب الملحق آخره ياء مشددة لتدل على نسبته إلى المجرد عنها وقياسه حذف تاء التأنيث مطلقا وزيادة التثنية و"},{"id":"shafiya:25","bookId":"shafiya","type":"section","seq":25,"chapter":"تعريف التصريف","title":"الجمع","page":"ج1 ص36","text":"إلا علما قد أعرب بالحركات فلذلك جاء قنسري وقنسريني\nويفتح الثاني من نحو نمر والدئل بخلاف تغلبي على الأفصح\nوتحذف الياء والواو من فعيلة وفعولة بشرط صحة العين ونفي التضعيف ك حنفي وشنئي ومن فعيلة غير مضاعف ك جهينة بخلاف شديدي وطويلي وسليقي وسليمي في الأزد وعميري في كلب شاذ وعبدي وجذمي في بني عبيدة وجذيمة\nأشذ وخريبي شاذ وثقفي وقرشي وفقمي في كنانة وملحي في خزاعة شاذ\nوتحذف الياء من المعتل اللام من المذكر والمؤنث وتقلب الياء الأخيرة واوا ك غنوي وقصوي وأموي وجاء أميي بخلاف غنوي وأموي شاذ وأجري تحوي في تحية مجرى غنوي\nوأما نحو عدو فعدوي اتفاقا وفي نحو عدوة قال المبرد مثله وقال سيبويه عدوي\nوتحذف الياء الثانية من نحو سيدي وميتي ومهيمي من هيم وطائي شاذ فإن كان نحو مهيم تصغير مهوم قيل مهييمي بالتعويض\nوتقلب الألف الأخيرة الثالثة والرابعة المنقلبة واوا كعصوي ورحوي وملهوي ومرموي ويحذف غيرها ك حبلي وجمزي ومرامي وقبعثري وقد جاء في نحو حبلى حبلوي وحبلاوي بخلاف نحو جمزى\nوتقلب الياء الأخيرة الثالثة المكسور ما قبلها واوا ويفتح ما قبلها ك عموي وشجوي وتحذف الرابعة على الأفصح ك قاضي ويحذف ما سواهما ك مشتري\nوباب محيي جاء على محوي ومحيي ك أموي وأميي\nونحو ظبية وقنية ورقية وغزوة وعروة ورشوة على القياس عند سيبويه وزنوي وقروي شاذ عنده وقال يونس ظبوي وغزوي\nواتفقا في باب ظبي وغزواء وبدوي شاذ\nوباب طي وحي ترد الأولى إلى أصلها وتفتح فتقول طووي وحيوي بخلاف دوي وكوي\nوما آخره ياء مشددة بعد ثلاثة إن كان في نحو مرمي قيل مرموي ومرمي وإن كانت زائدة حذفت ك كرسي وبخاتي في بخاتي اسم رجل\nوما آخره همزة بعد ألف إن كانت للتأنيث قلبت واوا وصنعاني وبهراني وروحاني وجلولي وحروري شاذ وإن كانت أصلية\nثبتت على الأكثر كقرائي وإلا فالوجهان ككساوي وعلباوي\nوباب سقاية سقائي بالهمزة وباب شقاوة شقاوي بالواو وباب زاي وزاية زائي وزاوي\nوما كان على حرفين إن كان متحرك الأوسط أصلا والمحذوف اللام ولم يعوض همزة وصل أو كان المحذوف فاء وهو معتل اللام وجب رده ك أبوي وأخوي وستهي في ست ووشوي في شية وقال الأخفش وشيي على الأصل وإن كانت لامه صحيحة والمحذوف غيرها لم يرد كعدي وزني وسهي في سه وجاء عدوي وليس برد وما سواهما يجوز فيه الأمران نحو غدي وغدوي وابني وبنوي وحري وحرحي وأبو الحسن يسكن ما اصله السكون فيقول غدوي وحرحي وأخت وبنت كأخ وابن عند سيبويه وعليه كلوي وقال يونس\nأختي وبنتي وعليه كلتي وكلتوي وكلتاوي\nوالمركب ينسب إلى صدره ك بعلي وتأبطي وخمسي في خمسة عشر علما ولا ينسب إليه عددا والمضاف إن كان الثاني مقصودا أصلا كابن الزبير وأبي عمرو قيل زبيري وعمري وإن كان ك عبد مناف وامرئ القيس قيل عبدي ومرئي\nوالجمع يرد إلى الواحد فيقال في كتب وصحف ومساجد وفرائض كتابي وصحفي ومسجدي وفرضي وأما مساجد علما فمساجدي كأنصاري وكلابي\nوما جاء على غير ما ذكر فشاذ\nوكثر مجيء فعال في الحرف كبتات وعواج وثواب وجمال وجاء فاعل أيضا بمعنى ذي كذا ك تامر ولابن ودارع ونابل ومنه {عيشة راضية} وطاعم كاس"},{"id":"shafiya:26","bookId":"shafiya","type":"section","seq":26,"chapter":"تعريف التصريف","title":"الجمع","page":"ج1 ص42","text":"الثلاثي الغالب في نحو فلس على أفلس وفلوس وباب ثوب على أثواب وجاء زناد في غير باب سيل ورئلان وبطنان وغردة وسقف وأنجدة شاذ\nونحو حمل على أحمال وحمول وجاء على قداح وأرجل وعلى صنوان وذؤبان وقردة\nونحو قرء على أقراء وقروء وجاء على قرطة وخفاف وفلك\nوباب عود على عيدان\nونحو جمل على أجمال وجمال وباب تاج على تيجان وجاء على ذكور وأزمن وخربان وحملان وجيرة وحجلى\nونحو فخذ على أفخاذ فيهما وجاء على نمور ونمر\nونحو عجز على أعجاز وجاء سباع وليس رجلة بتكسير\nونحو عنب على أعناب فيهما وجاء أضلع وضلوع\nونحو إبل على آبال فيهما\nونحو صرد على صردان فيهما وجاء أرطاب ورباع\nونحو عنق على أعناق فيهما\nوامتنعوا من أفعل في المعتل العين وأقوس وأثوب وأعين وأنيب شاذ\nوامتنعوا من فعال في الياء دون الواو ك فعول في الواو دون الياء وفووج وسووق شاذ\nالمؤنث نحو قصعة على قصاع وبدور وبدر ونوب\nونحو لقحة على لقح غالبا وجاء على لقاح وأنعم\nونحو برقة على برق غالبا وجاء على حجوز وبرام\nونحو رقبة على رقاب وجاء على أينق وتير وبدن\nونحو معدة على معد\nونحو تخمة على تخم\nوإذا صحح باب تمرة قيل تمرات بالفتح والإسكان ضرورة والمعتل العين ساكن وهذيل تسوي وباب كسرة على كسرات بالفتح والكسر والمعتل العين والمعتل اللام بالواو يسكن ويفتح ونحو حجرة على حجرات بالضم والفتح والمعتل العين والمعتل اللام بالياء يسكن ويفتح وقد يسكن في تميم في حجرات وكسرات والمضاعف ساكن في الجميع وأما الصفات فبالإسكان وقالوا لجبات وربعات للمح اسميه أصلية وحكم نحو أرض وأهل وعرس وعير كذلك وباب سنة جاء فيه سنون وقلون وثبون وقلون وسنوات وعضوات وثبات وهنات وجاء آم كآكم\nالصفة نحو صعب على صعاب غالبا وباب شيخ على أشياخ وجاء ضيفان ووغدان وكهول ورطلة وشيخة وورد وسحل وسمحاء\nونحو جلف على أجلاف كثيرا وأجلف نادر\nونحو حر على أحرار\nونحو بطل على أبطال وحسان وإخوان وذكران ونصف\nونحو نكد على أنكاد ووجاع وخشن وجاء وجاعي وحباطي وحذارى\nونحو يقظ على أيقاظ وبابه التصحيح\nونحو جنب على أجناب\nوالجميع يجمع جمع السلامة للعقلاء الذكور وأما مؤنثه فبالألف والتاء لا غير نحو عبلات وحذرات ويقظات إلا نحو عبلة فإنه جاء على عبال وكماش وقالوا علج في جمع علجة\nما زيادته مدة ثالثة الاسم نحو زمان على أزمنة غالبا وجاء قذل وغزلان وعنوق\nونحو حمار على أحمرة وحمر غالبا وجاء صيران وشمائل\nونحو غراب على أغربة وجاء قرد وغربان وزقان وغلمة قليل وذب نادر\nوجاء في مؤنث الثلاثة أعنق وأذرع وأعقب غالبا وأمكن شاذ\nونحو رغيف على أرغفة ورغف ورغفان غالبا وجاء\nأنصباء وفصال وأفائل وظلمان قليل وربما جاء مضاعفه على سرر\nونحو عمود على أعمدة وعمد وجاء قعدان وأفلاء وذنائب\nالصفة نحو جبان على جبناء وصنع وجياد\nونحو كناز على كنز وهجان\nونحو شجاع على شجعاء وشجعان وشجعان\nونحو كريم على كرماء وكرام ونذر وثنيان وخصيان وأشراف وأصدقاء وأشحة وظروف\nونحو صبور على صبر غالبا وعلى ودداء وأعداء\nوفعيل بمعنى مفعول بابه فعلى كجرحى وأسرى وقتلى وجاء أسارى وشذ قتلاء وأسراء ولا يجمع جمع التصحيح فلا يقال جريحون ولا جريحات ليتميز عن فعيل الأصل ونحو مرضى محمول على جرحى وإذا حملوا عليه نحو هلكى وموتى وجربى فهذا أجدر كما حملوا أيامى ويتامى على وجاعى وحباطى\nالمؤنث نحو صبيحة على صبائح وصباح وجاء خلفاء وجعله جمع خليف أولى حملا على الأكثر\nونحو عجوز على عجائز\nفاعل الاسم نحو كاهل على كواهل وجاء حجران وجنان\nالمؤنث نحو كاثبة على كواثب وقد نزلوا فاعلاء\nمنزلته فقالوا قواصع ونوافق ودوام وسواب\nالصفة نحو جاهل على جهل وجهال غالبا وفسقة كثيرا وعلى قضاة في المعتل اللام وعلى بزل وشعراء وصحبان وتجار وقعود وأما فوارس فشاذ\nالمؤنث نحو نائمة على نوائم ونوم وكذلك حوائض وحيض\nالمؤنث بالألف نحو أنثى على إناث ونحو صحراء على صحارى\nوالصفة نحو عطشى على عطاش ونحو حرمى على حرامى\nونحو بطحاء على بطاح ونحو عشراء على عشار وفعلى أفعل نحو الصغرى على الصغر\nوبالألف خامسة نحو حبارى على حباريات\nافعل الاسم كيف تصرف نحو أجدل وإصبع وأحوص على أجادل وأصابع وأحاوص وقولهم حوص للمح الوصفية\nوافعل الصفة نحو أحمر على حمران ولا يقال أحمرون لتميزه عن أفعل التفضيل ولاحمراوات لأنه فرعه وجاء الخضراوات لغلبته اسما ونحو الافضل على الأفاضل والافضلين\nوالاسم نحو شيطان وسرحان وسلطان على شياطين وسراحين وسلاطين وجاء سراح\nوالصفة نحو غضبان على غضاب وسكارى وقد ضمت\nأربعة كسالى وسكارى وعجالى وغيارى\nفيعل نحو ميت على أموات وجياد وأبيناء\nونحو شرابون وحسانون وفسيقون ومضربون ومكرمون ومكرمون استغني فيها بالتصحيح\nوجاء عواوير وملاعين وميامين ومشائيم ومياسير ومفاطير ومناكير ومطافل ومشادن\nوالرباعي نحو جعفر وغيره على جعافر قياسا ونحو قرطاس على قراطيس وما كان على زنته ملحقا أو غير ملحق بمدة أو بغير مدة يجرى مجراه نحو كوكب وجدول وعثير وتنضب ومدعس وقرواح وقرطاط ومصباح ونحو جواربة وأشاعثة في الأعجمي والمنسوب\nوتكسير الخماسي مستكرة كتصغيره بحذف خامسه\nونحو تمر وحنظل وبطيخ مما يميز واحده بالتاء ليس بجمع على الأصح وهو غالب في غير المصنوع ونحو سفين ولبن وقلنس ليس بقياس وكمأة وكمء وجبأة وجبء عكس تمرة وتمر\nونحو ركب وحلق وجامل وسراة وفرهة وغزي وتوأم ليس بجمع على الأصح\nونحو أراهط وأباطيل وأحاديث وأعاريض وأقاطيع وأهال وليال وحمير وأمكن على غير الواحد منها\nوقد يجمع الجمع نحو أكالب وأناعيم وجمائل وجمالات وكلابات وبيوتات وحمرات وجزرات"},{"id":"shafiya:27","bookId":"shafiya","type":"section","seq":27,"chapter":"تعريف التصريف","title":"التقاء الساكنين","page":"ج1 ص55","text":"يغتفر في الوقف مطلقا وفي المدغم قبله لين في كلمة نحو خويصة والضالين وتمود الثوب وفي نحو ميم وعين مما بني لعدم التركيب وقفا ووصلا وفي نحو الحسن عندك وآيمن الله يمينك للإلباس وحلقتا البطان شاذ\nفإن كان غير ذلك وأولهما مدة حذفت نحو خف وقل وبع وتخشين واغزوا وارمي واغزن وارمن ويخشى القوم ويغزو الجيش ويرمي الغرض\nوالحركة في نحو خف الله واخشوا لله واخشي الله واخشون واخشين غير معتد بها بخلاف نحو خافا وخافن\nفإن لم يكن مدة حرك نحو اذهب اذهب ولم أبله و {الم الله} واخشوا الله واخشي الله ومن ثم قيل اخشون واخشين لأنه كالمنفصل\nإلا في نحو انطلق ولم يلده وفي رد ولم يرد في\nتميم مما فر من تحريكه للتخفيف فحرك الثاني وقراءة حفص {ويتقه} ليست منه على الأصح\nوالأصل الكسر فإن خولف فلعارض كوجوب الضم في ميم الجمع ومذ وكاختيار الفتح في {الم الله} وكجواز الضم إذا كان بعد الثاني منهما ضمة أصلية في كلمته نحو {وقالت اخرج}\nوقالت اغزي بخلاف {إن امرؤ} وقالت ارمو و {إن الحكم} واختياره في نحو اخشوا القوم عكس {لو استطعنا} وكجواز الضم والفتح في نحو رد ولم يرد بخلاف رد القوم على الأكثر وكوجوب الفتح في نحو ردها والضم في نحو رده على الأفصح والكسر لغية وغلط ثعلب في جواز الفتح لكونه ضعيفا والفتح في نون من مع اللام نحو من الرجل والكسر ضعيف عكس من ابنك وعن على الأصل وعن الرجل بالضم ضعيف\nوجاء في = المغتفر = النقر ومن النقر واضربه ودأبة\nوشأبة و {جان} بخلاف نحو {تأمروني}"},{"id":"shafiya:28","bookId":"shafiya","type":"section","seq":28,"chapter":"تعريف التصريف","title":"الابتداء","page":"ج1 ص60","text":"لا يبتدأ إلا بمتحرك كما لا يوقف إلا على ساكن فإن كان الأول ساكنا وذلك في عشرة أسماء محفوظة وهي ابن وابنة وابنم واسم واست وثنان واثنتان وامرؤ وامرأة وايمن الله وفي كل مصدر بعد ألف فعله الماضي أربعة فصاعدا كالاقتدار والاستخراج وفي أفعال تلك المصادر من ماض أو أمر وفي صيغة أمر الثلاثي وفي لام التعريف وفي ميمه ألحق في الابتداء خاصة همزة وصل مكسورة إلا فيما بعد ساكنه ضمة أصلية فإنها تضم نحو اقتل اعز اعزي بخلاف ارموا وإلا في لام التعريف وايمن الله فإنها تفتح\nوإثباتها وصلا لحن وشذ في الضرورة والتزموا جعلها ألفا لا بين بين على الأفصح في نحو آلحسن عندك وآيمن الله يمينك للبس\nوأما سكون هاء وهو وهي وفهو وفهي ولهو ولهي فعارض فصيح وكذلك لام الأمر نحو {وليوفوا} وشبه به أهي وأهو و {ثم ليقضوا} ونحو أن يمل هو)\nقليل"},{"id":"shafiya:29","bookId":"shafiya","type":"section","seq":29,"chapter":"تعريف التصريف","title":"الوقف","page":"ج1 ص62","text":"قطع الكلمة عما بعدها وفيه وجوه مختلفة في الحسن والمحل\nفالإسكان المجرد في المتحرك والروم في المتحرك وهو أن تأتي بالحركة خفية وهو في المفتوح قليل والإشمام في المضموم وهو أن تضم الشفتين بعد الإسكان والأكثر على أن لا روم ولا إشمام في هاء التأنيث وميم الجمع والحركة العارضة\nوإبدال الألف في المنصوب المنون وفي إذا وفي نحو اضربن بخلاف المرفوع والمجرور في الواو والياء على الأفصح\nويوقف على الألف في باب عصا ورحى باتفاق وقلبها وقلب كل ألف همزة ضعيف وكذلك قلب ألف التأنيث في نحو حبلى همزة أو واوا أو ياء\nوإبدال تاء التأنيث الاسمية هاء في نحو رحمة على الأكثر وتشبيه تاء هيهات به قليل وفي الضاربات ضعيف\nوعرقات إن فتحت تاؤه في النصب فالبهاء وإلا فبالتاء وأما ثلاثة أربعة فيمن حرك فلأنه نقل حركة همزة القطع لما وصل بخلاف {الم الله} فإنه لما وصل التقى ساكنان\nوزيادة الألف في أنا ومن ثم وقف على {لكن هو الله ربي} بالألف ومه وأنه قليل\nوإلحاق هاء السكت لازم في نحو ره وقه ومجيء مه ومثل مه في مجيء م جئت ومثل م أنت وجائز في لم يخشه ولم يرمه ولم يغزه وغلاميه وعلى مه وحتى مه وإلى مه\nمما حركته غير إعرابية ولا مشبهة بها كالماضي وباب يا زيد ولا رجل وفي نحو ها هناه وهؤلاه\nوحذف الياء في نحو القاضي وغلامي حركت أو سكنت وإثباتها أكثر عكس قاض وإثباتها في نحو يا مري اتفاق\nوإثبات الواو والياء وحذفهما في الفواصل والقوافي فصيح وحذفهما فيهما في نحو لم يغزوا ولم ترمي وصنعوا قليل\nوحذف الواو في ضربه وضربهم فيمن الحق والياء في نحو ته وهذه\nوإبدال الهمزة حرفا من جنس حركتها عند قوم مثل هذا الكلو والخبو والبطو والردو ورأيت الكلا والخبا والبطا والردا ومررت بالكلي والخبي والبطي والردي ومنهم من يقول هذا الردي ومن البطو فيتبع\nوالتضعيف في المتحرك الصحيح غير الهمزة المتحرك ما قبلها مثل جعفر وهو قليل ونحو القصبا شاذ ضرورة\nونقل الحركة فيما قبله ساكن صحيح إلا الفتحة إلا في الهمزة وهو أيضا قليل مثل هذا بكر وخبؤ ومررت ببكر وخبىء ورأيت الخبأ ولا يقال رأيت البكر ولا هذا حبر ولا من قفل ويقال هذا الردؤ ومن البطىء ومنهم من يفر فيتبع"},{"id":"shafiya:30","bookId":"shafiya","type":"section","seq":30,"chapter":"تعريف التصريف","title":"المقصور والممدود","page":"ج1 ص67","text":"المقصور ما آخره ألف مفردة كالعصا والرحى\nوالممدود ما كان بعدها فيه همزة كالكساء والرداء\nوالقياسي من المقصور أن يكون ما قبل آخر نظيره من الصحيح فتحة ومن الممدود أن يكون ما قبله الفا\nفالمعتل اللام من أسماء المفاعيل من غير الثلاثي المجرد مقصور كمعطى ومشترى لأن نظائرهما مكرم ومشترك وأسماء الزمان والمكان والمصدر مما قياسه مفعل ومفعل كمغزى وملهى لأن نظائرهما مقتل ومخرج والمصدر من فعل فهو أفعل أو فعلان أو فعل كالعشى والصدى والطوى لأن نظائرها الحول والعطش والفرق والغراء شاذ والأصمعي يقصره وجمع فعلة وفعلة كعرى\nوجزى لأن نظائرهما قرب وقرب\nونحو الإعطاء والرماء والاشتراء والاحبنطاء ممدود لأن نظائرها الإكرام والطلاب والافتتاح والاحرنجام وأسماء الأصوات المضموم أولها كالعواء والثغاء لأن نظائرها النباح والصراخ ومفرد أفعلة نحو كساء وقباء لأن نظائرها حمار وقذال وأندية شاذ\nوالسماعي نحو العصا والرحى والخفاء والإباء مما ليس له نظير يحمل عليه"},{"id":"shafiya:31","bookId":"shafiya","type":"section","seq":31,"chapter":"تعريف التصريف","title":"ذو الزيادة","page":"ج1 ص69","text":"حروفها اليوم تنساه أو سألتمونيها أو السمان هويت أي التي لا تكون الزيادة لغير الإلحاق والتضعيف إلا منها\nومعنى الإلحاق أنها إنما زيدت لغرض جعل مثال على مثال أزيد منه ليعامل معاملته فنحو قردد ملحق ونحو مقتل غير ملحق لما ثبت من قياسها لغيره ونحو أفعل وفعل وفاعل كذلك لذلك ولمجيء مصادرها مخالفة\nولا تقع الألف للإلحاق في الاسم حشوا لما يلزم من تحريكها\nوتعرف الزيادة بالاشتقاق وعدم النظير وغلبة الزيادة فيه والترجيح عند التعارض\nوالاشتقاق المحقق مقدم فلذلك حكم بثلاثية عنسل وشأمل\nوشمأل ونئدل ورعشن وفرسن وبلغن وحطائط ودلامص وقمارص وهرماس وزرقم وقنعاس وفرناس وترنموت\nوكان ألندد أفنعلا ومعد فعلا لمجيء تمعدد ولم يعتد بتمسكن وتمدرع وتمندل لوضوح شذوذه ومراجل فعالل لمجيء ثوب ممرجل وضهيأ فعلأ لمجيء ضهياء وفينان فيعالا لمجيء فنن وجرائض فعائلا لمجيء جرواض ومعزى فعلى لقولهم معز وسنبتة فعلتة لقولهم سنب وبلهنية فعلنية من قولهم عيش أبله والعرضنة فعلنة لأنه من الاعتراض والأول أفعل لمجيء الأولى والأول والصحيح أنه من وول لا من وأل ولا من أول وإنقحل إنفعلا لأنه من قحل أي يبس وأفعوان أفعلانا لمجيء أفعى وإضحيان إفعلانا من الضحى وخنفقيق\nفنعليلا من خفق وعفرني فعلني من العفر\nفإن رجع إلى اشتقاقين واضحين كأرطى وأولق حيث قيل بعير آرط وراط وأديم مأروط ومرطي ورجل مألوق ومولوق جاز الأمران وكحسان وحمار قبان حيث صرف ومنع\nوإلا فالترجيح كملأك قيل مفعل من الألوكة ابن كيسان فعأل من الملك وابو عبيدة مفعل من لأك إذا\nأرسل وموسى مفعل من أوسيت أي حلقت والكوفيون فعلى من ماس وإنسان فعلان من الأنس وقيل إفعان من نسي لمجيء أنسيان وتربوت فعلوت من التراب عند سيبويه لأنه الذلول وقال في سبروت فعلول وقيل من السبر وقال في تنبالة فعلالة وقيل من النبل للصغار لأنه القصير وسرية قيل من السر وقيل من السراة ومؤونة قيل من مان يمون وقيل من الأون لأنها ثقل وقال الفراء من الأين وأما منجنيق فإن اعتد بجنقونا فمنفعيل وإلا فإن اعتد بمجانيق ففنعليل وإلا فإن اعتد بسلسبيل على الأكثر ففعلليل وإلا ففعلنيل ومجانيق يحتمل\nالثلاثة ومنجنون مثله لمجيء منجنين إلا في منفعيل ولولا منجنين لكان فعللولا كعضرفوط وخندريس كمنجنين\nفإن فقد الاشتقاق فبخروجها عن الاصول كتاء تتفل وترتب وكنون كنتأل وكنهبل بخلاف كنهور ونون خنفساء وقنفخر أو بخروج زنة أخرى لها كتاء تتفل وترتب مع تتفل وترتب ونون قنفخر مع قنفخر وخنفساء مع خنفساء وهمزة ألنجج مع ألنجوج\nفإن خرجتا معا فزائد ايضا كنون نرجس وحنطأو ونون جندب إذا لم يثبت جخدب إلا أن تشذ الزيادة كميم مرزنجوش دون نونها إذ لم تزد الميم أولا خامسة ونون برناساء وأما كنأبيل فمثل خزعبيل\nفإن لم تخرج فبالغلبة كالتضعيف في موضع أو موضعين مع ثلاثة أصول للإلحاق وغيره كقردد ومرمريس وعصبصب وهمرش وعند الأخفش اصله هنمرش كجحمرش لعدم فعلل قال ولذلك لم يظهروا والزائد في نحو كرم الثاني وقال الخليل الأول وجوز سيبويه الأمرين\nولا تضاعف الفاء وحدها ونحو زلزل وصيصة وقوقيت وضوضيت رباعي وليس بتكرير لفاء ولاعين للفصل ولا بذي زيادة لأحد حرفي اللين لرفع التحكم وكذلك سلسبيل خماسي على الأكثر وقال الكوفيون زلزل من زل وصرصر من صر ودمدم من دم لاتفاق المعنى\nوكالهمزة أولا مع ثلاثة أصول فقط فأفكل أفعل\nوالمخالف مخطىء وإصطبل فعلل كقرطعب\nوالميم كذلك ومطردة في الجاري على الفعل\nوالياء زيدت مع ثلاثة فصاعدا إلا في أول الرباعي إلا فيما يجري على الفعل ولذلك كان يستعور كعضرفوط وسلحفية فعلية\nوالواو والألف زيدتا مع ثلاثة فصاعدا إلا في الأول ولذلك كان ورنتل كجحنفل\nوالنون كثرت بعد الألف آخرا أو ثالثة ساكنة نحو شرنبث وعرند واطردت في المضارع والمطاوع\nوالتاء في تفعيل ونحوه وفي نحو رغبوت وجبروت\nوالسين اطردت في استفعل وشذت في أسطاع قال\nسيبويه هو أطاع فمضارعه يسطيع بالضم وقال الفراء الشاذ فتح الهمزة وحذف التاء فمضارعه بالفتح وعد سين الكسكسة غلط لاستلزامه شين الكشكشة\nوأما اللام فقليلة كزيدل وعبدل حتى قال بعضهم في فيشلة فيعلة مع فيشة وفي هيقل مع هيق وفي طيسل مع طيس للكثير وفي فحجل كجعفر مع أفحج\nوأما الهاء فكان المبرد لا يعدها ولا يلزمه نحو اخشه فإنها\nحرف معنى كالتنوين وباء الجر ولامه وإنما يلزمه نحو أمهات ونحو\n(أمهتي خندف وإلياس أبي ... )\nوأم فعل بدليل الأمومة وأجيب بجواز أصالتها بدليل تأمهت فتكون أمهة فعلة كأبهة ثم حذفت الهاء أو هما أصلان كدمث ودمثر وثرة وثرثار ولؤلؤ ولأل ويلزمه نحو أهراق إهراقة\nأبو الحسن يقول هجرع للطويل من الجرع للمكان السهل وهبلع للأكول من البلع وخولف وقال الخليل الهركولة للضخمة هفعولة لأنها تركل في مشيها وخولف\nفإن تعدد الغالب مع ثلاثة أصول حكم بالزيادة فيها\nأو فيهما كحبنطى فإن تعين أحدهما رجح بخروجها كميم مريم ومدين وهمزة أيدع وياء تيحان وتاء عزويت وطاء قطوطى ولام ادلولى دون الفهما لعدم فعولى وافعولى ووجود فعوعل وافعوعل وواو حولايا دون يائها وأول يهير والتضعيف دون الثانية وهمزة أرونان دون واوها وإن لم يأت إلا\nأنبجان فإن خرجتا رجح بأكثرهما كالتضعيف في تئفان والواو في كوألل ونون حنطأو وواوها فإن لم تخرج فيهما رجح بالإظهار الشاذ وقيل بشبهة الاشتقاق ومن ثم اختلف في يأجج ومأجج ونحو محبب علما يقوي الضعيف وأجيب بوضوح اشتقاقه فإن ثبتت فيهما بالإظهار اتفاقا كدال مهدد فإن لم يكن فيه إظهار فبشبهة الاشتقاق كميم موظب ومعلى وفي تقديم أغلبهما عليها نظر ولذلك قيل رمان\nفعال لغلبتها في نحوه فإن ثبتت فيهما رجح بأغلب الوزنين وقيل بأقيسهما ومن ثم اختلف في مورق دون حومان فإن ندرا احتملهما كأرجوان فإن فقدت شبهة الاشتقاق فيهما فبالأغلب\nكهمزة أفعى وأوتكان وميم إمعة فإن ندرا احتملهما كأسطوانة إن ثبتت أفعوالة وإلا ففعلوانة لا أفعلانة لمجيء أساطين"},{"id":"shafiya:32","bookId":"shafiya","type":"section","seq":32,"chapter":"تعريف التصريف","title":"الإمالة","page":"ج1 ص82","text":"أن ينحى بالفتحة نحو الكسرة وسببها قصد المناسبة لكسرة أو ياء أو لكون الألف منقلبة عن مكسور أو ياء أو صائرة ياء مفتوحة أو للفواصل أو لإمالة قبلها على وجه\nفالكسرة قبل الألف نحو عماد وشملال ونحو درهمان سوغة خفاء الهاء مع شذوذه وبعدها في نحو عالم ونحو من كلام قليل لعروضها بخلاف من دار للراء وليس مقدرها الأصلي كملفوظها على الأفصح كجاد وجواد بخلاف سكون الوقف\nولا تؤثر الكسرة في المنقلبة عن واو ونحو من بابه وماله والكبا شاذ كما شذ العشا والمكا وباب ومال والحجاج\nوالناس لغير سبب وأما إمالة الربا فلأجل الراء\nوالياء إنما تؤثر قبلها في نحو سيال وشيبان\nوالمنقلبة عن مكسور نحو خاف وعن ياء نحو ناب والرحى وسال ورمى\nوالصائرة ياء مفتوحة نحو دعا وحبلى والعلى بخلاف جال وحال\nوالفواصل نحو {والضحى}\nوالإمالة نحو رأيت عمادا\nوقد تمال ألف التنوين نحو رأيت زيدا\nوالاستعلاء في غير باب خاف وطاب وصغى مانع قبلها يليها\nفي كلمتها وبحرفين على رأي وبعدها يليها في كلمتها وبحرف وبحرفين على الأكثر\nوالراء غير المسكورة إذا وليت الألف قبلها أو بعدها منعت منع المستعلية وتغلب المسكورة بعدها المستعلية وغير المكسورة فيمال طارد وغارم ومن قرارك فإذا تباعدت فكالعدم في المنع والغلب عند الأكثر فيمال هذا كافر ويفتح مررت بقادر وبعضهم يعكس وقيل هو الأكثر\nوقد يمال ما قبل هاء التأنيث في الوقف وتحسن في نحو رحمة وتقبح في الراء نحو كدرة وتتوسط في الاستعلاء نحو حقة\nوالحروف لا تمال فإن سمي بها فكالأسماء وأميل بلى ويا ولا في إمالا لتضمنها الجملة وغير المتمكن كالحرف\nوذا وأنى ومتى ك بلى وأميل عسى لمجيء عسيت\nوقد تمال الفتحة منفردة في نحو من الضرر ومن الكبر ومن المحاذر"},{"id":"shafiya:33","bookId":"shafiya","type":"section","seq":33,"chapter":"تعريف التصريف","title":"تخفيف الهمزة","page":"ج1 ص86","text":"يجمعه الإبدال والحذف وبين بين أي بينها وبين حرف حركتها وقيل أو حرف حركة ما قبلها وشرطه أن لا تكون مبتدأ بها\nوهي ساكنة ومتحركة فالساكنة تبدل بحرف حركة ما قبلها كرأس وبير وسوت وإلى الهداتنا والذيتمن ويقولوذن لي\nوالمتحركة إن كان ما قبلها ساكن وهو واو أو ياء زائدتان لغير الإلحاق قلبت إليها وأدغمت فيها كخطية ومقروة وأفيس وقولهم التزم في نبي وبرية غير صحيح ولكنه كثر وإن كان ألفا فبين بين المشهور وإن كان حرفا صحيحا أو معتلا غير ذلك نقلت\nحركتها إليه وحذفت نحو مسلة والخب وشي وسو وجيل وحوبة وأبو يوب وذو مرهم واتبعى مره وقاضوبيك وقد جاء باب شيء وسوء مدغما أيضا والتزم ذلك في باب يرى وأرى يري للكثرة بخلاف ينأى وأنأى ينئي وكثر في سل للهمزتين\nوإذا وقف على المتطرفة وقف بمقتضى الوقف بعد التخفيف فيجيء في هذا الخب وبري ومقرو السكون والروم والإشمام وكذلك باب شيء وسوء نقلت أو أدغمت إلا أن ما قبلها ألف إذا وقف بالسكون وجب قلبها ألفا إذ لا نقلة وتعذر التسهيل فيجوز القصر والتطويل وإن وقف بالروم فالتسهيل كالوصل\nوإن كان قبلها متحرك فتسع مفتوحة وقبلها الثلاث ومكسورة كذلك ومضمومة كذلك نحو سأل ومائة ومؤجل وسئم\nومستهزئين وسئل ورؤوف ومستهزئون ورؤوس فنحو مؤجل واو ونحو مائة ياء ونحو مستهزئون وسئل بين بين المشهور وقيل البعيد والباقي بين بين المشهور وجاء منساة و {سأل} ونحو الواجي وصلا وأما\n(يشجج رأسه بالفهرواجي ... )\nفعلى القياس خلافا لسيبويه\nوالتزموا خذ وكل على غير قياس للكثرة وقالوا مر وهو أفصح من اؤمر وأما وأمر فافصح من ومر\nوإذا خفف باب الأحمر فبقاء همزة اللام أكثر فيقال الحمر ولحمر وعلى الأكثر قيل من لحمر بفتح النون وفلحمر بحذف الياء وعلى الأقل جاء وعادلولى ولم يقولوا اسل ولا اقل لاتحاد الكلمة\nوالهمزتان في كلمة إن سكنت الثانية وجب قلبها كآدم وايت وأوتمن وليس آجر منه لأنه فاعل لا أفعل لثبوت يؤاجر ومما قلته فيه\n(ذللت ثلاثا على أن يؤجر ... لا يستقيم مضارع آجر)\n(فعالة جاء والافعال عز ... وصحة آجر تمنع آجر)\nوإن تحركت وسكن ما قبلها كسأل تثبت وإن تحركت وتحرك ما قبلها فقالوا وجب قلب الثانية ياء إن انكسر ما قبلها أو انكسرت وواوا في غيره نحو جاء وأيمة وأويدم وأوادم ومنه خطايا في التقدير الأصلي خلافا للخليل وقد صح التسهيل في نحو {أئمة} والتحقيق والتزم في باب أكرم حذف الثانية وحمل عليه أخواته وقد التزموا قلبها مفردة ياء مفتوحة في باب مطايا ومنه خطايا على القولين وفي كلمتين يجوز تحقيقهما وتخفيفهما وتخفيف إحداهما على قياسها وجاء في نحو\n{يشاء إلى} الواو أيضا في الثانية وجاء في المتفقتين حذف احداهما وقلب الثانية كالساكنة"},{"id":"shafiya:34","bookId":"shafiya","type":"section","seq":34,"chapter":"تعريف التصريف","title":"الإعلال","page":"ج1 ص93","text":"تغيير حرف العلة للتخفيف ويجمعه القلب والحذف والإسكان وحروفه الألف والواو والياء ولا يكون الألف أصلا في متمكن ولا في فعل ولكن عن واو أو ياء\nوقد اتفقتا فاءين كوعد ويسر وعينين كقول وبيع ولامين كغزو ورمي وتقدمت كل واحدة على الأخرى فاء وعينا كويل ويوم واختلفتا في أن الواو تقدمت عينا على الياء لاما بخلاف العكس وواو حيوان بدل عن ياء وأن الياء وقعت فاء وعينا في يين وفاء ولاما في يديت بخلاف الواو إلا في أول على الأصح وإلا في الواو على وجه وأن الياء وقعت فاء وعينا\nولاما في يييت بخلاف الواو إلا في الواو على وجه\nالفاء تقلب الواو همزة لزوما في نحو أواصل وأويصل والأول إذا تحركت الثانية بخلاف ووري وجوازا في نحو أجوه وأوري وقال المازني وفي نحو إشاح والتزموه في الأولى حملا على الأول وأما أناة وأحد وأسماء فعلى غير القياس\nوتقلبان تاء في نحو اتعد واتسر بخلاف ايتزر\nوتقلب الواو ياء إذا انكسر ما قبلها والياء واوا إذا انضم ما قبلها نحو ميزان وميقات وموقظ وموسر\nوتحذف الواو من نحو يعد ويلد لوقوعها بين ياء وكسرة أصلية ومن ثم لم يبن مثل وددت بالفتح لما يلزم من إعلالين في يد وحمل أخواته نحو نعد وأعد وتعد وصيغة أمره عليه ولذلك\nحملت فتحة يسع ويضع على العروض ويوجل على الأصل وشبهتا بالتجاري والتجارب بخلاف الياء في نحو ييئس وييسر وقد جاء يئس وجاء ياءس كما جاء يا تعد ويا تسر وعليه جاء موتعد وموتسر في لغة الشافعي وشذ في مضارع وجل ييجل وياجل وييجل ويحذف الواو من نحو العدة والمقة ونحو وجهة قليل\nالعين تقلبان ألفا إذا تحركتا مفتوحا ما قبلهما أو في حكمه في اسم ثلاثي أو في فعل ثلاثي أو محمول عليه أو اسم محمول عليهما نحو باب وناب وقام وباع وأقام وأباع واستكان منه خلافا للأكثر لبعد الزيادة ولقولهم استكانة ونحو الإقامة والاستقامة ومقام ومقام بخلاف قول وبيع وطائي وياجل شاذ\nوبخلاف قاول وبايع وقوم وبين وتقوم وتبين وتقاول وتبايع ونحو القود والصيد وأخيلت وأغيلت وأغيمت شاذ\nوصح باب قوي وهوى للإعلالين وباب طوي وحيي لأنه فرعه أو لما يلزم من يقاي ويطاي ويحاي وكثر الإدغام في باب حيي للمثلين وقد يكسر الفاء بخلاف باب قوي لأن الإعلال قبل الإدغام ولذلك قالوا يحيى ويقوى واحواوى يحواوي وارعوى يرعوي فلم يدغموا وجاء احويواء واحوياء ومن قال اشهباب فال احوواء كاقتتال ومن أدغم اقتتالا قال حواء وجاز الإدغام في أحيي واستحيي بخلاف أحيى واستحيى وأما امتناعهم في يحيي ويستحيي فلئلا ينضم ما رفض ضمه ولم يبنوا\nمن باب قوي مثل ضرب ولا شرف كراهة قووت وقووت ونحو القوة والصوة والبو والجو محتمل للإدغام\nوصح باب ما افعله لعدم تصرفه وأفعل محمول عليه أو للبس بالفعل وازدوجوا واجتوروا لأنه بمعنى تفاعلوا وباب اعوار واسواد للبس وعور وسود لأنه بمعناه وما تصرف مما صح صحيح ايضا كأعورته واستعور ومقاول ومبايع وعاور وأسود ومن قال عار قال أعار واستعار وعائر وصح تقوال وتسيار للبس ومقوال ومخياط للبس ومقول ومخيط محذوفان منهما أو بمعناهما وأعل نحو يقوم ويبيع ومقوم ومبيع بغير ذلك للبس ونحو جواد وطويل وغيور للإلباس بفاعل أو بفعل أو لأنه ليس بجار على الفعل ولا موافق ونحو\nالجولان والحيوان والحيدى والصورى للتنبيه بحركته على مسماه والموتان لأنه نقيضه أو لأنه ليس بجار ولاموافق ونحو أدور وأعين للإلباس أو لأنه ليس بجار ولامخالف ونحو جدول وخروع وعليب لمحافظة الإلحاق أو للسكون المحض\nوتقلبان همزة في نحو قائم وبائع المعتل فعله بخلاف نحو عاور ونحو شاك وشاك شاذ وفي نحو جاء قولان قال الخليل مقلوب كالشاكي وقيل على القياس وفي نحو أوائل وبوائع مما وقعتا فيه بعد ألف باب مساجد وقبلها واو أو ياء بخلاف عواوير وطواويس وضياون شاذ وصح عواور وأعل عيائيل لأن الأصل عواوير فحذف وعيائل فأشبع ولم يفعلوه في باب مقاوم ومعايش للفرق بينه وبين باب رسائل وعجائز وصحائف\nوجاء معائش بالهمزة على ضعف والتزم همزة مصائب\nوتقلب ياء فعلى اسما واوا في نحو طوبى وكوسى ولا تقلب في الصفة ولكن يكسر ما قبلها فتسلم الياء نحو مشية حيكى و {قسمة ضيزى} وكذلك باب بيض واختلف في غير\nذلك فقال سيبويه القياس الثاني فنحو مضوفة شاذ عنده ونحو معيشة يجوز أن يكون مفعلة ومفعلة وقال الأخفش القياس الأول فمضوفة قياس عنده ومعيشة مفعلة وإلا لزم معوشة وعليهما لو بني من البيع مثل ترتب لقيل تبيع وتبوع\nوتقلب الواو المكسور ما قبلها في المصادر ياء نحو قياما وعياذا وقيما لإعلال أفعالها وحال حولا كالقود بخلاف مصدر نحو لاوذ وفي نحو جياد وديار ورياح وتير وديم لإعلال المفرد وشذ طيال وصح رواء جمع ريان كراهة إعلالين ونواء جمع ناو وفي نحو رياض وثياب لسكونها في الواحد مع الألف بعدها بخلاف عودة وكوزة وأما ثيرة فشاذ\nوتقلب الواو عينا أو لاما أو غيرهما إذا اجتمعت مع ياء وسكن السابق ياء وتدغم ويكسر ما قبلها إن كان ضمة كسيد وأيام وديار وقيام وقيوم ودلية وطي ومرمي ومسلمي رفعا وجاء لي في جمع ألوى بالكسر والضم وأما ضيون وحيوة ونهو فشاذ وقوله\n(فما أرق النيام إلا سلامها ... )\nأشذ\nوتسكنان وتنقل حركتهما في نحو يقوم ويبيع للبسه بباب يخاف ومفعل ومفعل كذلك ومفعول كذلك نحو مقول ومبيع\nوالمحذوف عند سيبويه واو مفعول وعند الأخفش العين وانقلبت واو مفعول عنده ياء للكسرة فخالفا أصليهما وشذ مشيب ومهوب وكثر نحو مبيوع وقل نحو مصوون وإعلال نحو تلوون ويستحيي قليل\nوتحذفان في نحو قلت وبعت وقلن وبعن ويكسر الأول إن كانت العين ياء أو واوا مكسورة ويضم في غيره ولم يفعلوه في لست لشبهه بالحرف ومن ثم سكنوا الياء وفي نحو قل وبع لأنه عن تقول وتبيع وفي الإقامة والاستقامة ويجوز الحذف في نحو سيد وميت وكينونة وقيلولة\nوفي باب قيل وبيع ثلاث لغات الياء والإشمام والواو فإن اتصل به ما يسكن لامه نحو بعت يا عبد وقلت يا قول فالكسر والإشمام والضم وباب اختير وانقيد مثله فيها بخلاف باب أقيم واستقيم\nوشرط إعلال العين في الاسم غير الثلاثي والجاري على الفعل مما لم يذكر موافقة الفعل حركة وسكونا مع مخالفته بزيادة أو بنية مخصوصتين به فلذلك لو بنيت من البيع مثل مضرب وتحلىء قلت مبيع وتبيع معلا ومثل تضرب قلت تبيع مصححا\nاللام تقلبان ألفا إذا تحركتا وانفتح ما قبلهما إن لم يكن بعدهما موجب للفتح كغزا ورمى ويقوى ويحيى وعصا ورحى\nبخلاف غزوت ورميت وغزونا ورمينا وتخشين وتأبين وغزو ورمي وبخلاف غزوا ورميا وعصوان ورحيان للإلباس واخشيا نحوه لأنه من باب لن يخشيا واخشين لشبهه بذلك بخلاف اخشوا واخشون واخشي واخشين\nوتقلب الواو ياء إذا وقعت مكسورا ما قبلها أو رابعة فصاعدا ولم ينضم ما قبلها كدعي ورضي والغازي وأغزيت وتغزيت واستغزيت ويغزيان ويرضيان بخلاف يدعو ويغزو وقنية وهو ابن عمي دنيا شاذ وطيىء تقلب الياء في باب رضي وبقي ودعي ألفا\nوتقلب الواو طرفا بعد ضمة في كل متمكن ياء فتنقلب الضمة كسرة كما انقلبت في الترامي والتجاري فيصير من باب قاض\nمثل ادل وقلنس بخلاف قلنسوة وقمحدوة وبخلاف العين كالقوباء والخيلاء ولاأثر للمدة الفاصلة في الجمع إلا في الإعراب نحو عتي وجثي ونحو نحو شاذ وقد جاء نحو معدي ومغزي كثيرا والقياس الواو\nوتقلبان همزة إذا وقعتا طرفا بعد ألف زائدة نحو كسائ ورداء بخلاف زاي وثاي ويعتد بتاء التأنيث قياسا نحو شقاوة وسقاية ونحو صلاءة وعظاءة وعباءة شاذ\nوتقلب الياء واوا في فعلى اسما كتقوى وبقوى بخلاف الصفة نحو صديا وريا وتقلب الواو ياء في فعلى اسما كالدنيا والعليا وشذ نحو القصوى وحزوى بخلاف الصفة نحو الغزوى\nولم يفرق في فعلى من الواو نحو دعوى وشهوى ولا في فعلى من الياء نحو الفتيا والقضيا\nوتقلب الياء إذا وقعت بعد همزة بعد ألف في باب مساجد وليس مفردها كذلك ألفا والهمزة ياء نحو مطايا وركايا وخطايا على القولين وصلايا جمع المهموز وغيره وشوايا جمع شاوية بخلاف شواء جمع شائية من شأوت وبخلاف شواء وجواء جمعي شائية وجائية على القولين فيهما وقد جاء أداوى وعلاوى وهراوى مراعاة للمفرد\nوتسكنان في باب يغزو ويرمي مرفوعين والغازي والرامي\nمرفوعا ومجرورا والتحريك في الرفع والجر في الياء شاذ كالسكون في النصب والإثبات فيهما وفي الألف في الجزم\nويحذفان في مثل يغزون ويرمون وترمين واغزن واغزن وارمن وارمن ونحو يد ودم واسم وابن وأخ وأخت ليس بقياس"},{"id":"shafiya:35","bookId":"shafiya","type":"section","seq":35,"chapter":"تعريف التصريف","title":"الإبدال","page":"ج1 ص108","text":"جعل حرف مكان غيره ويعرف باشتقاقه كتراث وأجوه وبقلة استعماله كالثعالي وبكونه فرعا وهو زائد كضويرب وبكونه فرعا وهو أصل كمويه وبلزوم بناء مجهول نحو هراق واصطبر وادراك\nوحروفه أنصت يوم جد طاه زل وقول بعضهم استنجده يوم طال وهم في نقص الصاد والزاي لثبوت صراط وزقر وفي زيادة السين ولو أورد اسمع ورد اذكر واظلم\nفالهمزة من حروف اللين والعين والهاء فمن اللين إعلال لازم في نحو كساء ورداء وقائل وبائع وأواصل وجائز في نحو\nأجوه وأوري وأما نحو دأبة وشأبة والعألم وبأز وشئمة وموقد فشاذ وأباب بحر أشذ وماء شاذ لازم\nوالألف من أختيها والهمزة والهاء فمن أختيها لازم في نحو قال وباع وآل على رأي ونحو يا جل ضعيف وطائي شاذ لازم ومن الهمزة في نحو رأس ومن الهاء في آل على رأي\nوالياء من أختيها ومن الهمزة ومن أحد حرفي المضاعف والنون والعين والباء والسين والثاء فمن أختيها لازم في نحو\nمفاتيح ومفيتيح وميقات وغاز وقيام وحياض وشاذ في نحو حبلى وصيم وصبية وييجل ومن الهمزة نحو ذيب ومن الباقي مسموع كثير في نحو أمليت وقصيت وفي نحو أناسي وأما الضفادي والثعالي والسادي والثالي فضعيف\nوالواو من أختيها ومن الهمزة فمن أختيها لازم في نحو ضوارب وضويرب ورحوي وعصوي وموقن وطوبى وبوطر وبقوى وشاذ ضعيف في هذا أمر ممضو عليه ونهو عن المنكر\nوجباوة ومن الهمزة في نحو جونة وجون\nوالميم من الواو واللام والنون فمن الواو لازم في فم وحده وضعيف في لام التعريف وهي طائية ومن النون لازم في نحو عمبر وشمباء وضعيف في البنام وطامه الله على الخير ومن الباء في بنان مخر وما زلت راتما ومن كثم\nوالنون من الواو واللام شاذ في صنعاني وبهراني وضعيف في لعن\nوالتاء من الواو والياء والسين والباء والصاد فمن الواو والياء لازم في نحو اتعد واتسر على الأفصح وشاذ في نحو اتلجه وفي طست وحده وفي الذعالت ولصت ضعيف\nوالهاء من الهمزة والألف والياء والتاء فمن الهمزة مسموع في هرقت وهرحت وهياك ولهنك وهن فعلت في طيىء وهذا الذي في أذا الذي ومن الألف شاذ في أنه وحيهله وفي مه مستفهما وفي يا هناه على رأي ومن الياء في هذه ومن التاء في باب رحمه وقفا\nواللام من النون والضاد في أصيلال قليل وفي الطجع رديء\nوالطاء من التاء لازم في اصطبر وشاذ في حصط\nوالدال من التاء لازم في نحو ازدجر وادكر وشاذ في نحو فزد واجدمعوا واجدز ودولج\nوالجيم من الياء المشددة في الوقف في نحو فقيمج وهو شاذ ومن غير المشددة في نحو\n(لا هم إن كنت قبلت حجتج ... )\nأشذ ومن نحو\n(حتى إذا ما أمسجت وأمسجا ... )\nأشذ\nوالصاد من السين التي بعدها غين أو خاء أو قاف أو طاء جوازا نحو أصبغ وصلخ ومس صقر وصراط\nوالزاي من السين ووالصاد الواقعتين قبل الدال ساكنتين نحو يزدل وهكذا فزدي أنه\nوقد ضورع بالصاد الزاي دونها وضورع بها متحركة أيضا نحو صدق وصدر والبيان أكثر فيهما ونحو مس زقر كلبية وأجدر وأشدق بالمضارعة قليل"},{"id":"shafiya:36","bookId":"shafiya","type":"section","seq":36,"chapter":"تعريف التصريف","title":"الإدغام","page":"ج1 ص119","text":"أن تأتي بحرفين ساكن فمتحرك من مخرج واحد من غير فصل ويكون في المثلين والمتقاربين\nفالمثلان واجب عند سكون الأول في الهمزتين إلا في نحو سأل والدأث وإلا في الألف لتعذره وإلا في نحو قوول للإلباس وفي نحو تووي ورييا على المختار إذا خفف وفي نحو قالوا وما وفي يوم وعند تحركهما في كلمة ولا إلحاق ولا لبس نحو رد يرد إلا في نحو حيي فإنه جائز وإلا في نحو اقتتل وتتنزل وتتباعد وسيأتي وتنقل حركته إن كان قبله ساكن غير لين نحو يرد وسكون الوقف كالحركة ونحو {مكني}\nويمكنني و {مناسككم} و {ما سلككم} من باب كلمتين وممتنع في الهمزة على الأكثر وفي الألف وعند سكون الثاني لغير الوقف نحو ظللت ورسول الحسن وتميم تدغم في نحو رد ولم يرد وعند الإلحاق واللبس بزنة أخرى نحو قردد وسرر وعند ساكن صحيح قبلهما في كلمتين نحو قرم مالك وحمل قول القراء على الإخفاء وجائز فيما سوى ذلك\nالمتقاربان ونعني بهما ما تقاربا في المخرج أو في صفة تقوم مقامه ومخارج الحروف ستة عشر تقريبا وإلا فلكل مخرج فللهمزة والهاء والألف أقصى الحلق وللعين والحاء وسطه وللغين والخاء أدناه وللقاف أقصى اللسان وما فوقه من الحنك وللكاف منهما ما يليهما وللجيم والشين والياء وسط اللسان وما فوقه من الحنك وللضاد أول إحدى حافتيه وما يليهما من الأضراس وللام ما دون طرف اللسان إلى منتهاه وما فوق ذلك وللراء منهما ما يليهما وللنون منهما ما يليهما وللطاء والدال والتاء طرف اللسان وأصول الثنايا وللصاد والزاي والسين طرف اللسان والثنايا وللظاء والذال والثاء طرف اللسان وطرف الثنايا\nوللفاء باطن الشفة السفلى وطرف الثنايا العليا وللباء والميم والواو ما بين الشفتين\nومخرج المتفرع واضح والفصيح ثمانية همزة بين ثلاثة والنون الخفية نحو عندك وألف الإمالة ولام التفخيم والصاد كالزاي والشين كالجيم\nوأما الصاد كالسين والطاء كالتاء والظاء كالثاء والفاء كالباء والضاد الضعيفة والكاف كالجيم فمستهجنة\nوأما الجيم كالكاف والجيم كالشين فلا يتحقق\nومنها المجهورة والمهموسة ومنها الشديدة والرخوة وما بينهما ومنها المطبقة والمنفتحة ومنها المستعلية والمنخفضة ومنها حروف الذلاقة والمصمتة ومنها حروف القلقة والصفير واللينة والمنحرف والمكرر والهاوي والمهتوت\nفالمجهورة ما ينحصر جري النفس مع تحركه وهي ما عدا حروف ستشحثك خصفه والمهموسة بخلافها ومثلا بققق وككك\nوخالف بعضهم فجعل الضاد والظاء والذال والزاي والعين والغين والياء من المهموسة والكاف والتاء من المجهورة ورأى أن الشدة تؤكد الجهر\nوالشديدة ما ينحصر جري صوته عند إسكانه في مخرجه فلا يجري ويجمعها أجدك قطبت والرخوة بخلافها\nوما بينهما ما لا يتم له الانحصار ولا الجري ويجمعها لم يروعنا ومثلت بالحج والطش والخل\nوالمطبقة ما ينطبق على مخرجه الحنك وهي الصاد والضاد والطاء والظاء والمنفتحة بخلافها\nوالمستعلية ما يرتفع اللسان بها إلى الحنك وهي المطبقة والخاء والغين والقاف والمنخفضة بخلافها\nوحروف الذلاقة ما لا ينفك رباعي أو خماسي عن شيء منها لسهولتها ويجمعها مر بنفل والمصمتة بخلافها لأنه صمت عنها في بناء رباعي أو خماسي منها\nوحروف القلقة ما ينضم إلى الشدة فيها ضغط في الوقف ويجمعها قد طبج\nوحروف الصفير ما يصفر بها وهي الصاد والسين والزاي واللينة حروف اللين\nوالمنحرف اللام لأن اللسان ينحرف به\nوالمكرر الراء لتعثر اللسان به\nوالهاوي الألف لاتساع هواء الصوت به\nوالمهتوت التاء لخفائها\nومتى قصد لإدغام المتقارب فلا بد من قلبه والقياس قلب الأول إلا لعارض في نحو اذبحتودا واذبحاذه وفي جملة من تاء الافتعال لنحوه ولكثرة تغيرها ومحم في معهم ضعيف وست أصله سدس شاذ لازم\nولا ترغم منها في كلمة ما يؤدي إلى لبس بتركيب آخر نحو وطد ووتد وشاة زنماء ومن ثم لم يقولوا وطدا ولا وتدا لما يلزم من ثقل أو لبس بخلاف نحو امحى واطير وجاء ود في وتد في تميم\nولم تدغم حروف ضوي مشفر فيما يقاربها لزيادة صفتها\nونحو سيد ولية إنما أدغما لأن الإعلال صيرهما مثلين وأدغمت النون في اللام والراء لكراهة نبرتها وفي الميم وإن لم يتقاربا لغنتها وفي الواو والياء لإمكان بقائها وقد جاء {لبعض شأنهم} و {اغفر لي} و {نخسف بهم} ولا حروف الصفير في غيرها ولا المطبقة في غيرها من غير إطباق على الأفصح ولا حرف حلق في أدخل منهه إلا الحاء في العين والهاء ومن ثم قالوا فيهما اذبحتودا واذبحاذه"},{"id":"shafiya:37","bookId":"shafiya","type":"section","seq":37,"chapter":"تعريف التصريف","title":"فالهاء في الحاء والعين في الحاء والحاء في الهاء والعين بقلبهما حاءين وجاء {فمن زحزح عن النار} والغين في الخاء والخاء في الغين","page":"ج1 ص126","text":"والقاف في الكاف والكاف في القاف والجيم في الشين\nواللام المعرفة تدغم وجوبا في مثلها وفي ثلاثة عشر وغير المعرفة لازم في نحو {بل ران} وجائز في البواقي\nوالنون الساكنة تدغم وجوبا في حروف يرملون والأفصح إبقاء غنتها في الواو والياء وإذهابها في اللام والراء وتقلب ميما قبل الباء وتخفى في غير حروف الحلق فيكون لها خمس أحوال والمتحركة تدغم جوازا\nوالطاء والدال والتاء والظاء والذال والثاء يدغم بعضها في بعض وفي الصاد والزاي والسين والإطباق في نحو\n{فرطت} إن كان معه إدغام فهو إتيان بطاء أخرى وجمع بين ساكنين بخلاف غنة النون في {من يقول}\nوالصاد والزاي والسين يدغم بعضها في بعض\nوالباء في الميم والفاء\nوقد تدغم تاء افتعل في مثلها فيقال قتل وقتل وعليها مقتلون ومقتلون وقد جاء {مردفين} اتباعا وتدغم الثاء فيها وجوبا على الوجهين نحو اتأر واثأر وتدغم فيها السين شاذا على الشاذ نحو اسمع لامتناع اتمع وتقلب بعد حروف الإطباق طاء\nفتدغم فيها وجوبا في اطلب وجوازا على الوجهين في اظطلم وجاءت الثلاث في\n(ويظلم أحيانا فيظطلم ... )\nوشاذا على الشاذ في نحو اصبر واضرب لامتناع اطبر واطرب وتقلب مع الدال والذال والزاي دالا فتدغم وجوبا في ادان وقويا في ادكر وجاء اذكر واذدكر وضعيفا في ازان لامتناع ادان\nونحو خبط وحصط وفزد وعد في خبطت وحصت وفزت وعدت شاذ\nوقد تدغم تاء نحو تتنزل وتتنابزوا وصلا وليس قبلها ساكن\nصحيح وتاء تفعل وتفاعل فيما يدغم فيه التاء فتجب همزة الوصل ابتداء نحو اطيروا وازينوا واثاقلوا وادارووا ونحو اسطاع مدغما مع بقاء صوت السين نادر"},{"id":"shafiya:38","bookId":"shafiya","type":"section","seq":38,"chapter":"تعريف التصريف","title":"الحذف","page":"ج1 ص130","text":"الحذف الإعلالي والترخيمي تقدم وجاء غيره في تفعل وتفاعل وفي نحو مست وأحست وظلت واسطاع ويسطيع وجاء يستيع وقالوا بلعنبر وعلماء وملماء في بني العنبر وعلى الماء ومن الماء\nوأما نحو يتسع ويتقي فشاذ وعليه جاء\n(تق الله فينا والكتاب الذي تتلو ... )\nبخلاف تخذ يتخذ فإنه أصل واستخذ من استتخذ وقيل أبدل من تاء اتخذ أشذ ونحو تبشروني وتبشريني وإني قد تقدم"},{"id":"shafiya:39","bookId":"shafiya","type":"section","seq":39,"chapter":"تعريف التصريف","title":"وهذه مسائل التمرين","page":"ج1 ص132","text":"معنى قولهم كيف تبني من كذا نحو كذا أي إذا ركبت منها زنتها وعملت ما يقتضيه القياس فكيف تنطق به وقياس قول أبي علي أن تزيد وتحذف ما حذف في الأصل قياسا وقياس آخرين أن تحذف المحذوف قياسا أو غير قياس فمثل محوي من ضرب مضربي وقال أبو علي مضري\nومثل اسم وغد من دعا دعو ودعو لا ادع ولا دع خلافا للآخرين\nومثل صحائف من دعا دعايا باتفاق إذ لا حذف في الأصل\nومثل عنسل من عمل عنمل ومن باع وقال بنيع وقنول بإظهار النون فيهن للإلباس بفعل\nومثل قنفخر من عمل عنمل ومن باع وقال بنيع وقنول بالإظهار للإلباس بعلكد فيهن\nولا يبنى مثل جحنفل من كسرت أو جعلت لرفضهم مثله لما يلزم من ثقل أو لبس\nومثل أبلم من وأيت أوء ومن أويت أو مدغما لوجوب الواو بخلاف تؤوي\nومثل إجرد من وأيت إيء ومن أويت إي فيمن قال أحي ومن قال أحي قال إي\nومثل إوزة من وأيت إيئاة ومن أويت إياة مدغما ومثل اطلخم من وأيت ايأيا ومن أويت ايويا\nوسئل ابو علي عن مثل ما شاء الله من أولق فقال ما ألق الإلاق واللاق على اللفظ والألق على وجه بنى على أنه فوعل\nوأجاب في باسم بإلق أو بألق\nوسألو أبو علي ابن خالويه عن مثل مسطار من آءة فظنه مفعالا وتحير فقال أبو علي مساء فأجاب على أصله وعلى الأكثر مستاء\nوسأل ابن جني ابن خالويه عن مثل كوكب من وأيت مخففا مجموعا جمع السلامة مضافا إلى ياء المتكلم فتحير أيضا فقال ابن جني أوي\nومثل عنكبوت من بعت بيععوت\nومثل اطمأن ابيعع مصححا\nومثل اغدودن من قلت اقوول وقال أبو الحسن اقويل للواوات\nومثل اغدودن اقووول وابيويع مظهرا\nومثل مضروب من القوة مقوي\nومثل عصفور قوي ومن الغزو غزوي\nومثل عضد من قضيت قض\nومثل قذعملة قضية كمعية في التصغير\nومثل قذعميلة قضوية\nومثل حمصيصة قضوية فتقلب كرحوية\nومثل ملكوت قضووت\nومثل جحمرش قضيي ومن حييت حيو\nومثل حلبلاب قضيضاء\nومثل دحرجت من قرأ قرأيت\nومثل سبطر قرأي\nومثل اطمأننت اقرأيأت ومضارعه يقرئي كيقرعيع"},{"id":"shafiya:40","bookId":"shafiya","type":"section","seq":40,"chapter":"تعريف التصريف","title":"الخط","page":"ج1 ص137","text":"الخط تصوير اللفظ بحروف هجائه إلا أسماء الحروف إذا قصد بها المسمى نحو قولك اكتب جيم عين فا را فإنك تكتب هذه الصورة جعفر لأنه مسماها خطا ولفظا ولذلك قال الخليل لما سألهم كيف تنطقون بالجيم من جعفر فقالوا جيم فقال إنما نطقتم بالاسم ولم تنطقوا بالمسؤول عنه والجواب جه لأنه المسمى فإن سمي بها مسمى آخر كتبت كغيرها وفي المصحف على أصلها على الوجهين نحو {يس} و {حم}\nوالأصل في كل كلمة أن تكتب بصورة لفظها بتقدير الابتداء بها والوقوف عليها فمن ثم كتب نحو ره زيدا وقه زيدا بالهاء ومثل مه أنت ومجيء مه جئت بالهاء أيضا بخلاف الجار نحو حتام وإلام وعلام لشدة الاتصال بالحروف ومن ثم كتبت معها بألفات وكتب مم وعم بغير نون فإن قصدت إلى الهاء كتبتها ورجعت الياء وغيرها إن شئت\nومن ثم كتب أنا زيد بالألف ومنه {لكن هو الله}\nومن ثم كتب تاء التأنيث في نحو رحمة وقمحة هاء وفيمن وقف بالتاء تاء بخلاف أخت وبنت وباب قائمات وباب قامت هند\nومن ثم كتب المنون المنصوب بالألف وغيره بالحذف وإذا بالألف على الأكثر واضربا كذلك وكان قياس اضربن بواو وألف\nواضربن بياء وهل تضربن بواو ونون وهل تضربن بياء ونون ولكنهم كتبوه على لفظه لعسر تبينه أو لعدم تبين قصدها وقد يجرى اضربن مجراه\nومن ثم كتب باب قاض بغير ياء وباب القاضي بالياء على الأفصح فيهما\nومن ثم كتب نحو بزيد ولزيد وكزيد متصلا لأنه لا يوقف عليه وكتب نحو منك ومنكم وضربكم متصلا لأنه لا يبتدأ به\nوالنظر بعد ذلك فيما لا صورة له تخصه وفيما خولف بوصل أو زيادة أو نقص أو بدل\nالأول الهمزة وهو أول ووسط وآخر\nالأول ألف مطلقا نحو أحد وأحد وإبل\nوالوسط إما ساكن فيكتب بحرف حركة ما قبله مثل يأكل ويؤمن وبئس وإما متحرك قبله ساكن فيكتب بحرف حركته مثل يسأل ويلؤم ويشئم ومنهم من يحذفها إن كان تخفيفها بالنقل\nأو الإدغام ومنهم من يحذف المفتوحة فقط والأكثر على حذف المفتوحة بعد الألف نحو ساءل ومنهم من يحذفها في الجميع وإما متحرك وقبله متحرك فيكتب على نحو ما يسهل فلذلك كتب نحو مؤجل بالواو ونحو فئة بالياء وكتب نحو سأل ولؤم ويئس ومن مقرئك ورؤوس بحرف حركته وجاء في سئل ويقرئك القولان\nوالآخر إن كان ما قبله ساكنا حذف نحو خبأ وخبء وخبء وإن كان متحركا كتب بحرف حركة ما قبله كيف كان مثل قرأ ويقرىء وردؤ ولم يقرأ ولم يقرىء ولم يردؤ\nوالطرف الذي لا يوقف عليه لاتصال غيره كالوسط نحو جزأك وجزؤك وجزئك ونحو رداءك ورداؤك وردائك ونحو\nيقرؤه ويقرئك إلا في نحو مقروءة بخلاف الأول المتصل نحو بأحد ولأحد وكأحد بخلاف لئلا لكثرته وكراهة صورته وبخلاف لئن لكثرته\nوكل همزة بعدها حرف مد كصورتها تحذف نحو خطأ في النصب ومستهزءون ومستهزءين وقد تكتب بالياء بخلاف قرأا ويقرأان للبس وبخلاف مستهزئين في المثنى لعدم المد وبخلاف نحو ردائي ونحوه في الأكثر لمغايرة الصورة أو للفتح الأصلي وبخلاف نحو حنائي في الأكثر للمغايرة والتشديد وبخلاف لم تقرئي للمغايرة واللبس\nوأما الوصل فقد وصلوا الحروف وشبهها بما الحرفية نحو {إنما إلهكم الله} وأينما تكن أكن وكلما أتيتني أكرمتك بخلاف إن ما عندي حسن وأين ما وعدتني وكل ما عندي حسن وكذلك من ما\nوعن ما في الوجهين وقد تكتبان متصلتين مطلقا لوجوب الإدغام ولم يصلوا متى لما يلزم من تغيير الياء ووصلوا أن الناصبة للفعل مع لا بخلاف المخففة نحو علمت أن لا يقوم ووصلوا إن الشرطية ب لا وما نحو {إلا تفعلوه} {وإما تخافن} وحذفت النون في الجميع لتأكيد الاتصال ووصلوا يومئذ وحينئذ في مذهب البناء فمن ثم كتبت بالهمزه ياء وكتبوا نحو الرجل على المذهبين متصلا لأن الهمزة كالعدم أو اختصارا للكثرة\nوأما الزيادة فإنهم زادوا بعد واو الجمع المتطرفة في الفعل ألفا نحو أكلوا وشربوا فرقا بينها وبين واو العطف بخلاف نحو يدعو ويغزو ومن ثم كتب ضربوا هم في التأكيد بألف وفي المفعول بغير ألف ومنهم من يكتبها في نحو شاربوا الماء ومنهم من يحذفها في الجميع وزادوا في مائة ألفا فرقا بينها وبين منه وألحقوا المثنى به بخلاف الجمع وزادوا في عمرو واوا فرقا بينه وبين عمر مع الكثرة ومن ثم لم يزيدوه في النصب وزادوا في أولئك واوا\nفرقا بينه وبين إليك وأجري أولاء عليه وزادوا في أولى واوا فرقا بينها وبين إلى وأجري أولو عليه وأما النقص فإنهم كتبوا كل مشدد من كلمة حرفا واحدا نحو شد ومد وادكر وأجري نحو فتت مجراه بخلاف نحو وعدت واجبهه وبخلاف لام التعريف مطلقا نحو اللحم والرجل لكونهما كلمتين ولكثرة اللبس بخلاف الذي والتي والذين لكونها لا تنفصل ونحو اللذين في التثنية بلامين للفرق وحمل اللتين عليه وكذلك اللاؤون وأخواته ونحو مم وعم وإما وإلا ليس بقياس ونقصوا من بسم الله الرحمن الرحيم الألف لكثرته بخلاف باسم الله وباسم ربك ونحوه وكذا الالف من اسم الله الرحمن مطلقا ونقصوا من نحو للرجل وللدار جرا وابتداء الألف لئلا يلتبس بالنفي بخلاف بالرجل ونحوه ونقصوا مع الألف اللام مما في أوله لام نحو للحم وللبن كراهية اجتماع اللامات ونقصوا من نحو أبنك بار في الاستفهام\nو {أصطفى البنات} ألف الوصل وجاء في الرجل الأمران ونقصوا من ابن إذا وقع صفة بين علمين ألفه مثل هذا زيد بن عمرو بخلاف زيد ابن عمرو وبخلاف المثنى ونقصوا ألف ها مع اسم الإشارة نحو هذا وهذه وهذان وهؤلاء بخلاف هاتا وهاتي لقلته فإن جاءت الكاف ردت نحو ها ذاك وها ذانك لاتصال الكاف ونقصوا الألف من ذلك وأولئك ومن الثلث والثلثين ومن لكن ولكن ونقص كثير الواو من داود والألف من إبراهيم وإسماعيل وإسحق وبعضهم الألف من عثمان وسليمان ومعاوية\nوأما البدل فإنهم كتبوا كل ألف رابعة فصاعدا في اسم أو فعل ياء إلا فيما قبلها ياء إلا في يحيى وربي علما وأما الثالثة\nفإن كانت عن ياء كتبت ياء وإلا فالألف ومنهم من يكتب الباب كله بالألف وعلى كتبه بالياء فإن كان منونا فالمختار أنه كذلك وهو قياس المبرد وقياس المازني بالألف وقياس سيبويه المنصوب بالألف وما سواه بياء ويتعرف الياء من الواو بالتثنية نحو فتيان وعصوان وبالجمع نحو الفتيات والقنوات وبالمرة نحو رمية وغزوة وبالنوع نحو رمية وغزوة وبرد الفعل إلى نفسك نحو رميت وغزوت وبالمضارع نحو يرمي ويغزو وبكون الفاء واوا نحو وعى وبكون العين واوا نحو شوى إلا ما شذ نحو القوا والصوا فإن جهل فإن أميلت فالياء نحو متى وإلا فالألف وإنما كتبوا لدى بالياء لقولهم لديك وكلا يكتب\nعلى الوجهين لاحتماله وأما الحروف فلم يكتب منها بالياء غير بلى وإلى وعلى وحتى"},{"id":"shafiya:41","bookId":"shafiya","type":"section","seq":41,"chapter":"تعريف التصريف","title":"1-","page":"ج1 ص147","text":"(الحمد لله الذي يصرف ... بلطفه الرياح حين تعصف)"},{"id":"shafiya:42","bookId":"shafiya","type":"section","seq":42,"chapter":"تعريف التصريف","title":"2-","page":"ج1 ص147","text":"(ما صرفت أمثلة المباني ... وصرحت بنطقها المعاني)"},{"id":"shafiya:43","bookId":"shafiya","type":"section","seq":43,"chapter":"تعريف التصريف","title":"3-","page":"ج1 ص147","text":"(ثم الصلاة والسلام العالي ... على النبي المصطفى والآل)"},{"id":"shafiya:44","bookId":"shafiya","type":"section","seq":44,"chapter":"تعريف التصريف","title":"4-","page":"ج1 ص147","text":"(وبعد فاحفظن صرف الشافية ... وسمها منظومة بالوافية)"},{"id":"shafiya:45","bookId":"shafiya","type":"section","seq":45,"chapter":"تعريف التصريف","title":"5-","page":"ج1 ص147","text":"(واغن بها يا ولدي الحفيا ... لا زلت في كرامة مهديا)"},{"id":"shafiya:46","bookId":"shafiya","type":"section","seq":46,"chapter":"تعريف التصريف","title":"6-","page":"ج1 ص147","text":"(الصرف علم بأصول مفهم ... بهن أحوال مباني الكلم)"},{"id":"shafiya:47","bookId":"shafiya","type":"section","seq":47,"chapter":"تعريف التصريف","title":"7-","page":"ج1 ص147","text":"(والاسم أنواع هي الثلاثي ... ثم الرباعي مع الخماسي)"},{"id":"shafiya:48","bookId":"shafiya","type":"section","seq":48,"chapter":"تعريف التصريف","title":"8-","page":"ج1 ص147","text":"(والفعل نوعان على السماع ... هما الثلاثي مع الرباعي)"},{"id":"shafiya:49","bookId":"shafiya","type":"section","seq":49,"chapter":"تعريف التصريف","title":"9-","page":"ج1 ص147","text":"(وتوزن الأصول في الكلام ... بالفاء ثم العين ثم اللام)"},{"id":"shafiya:50","bookId":"shafiya","type":"section","seq":50,"chapter":"تعريف التصريف","title":"10-","page":"ج1 ص147","text":"(وزائد بلفظه والمبدل ... من تاء الافتعال تاء يجعل)"},{"id":"shafiya:51","bookId":"shafiya","type":"section","seq":51,"chapter":"تعريف التصريف","title":"11-","page":"ج1 ص147","text":"(وزائد كرر للتضعيف ... أو غيره يوزن كالرديف)"},{"id":"shafiya:52","bookId":"shafiya","type":"section","seq":52,"chapter":"تعريف التصريف","title":"12-","page":"ج1 ص147","text":"(وإن أتى من أحرف الزياده ... إلا بأمر أثبت ازدياده)"},{"id":"shafiya:53","bookId":"shafiya","type":"section","seq":53,"chapter":"تعريف التصريف","title":"13-","page":"ص0","text":"(من ثم حلتيت بفعليل وزن ... كذاك سحنون بفعلول قرن)"},{"id":"shafiya:54","bookId":"shafiya","type":"section","seq":54,"chapter":"تعريف التصريف","title":"14-","page":"ص0","text":"(وليس فعلونا كذا عثنون ... لما يجي ولم يجىء فعلون)"},{"id":"shafiya:55","bookId":"shafiya","type":"section","seq":55,"chapter":"تعريف التصريف","title":"15-","page":"ص0","text":"(والفتح إن يصح في سحنون ... فذاك فعلون كما حمدون)"},{"id":"shafiya:56","bookId":"shafiya","type":"section","seq":56,"chapter":"تعريف التصريف","title":"16-","page":"ص0","text":"(ووزنه يختص بالأعلام ... لندرة الفعلول في الكلام)"},{"id":"shafiya:57","bookId":"shafiya","type":"section","seq":57,"chapter":"تعريف التصريف","title":"17-","page":"ص0","text":"(وذاك صعفوق وخرنوب ضعف ... وضمه اثبت ذكرا في الصحف)"},{"id":"shafiya:58","bookId":"shafiya","type":"section","seq":58,"chapter":"تعريف التصريف","title":"18-","page":"ص0","text":"(سمنان فعلان على ما قالوا ... ونادر في وزنهم خزعال)"},{"id":"shafiya:59","bookId":"shafiya","type":"section","seq":59,"chapter":"تعريف التصريف","title":"19-","page":"ص0","text":"(فعلان بطنان وقرطاس ضعف ... مع أنه نقيض ظهران يحف)"},{"id":"shafiya:60","bookId":"shafiya","type":"section","seq":60,"chapter":"تعريف التصريف","title":"20-","page":"ص0","text":"(إن يك في الموزون قلب يبدل ... ميزانه فآدر كأعفل)"},{"id":"shafiya:61","bookId":"shafiya","type":"section","seq":61,"chapter":"تعريف التصريف","title":"21-","page":"ص0","text":"(ويعرف القلب بأصله كما ... ناء يناء مع نأي أحكما)"},{"id":"shafiya:62","bookId":"shafiya","type":"section","seq":62,"chapter":"تعريف التصريف","title":"22-","page":"ص0","text":"(وباشتقاقات له كالحادي ... والجاه والقسي باستناد)"},{"id":"shafiya:63","bookId":"shafiya","type":"section","seq":63,"chapter":"تعريف التصريف","title":"23-","page":"ص0","text":"(وصحة المقلوب مثل أيسا ... وقلة استعماله مستأنسا)"},{"id":"shafiya:64","bookId":"shafiya","type":"section","seq":64,"chapter":"تعريف التصريف","title":"24-","page":"ص0","text":"(كمثل آرام مع الأرام ... وآدر مع أدور تسامي)"},{"id":"shafiya:65","bookId":"shafiya","type":"section","seq":65,"chapter":"تعريف التصريف","title":"25-","page":"ص0","text":"(وباجتماع الهمزتين إن فقد ... عند الخليل نحو جاء فانتقد)"},{"id":"shafiya:66","bookId":"shafiya","type":"section","seq":66,"chapter":"تعريف التصريف","title":"26-","page":"ص0","text":"(وبامتناع الصرف من غير سبب ... على الأصح نحو أشياء تؤب)"},{"id":"shafiya:67","bookId":"shafiya","type":"section","seq":67,"chapter":"تعريف التصريف","title":"27-","page":"ص0","text":"(فإنها توزن باللفعاء ... وهي كأفعال لدى الكسائي)"},{"id":"shafiya:68","bookId":"shafiya","type":"section","seq":68,"chapter":"تعريف التصريف","title":"28-","page":"ص0","text":"(وقال في وزانه الفراء ... أفعاء والبناء أفعلاء)"},{"id":"shafiya:69","bookId":"shafiya","type":"section","seq":69,"chapter":"تعريف التصريف","title":"29-","page":"ص0","text":"(والحذف كالقلب فقل فل مفهما ... إلا إذا بين أصل فيهما)"},{"id":"shafiya:70","bookId":"shafiya","type":"section","seq":70,"chapter":"تعريف التصريف","title":"30-","page":"ص0","text":"(وانقسم الأصول عند الحل ... إلى صحيح وإلى معتل)"},{"id":"shafiya:71","bookId":"shafiya","type":"section","seq":71,"chapter":"تعريف التصريف","title":"31-","page":"ص0","text":"(معتلهم ما فيه حرف علة ... صحيحهم خلافه محله)"},{"id":"shafiya:72","bookId":"shafiya","type":"section","seq":72,"chapter":"تعريف التصريف","title":"32-","page":"ص0","text":"(ما عتل بالفاء هو المثال ... مثاله اليسار والوصال)"},{"id":"shafiya:73","bookId":"shafiya","type":"section","seq":73,"chapter":"تعريف التصريف","title":"33-","page":"ص0","text":"(معتل عينه يسمى أجوفا ... وذا ثلاثة كطفت بالصفا)"},{"id":"shafiya:74","bookId":"shafiya","type":"section","seq":74,"chapter":"تعريف التصريف","title":"34-","page":"ص0","text":"(ما اعتل لاما كحميت مربعه ... سمي منقوصا كذا ذا الأربعة)"},{"id":"shafiya:75","bookId":"shafiya","type":"section","seq":75,"chapter":"تعريف التصريف","title":"35-","page":"ص0","text":"(بالفاء والعين لفيف قرنا ... كذاك بالعين ولام فاقرنا)"},{"id":"shafiya:76","bookId":"shafiya","type":"section","seq":76,"chapter":"تعريف التصريف","title":"36-","page":"ص0","text":"(بالفاء واللام لفيف فرقا ... مثل وقى الله التقي ما اتقى)"},{"id":"shafiya:77","bookId":"shafiya","type":"section","seq":77,"chapter":"تعريف التصريف","title":"37-","page":"ص0","text":"(لاسم مجرد ثلاثي جرى ... عشرة من جملة اثني عشرا)"},{"id":"shafiya:78","bookId":"shafiya","type":"section","seq":78,"chapter":"تعريف التصريف","title":"38-","page":"ص0","text":"(أسقط منها فعل مثل فعل ... والدئل النادر منقولا جعل)"},{"id":"shafiya:79","bookId":"shafiya","type":"section","seq":79,"chapter":"تعريف التصريف","title":"39-","page":"ص0","text":"(وإن يحقق حبك يحمل على ... تداخل في اللغتين قد تلا)"},{"id":"shafiya:80","bookId":"shafiya","type":"section","seq":80,"chapter":"تعريف التصريف","title":"40-","page":"ص0","text":"(أمثلة العشرة فلس وذهب ... ذو كتف ذو عضد حبر عنب)"},{"id":"shafiya:81","bookId":"shafiya","type":"section","seq":81,"chapter":"تعريف التصريف","title":"41-","page":"ص0","text":"(ذو إبل قفل وبعده صرد ... ذو عنق ونقل بعض قد ورد)"},{"id":"shafiya:82","bookId":"shafiya","type":"section","seq":82,"chapter":"تعريف التصريف","title":"42-","page":"ص0","text":"(في فعل ثانية من حلق أخذ ... كفخذ فخذ وفخذ وفخذ)"},{"id":"shafiya:83","bookId":"shafiya","type":"section","seq":83,"chapter":"تعريف التصريف","title":"43-","page":"ص0","text":"(كذلك الفعل كقولنا شهد ... فيه أتى شهد وشهد مع شهد)"},{"id":"shafiya:84","bookId":"shafiya","type":"section","seq":84,"chapter":"تعريف التصريف","title":"44-","page":"ص0","text":"(كتف وكتف جاء في مثل كتف ... في عضد ونحوه عضد عرف)"},{"id":"shafiya:85","bookId":"shafiya","type":"section","seq":85,"chapter":"تعريف التصريف","title":"45-","page":"ص0","text":"(في عنق عنق أتى وفي إبل ... أو بلز إبل وبلز قد نقل)"},{"id":"shafiya:86","bookId":"shafiya","type":"section","seq":86,"chapter":"تعريف التصريف","title":"46-","page":"ص0","text":"(في نحو قفل قفل جاز على ... رأي فضم سين عسر نقلا)"},{"id":"shafiya:87","bookId":"shafiya","type":"section","seq":87,"chapter":"تعريف التصريف","title":"47-","page":"ص0","text":"(وللرباعي قمطر علقم ... وزبرج وبرثن ودرهم)"},{"id":"shafiya:88","bookId":"shafiya","type":"section","seq":88,"chapter":"تعريف التصريف","title":"48-","page":"ص0","text":"(وأثبت الأخفش نحو جخدب ... كما حكى الفراء فتح طحلب)"},{"id":"shafiya:89","bookId":"shafiya","type":"section","seq":89,"chapter":"تعريف التصريف","title":"49-","page":"ص0","text":"(ومن توالي الحركات الجندل ... رد إلى جنادل ليعتدل)"},{"id":"shafiya:90","bookId":"shafiya","type":"section","seq":90,"chapter":"تعريف التصريف","title":"50-","page":"ص0","text":"(وهكذا من التوالي العلبط ... ضم إلى علابط ليرتبط)"},{"id":"shafiya:91","bookId":"shafiya","type":"section","seq":91,"chapter":"تعريف التصريف","title":"أبنية الاسم الخماسي","page":"ص0","text":"المجرد"},{"id":"shafiya:92","bookId":"shafiya","type":"section","seq":92,"chapter":"تعريف التصريف","title":"51-","page":"ص0","text":"(وللخماسي أتى سفرجل ... قرطعبهم جحمرش قذعمل)\nالمزيد فيه"},{"id":"shafiya:93","bookId":"shafiya","type":"section","seq":93,"chapter":"تعريف التصريف","title":"52-","page":"ص0","text":"(أبنية المزيد فيه تكثر ... وفي الخماسي قليل يحصر)"},{"id":"shafiya:94","bookId":"shafiya","type":"section","seq":94,"chapter":"تعريف التصريف","title":"53-","page":"ص0","text":"(من عضرفوط وخزعبيل ترى ... وقرطبوس بعده قبعثرى)"},{"id":"shafiya:95","bookId":"shafiya","type":"section","seq":95,"chapter":"تعريف التصريف","title":"54-","page":"ص0","text":"(وخندريس منه عند الأكثر ... فالنون أصلي لديهم فابصر)"},{"id":"shafiya:96","bookId":"shafiya","type":"section","seq":96,"chapter":"تعريف التصريف","title":"55-","page":"ص0","text":"(وليعلمن أن حال الأبنية ... إما لحاجة إليها مفضيه)"},{"id":"shafiya:97","bookId":"shafiya","type":"section","seq":97,"chapter":"تعريف التصريف","title":"56-","page":"ص0","text":"(كالماض والمضارع المعمول ... والأمر والفاعل والمفعول)"},{"id":"shafiya:98","bookId":"shafiya","type":"section","seq":98,"chapter":"تعريف التصريف","title":"57-","page":"ص0","text":"(وأفعل التفضيل في التفاضل ... والصفة المشبهة اسم الفاعل)"},{"id":"shafiya:99","bookId":"shafiya","type":"section","seq":99,"chapter":"تعريف التصريف","title":"58-","page":"ص0","text":"(والمصدر المنشأ للمباني ... واسم زمان الفعل والمكان)"},{"id":"shafiya:100","bookId":"shafiya","type":"section","seq":100,"chapter":"تعريف التصريف","title":"59-","page":"ص0","text":"(وآلة الفعل وما يصغر ... كذاك منسوب وجمع يذكر)"},{"id":"shafiya:101","bookId":"shafiya","type":"section","seq":101,"chapter":"تعريف التصريف","title":"60-","page":"ص0","text":"(ثم التقاء الساكنين مردفا ... والابتداء ثم وقف فقفا)"},{"id":"shafiya:102","bookId":"shafiya","type":"section","seq":102,"chapter":"تعريف التصريف","title":"61-","page":"ص0","text":"(أوسعة في منطق مراده ... كالقصر والمد وذي الزياده)"},{"id":"shafiya:103","bookId":"shafiya","type":"section","seq":103,"chapter":"تعريف التصريف","title":"62-","page":"ص0","text":"(أو لجناس كإمالة كفى ... أو دفع ثقل مثل همز خففا)"},{"id":"shafiya:104","bookId":"shafiya","type":"section","seq":104,"chapter":"تعريف التصريف","title":"63-","page":"ص0","text":"(كذاك في الإعلال والإبدال ... كمثل إدغام وحذف تال)"},{"id":"shafiya:105","bookId":"shafiya","type":"section","seq":105,"chapter":"تعريف التصريف","title":"أبنية الفعل الماضي","page":"ص0","text":"المجرد"},{"id":"shafiya:106","bookId":"shafiya","type":"section","seq":106,"chapter":"تعريف التصريف","title":"64-","page":"ص0","text":"(الماض للمجرد الثلاثي ... أبنية تحصر في ثلاث)"},{"id":"shafiya:107","bookId":"shafiya","type":"section","seq":107,"chapter":"تعريف التصريف","title":"65-","page":"ص0","text":"(فعل أو فعل ثم فعلا ... ويلزم الثالث مثل سهلا)\nالمزيد فيه"},{"id":"shafiya:108","bookId":"shafiya","type":"section","seq":108,"chapter":"تعريف التصريف","title":"66-","page":"ص0","text":"(وللمزيد فيه من ماض أتى ... خمس وعشرون بناء ثبتا)"},{"id":"shafiya:109","bookId":"shafiya","type":"section","seq":109,"chapter":"تعريف التصريف","title":"67-","page":"ص0","text":"(فملحق في وزنه بفعللا ... كشملل الشائب ثم حوقلا)"},{"id":"shafiya:110","bookId":"shafiya","type":"section","seq":110,"chapter":"تعريف التصريف","title":"68-","page":"ص0","text":"(قلنس قلسى لابسا وبيطرا ... وهكذا الحق فيه جهورا)"},{"id":"shafiya:111","bookId":"shafiya","type":"section","seq":111,"chapter":"تعريف التصريف","title":"69-","page":"ص0","text":"(وملحق بالتاء من تجلببا ... ترهوك المرء كما تجوربا)"},{"id":"shafiya:112","bookId":"shafiya","type":"section","seq":112,"chapter":"تعريف التصريف","title":"70-","page":"ص0","text":"(تغافل الساكت إذ تشيطنا ... تكلم الصامت إذ تمسكنا)"},{"id":"shafiya:113","bookId":"shafiya","type":"section","seq":113,"chapter":"تعريف التصريف","title":"71-","page":"ص0","text":"(وملحق موازن لاحرنجما ... كاقعنسس اسلنقى لضعف أحجما)"},{"id":"shafiya:114","bookId":"shafiya","type":"section","seq":114,"chapter":"تعريف التصريف","title":"72-","page":"ص0","text":"(وغير ملحق كمثل أخرجا ... وقاتل المقبل ثم فرجا)"},{"id":"shafiya:115","bookId":"shafiya","type":"section","seq":115,"chapter":"تعريف التصريف","title":"73-","page":"ص0","text":"(وانطلق المرء به واجتمعا ... واستخرج اشهب وبالمد معا)"},{"id":"shafiya:116","bookId":"shafiya","type":"section","seq":116,"chapter":"تعريف التصريف","title":"74-","page":"ص0","text":"(واعلوط البعير ثم اغدودنا ... فهذه خمس وعشرون بنا)"},{"id":"shafiya:117","bookId":"shafiya","type":"section","seq":117,"chapter":"تعريف التصريف","title":"75-","page":"ص0","text":"(والمد في استكان بالقياس ... إن يك من كان بلا التباس)"},{"id":"shafiya:118","bookId":"shafiya","type":"section","seq":118,"chapter":"تعريف التصريف","title":"76-","page":"ص0","text":"(وإن يكن صيغ من السكون ... فمده شذ عن القانون)"},{"id":"shafiya:119","bookId":"shafiya","type":"section","seq":119,"chapter":"تعريف التصريف","title":"معاني الصيغ","page":"ج2 ص20","text":"معاني فعل"},{"id":"shafiya:120","bookId":"shafiya","type":"section","seq":120,"chapter":"تعريف التصريف","title":"77-","page":"ج2 ص20","text":"(أما المعاني فمعاني فعلا ... كثيرة كما فشا مستعملا)\nباب المغالبة"},{"id":"shafiya:121","bookId":"shafiya","type":"section","seq":121,"chapter":"تعريف التصريف","title":"78-","page":"ج2 ص20","text":"(وباب ما غالبت حين تفعله ... يبنى على فعلته فأفعله)"},{"id":"shafiya:122","bookId":"shafiya","type":"section","seq":122,"chapter":"تعريف التصريف","title":"79-","page":"ج2 ص20","text":"(في غير أمثال يسرت أو أعد ... أوبعت أو رميت فالكسر يرد)"},{"id":"shafiya:123","bookId":"shafiya","type":"section","seq":123,"chapter":"تعريف التصريف","title":"80-","page":"ج2 ص20","text":"(والفتح في شاعرته فأشعره ... عن الكسائي لعين تبصره)\nمعاني فعل"},{"id":"shafiya:124","bookId":"shafiya","type":"section","seq":124,"chapter":"تعريف التصريف","title":"81-","page":"ج2 ص20","text":"(في فعل الأحزان والأضداد ... شاعت كذا الأسقام إذ تفاد)"},{"id":"shafiya:125","bookId":"shafiya","type":"section","seq":125,"chapter":"تعريف التصريف","title":"2-","page":"ج2 ص20","text":"(وجاء مجموع حلى الأبدان ... عليه كالعيوب والألوان)"},{"id":"shafiya:126","bookId":"shafiya","type":"section","seq":126,"chapter":"تعريف التصريف","title":"3-","page":"ج2 ص20","text":"(وقد أتى كسرا وضما عجما ... سمرت لزنا وسعيد أدما)"},{"id":"shafiya:127","bookId":"shafiya","type":"section","seq":127,"chapter":"تعريف التصريف","title":"4-","page":"ج2 ص20","text":"(عجفت من سقم وزيد حمقا ... رعنت من عجب وعمرو خرقا)\nمعاني فعل"},{"id":"shafiya:128","bookId":"shafiya","type":"section","seq":128,"chapter":"تعريف التصريف","title":"85-","page":"ج2 ص20","text":"(في فعل الفعل الطبيعي حتم ... كالحسن والقبح فمن ثم لزم)"},{"id":"shafiya:129","bookId":"shafiya","type":"section","seq":129,"chapter":"تعريف التصريف","title":"6-","page":"ج2 ص20","text":"(وشذ فيه رحبتك الدار ... أي بك أو ضمنه ما تختار)"},{"id":"shafiya:130","bookId":"shafiya","type":"section","seq":130,"chapter":"تعريف التصريف","title":"7-","page":"ج2 ص20","text":"(والضم في قلت لواو حذفا ... كالكسر في بعت لياء عرفا)"},{"id":"shafiya:131","bookId":"shafiya","type":"section","seq":131,"chapter":"تعريف التصريف","title":"8-","page":"ج2 ص20","text":"(وليس للنقل على الصواب ... ولاحظوا في خفت كشف الباب)\nمعاني أفعل"},{"id":"shafiya:132","bookId":"shafiya","type":"section","seq":132,"chapter":"تعريف التصريف","title":"89-","page":"ج2 ص20","text":"(افعل في غالبه للتعديه ... كمثل أجلس من أراك الأردية)"},{"id":"shafiya:133","bookId":"shafiya","type":"section","seq":133,"chapter":"تعريف التصريف","title":"90-","page":"ج2 ص20","text":"(وصيغ للتعريض في المعدى ... مثل ابعت العبد إذ تعدى)"},{"id":"shafiya:134","bookId":"shafiya","type":"section","seq":134,"chapter":"تعريف التصريف","title":"91-","page":"ج2 ص20","text":"(وهكذا يأتي لصار ذا كذا ... نحو أغدت إبلي من الأذى)"},{"id":"shafiya:135","bookId":"shafiya","type":"section","seq":135,"chapter":"تعريف التصريف","title":"92-","page":"ج2 ص20","text":"(ومنه قد أحصد زرع البلد ... وأصرم النخل به فليقصد)"},{"id":"shafiya:136","bookId":"shafiya","type":"section","seq":136,"chapter":"تعريف التصريف","title":"93-","page":"ج2 ص20","text":"(كذا لوجدانك إياه على ... وصف كأحمدت وأبخلت العلا)"},{"id":"shafiya:137","bookId":"shafiya","type":"section","seq":137,"chapter":"تعريف التصريف","title":"94-","page":"ج2 ص21","text":"(وسيق للسلب كأشكيت الفتى ... ومثل قلته أقلته أتى)\nمعاني فعل"},{"id":"shafiya:138","bookId":"shafiya","type":"section","seq":138,"chapter":"تعريف التصريف","title":"95-","page":"ج2 ص21","text":"(فعل في الغالب للتكثير ... كفتح الأبواب للتعمير)"},{"id":"shafiya:139","bookId":"shafiya","type":"section","seq":139,"chapter":"تعريف التصريف","title":"96-","page":"ج2 ص21","text":"(قطعت جولت وطوفت كذا ... وموتت أنعامهم فليؤخذا)"},{"id":"shafiya:140","bookId":"shafiya","type":"section","seq":140,"chapter":"تعريف التصريف","title":"97-","page":"ج2 ص21","text":"(وللتعدي نحو فرحت التقي ... ومنه فسقت المنافق الشقي)"},{"id":"shafiya:141","bookId":"shafiya","type":"section","seq":141,"chapter":"تعريف التصريف","title":"98-","page":"ج2 ص21","text":"(للسلب في جلدته قد عهدا ... زيلته كزلته قد وردا)\nمعاني فاعل"},{"id":"shafiya:142","bookId":"shafiya","type":"section","seq":142,"chapter":"تعريف التصريف","title":"99-","page":"ج2 ص21","text":"(ينسب في فاعل أصله إلى ... مشارك لغيره مسجلا)"},{"id":"shafiya:143","bookId":"shafiya","type":"section","seq":143,"chapter":"تعريف التصريف","title":"100-","page":"ج2 ص21","text":"(فعكسه يلزم بالتضمن ... كنحو باحثت أولي التفطن)"},{"id":"shafiya:144","bookId":"shafiya","type":"section","seq":144,"chapter":"تعريف التصريف","title":"101-","page":"ج2 ص21","text":"(لذا يعدي الفعل باللزوم ... كمثل كارمت أبا مخزوم)"},{"id":"shafiya:145","bookId":"shafiya","type":"section","seq":145,"chapter":"تعريف التصريف","title":"102-","page":"ج2 ص21","text":"(وإن تعدى للذي ما شاركه ... عدى لاثنين على المشاركه)"},{"id":"shafiya:146","bookId":"shafiya","type":"section","seq":146,"chapter":"تعريف التصريف","title":"103-","page":"ج2 ص21","text":"(كنحو جاذبت أخي الكتابا ... لا مثل شاتمت الذي أجابا)"},{"id":"shafiya:147","bookId":"shafiya","type":"section","seq":147,"chapter":"تعريف التصريف","title":"104-","page":"ج2 ص21","text":"(وربما جاء بمعنى فعلا ... كمثل ضاعفت ومعنى فعلا)\nمعاني تفاعل"},{"id":"shafiya:148","bookId":"shafiya","type":"section","seq":148,"chapter":"تعريف التصريف","title":"105-","page":"ج2 ص21","text":"(واشترك الأمران في تفاعلا ... مصرحا كقولنا تبادلا)"},{"id":"shafiya:149","bookId":"shafiya","type":"section","seq":149,"chapter":"تعريف التصريف","title":"106-","page":"ج2 ص21","text":"(من ثم هذا الباب في المشاكله ... ينقص مفعولا عن المفاعلة)"},{"id":"shafiya:150","bookId":"shafiya","type":"section","seq":150,"chapter":"تعريف التصريف","title":"107-","page":"ج2 ص21","text":"(وجاء في إظهار أمر انتفى ... نحو تجاهلت بأمر عرفا)"},{"id":"shafiya:151","bookId":"shafiya","type":"section","seq":151,"chapter":"تعريف التصريف","title":"108-","page":"ج2 ص21","text":"(وهكذا جاء بمعنى فعلا ... مثل توانيت لضعف حصلا)"},{"id":"shafiya:152","bookId":"shafiya","type":"section","seq":152,"chapter":"تعريف التصريف","title":"109-","page":"ص0","text":"(وطاوعت فاعل نحو باعدا ... طاوعه بتائه تباعدا)\nمعاني تفعل"},{"id":"shafiya:153","bookId":"shafiya","type":"section","seq":153,"chapter":"تعريف التصريف","title":"110-","page":"ص0","text":"(تفعل مطاوع لفعلا ... فطاوعت حصلته تحصلا)"},{"id":"shafiya:154","bookId":"shafiya","type":"section","seq":154,"chapter":"تعريف التصريف","title":"111-","page":"ص0","text":"(وتارة يجيء للتكلف ... نحو تشجعت بلا تصلف)"},{"id":"shafiya:155","bookId":"shafiya","type":"section","seq":155,"chapter":"تعريف التصريف","title":"112-","page":"ص0","text":"(ولاتخاذ كتوسد الحجر ... ولاجتناب كتأثم للحذر)"},{"id":"shafiya:156","bookId":"shafiya","type":"section","seq":156,"chapter":"تعريف التصريف","title":"113-","page":"ص0","text":"(وهكذا للعمل المكرر ... في مهلة نحو تجرع صبري)"},{"id":"shafiya:157","bookId":"shafiya","type":"section","seq":157,"chapter":"تعريف التصريف","title":"114-","page":"ص0","text":"(وقد أتى بمعنى الاستفعال ... نحو تكبرت من الخيال)\nمعاني انفعل"},{"id":"shafiya:158","bookId":"shafiya","type":"section","seq":158,"chapter":"تعريف التصريف","title":"115-","page":"ص0","text":"(طاوع الانفعال حتما فعلا ... تقول قد فصلته فانفصلا)"},{"id":"shafiya:159","bookId":"shafiya","type":"section","seq":159,"chapter":"تعريف التصريف","title":"116-","page":"ص0","text":"(وطاوع الإفعال لكن ندرا ... كالانسفاق وانزعاج ظهرا)"},{"id":"shafiya:160","bookId":"shafiya","type":"section","seq":160,"chapter":"تعريف التصريف","title":"117-","page":"ص0","text":"(واختص بالعلاج فهو انصرما ... من أجل ذاك خطؤوا منعدما)\nمعاني افتعل"},{"id":"shafiya:161","bookId":"shafiya","type":"section","seq":161,"chapter":"تعريف التصريف","title":"118-","page":"ص0","text":"(والافتعال غالبا مطاوع ... فالاجتماع بعد جمع واقع)"},{"id":"shafiya:162","bookId":"shafiya","type":"section","seq":162,"chapter":"تعريف التصريف","title":"119-","page":"ص0","text":"(وقد أتى للاتخاذ كاشتوى ... أي أخذ المرء لنفسه الشوى)"},{"id":"shafiya:163","bookId":"shafiya","type":"section","seq":163,"chapter":"تعريف التصريف","title":"120-","page":"ص0","text":"(وجاء في معنى تفاعل كما ... تقول هم يشتركون في الحمى)"},{"id":"shafiya:164","bookId":"shafiya","type":"section","seq":164,"chapter":"تعريف التصريف","title":"121-","page":"ص0","text":"(وربما يجيء للتصرف ... نحو اكتسبت السوء بالتعرف)\nمعاني استفعل"},{"id":"shafiya:165","bookId":"shafiya","type":"section","seq":165,"chapter":"تعريف التصريف","title":"122-","page":"ص0","text":"(وباب الاستفعال للسؤال ... مطرد في غالب الأحوال)"},{"id":"shafiya:166","bookId":"shafiya","type":"section","seq":166,"chapter":"تعريف التصريف","title":"123-","page":"ص0","text":"(إما صريحا نحو الاستعلاج ... أو غيره كمثل الاستخراج)"},{"id":"shafiya:167","bookId":"shafiya","type":"section","seq":167,"chapter":"تعريف التصريف","title":"124-","page":"ص0","text":"(وهكذا يجيء للتحول ... كاستحجر الطين من التبدل)"},{"id":"shafiya:168","bookId":"shafiya","type":"section","seq":168,"chapter":"تعريف التصريف","title":"125-","page":"ص0","text":"(وربما أفاد معنى فعلا ... كقر واستقر حيث استعملا)"},{"id":"shafiya:169","bookId":"shafiya","type":"section","seq":169,"chapter":"تعريف التصريف","title":"أبنية الفعل الرباعي","page":"ص0","text":"المجرد"},{"id":"shafiya:170","bookId":"shafiya","type":"section","seq":170,"chapter":"تعريف التصريف","title":"126-","page":"ص0","text":"(وللرباعي بناء رسخا ... كقولنا دحرجته ودربخا)\nالمزيد فيه"},{"id":"shafiya:171","bookId":"shafiya","type":"section","seq":171,"chapter":"تعريف التصريف","title":"127-","page":"ص0","text":"(وللرباعي المزيد في البنا ... ثلاثة لازمة فليتقنا)"},{"id":"shafiya:172","bookId":"shafiya","type":"section","seq":172,"chapter":"تعريف التصريف","title":"128-","page":"ص0","text":"(مثل اقشعر جلده واحرنجما ... تدحرج الصخرة عندما رمى)"},{"id":"shafiya:173","bookId":"shafiya","type":"section","seq":173,"chapter":"تعريف التصريف","title":"129-","page":"ص0","text":"(يزاد في فعل مضارع على ... ماضيه حرف من أتين أولا)\nمضارع فعل"},{"id":"shafiya:174","bookId":"shafiya","type":"section","seq":174,"chapter":"تعريف التصريف","title":"130-","page":"ص0","text":"(فإن يكن مجردا على فعل ... تضم عينه وتكسر مثل حل)"},{"id":"shafiya:175","bookId":"shafiya","type":"section","seq":175,"chapter":"تعريف التصريف","title":"131-","page":"ص0","text":"(والفتح جاء في حروف الحلق ... في عين أو لام كمنع محق)"},{"id":"shafiya:176","bookId":"shafiya","type":"section","seq":176,"chapter":"تعريف التصريف","title":"132-","page":"ص0","text":"(شذ أبى يأبى عن الرويه ... أما قلى يقلى فعاميره)"},{"id":"shafiya:177","bookId":"shafiya","type":"section","seq":177,"chapter":"تعريف التصريف","title":"133-","page":"ص0","text":"(والفتح في ركنت ثم تركن ... فمن تداخل بحكم يتقن)"},{"id":"shafiya:178","bookId":"shafiya","type":"section","seq":178,"chapter":"تعريف التصريف","title":"134-","page":"ص0","text":"(والضم في الأجوف بالواو لزم ... كذاك في المنقوص منها فالتزم)"},{"id":"shafiya:179","bookId":"shafiya","type":"section","seq":179,"chapter":"تعريف التصريف","title":"135-","page":"ص0","text":"(والكسر في النوعين بالياء يجب ... كمثل يرمي ويميز فليطب)"},{"id":"shafiya:180","bookId":"shafiya","type":"section","seq":180,"chapter":"تعريف التصريف","title":"136-","page":"ص0","text":"(ومن يقل أتوه ممن توها ... شذ يتيه عنده إذ وجها)"},{"id":"shafiya:181","bookId":"shafiya","type":"section","seq":181,"chapter":"تعريف التصريف","title":"137-","page":"ص0","text":"(وهكذا يطيح مع يطوح ... إلا على تداخل يصحح)"},{"id":"shafiya:182","bookId":"shafiya","type":"section","seq":182,"chapter":"تعريف التصريف","title":"138-","page":"ص0","text":"(ولم يضم العين من معتل ف ... وقوله يجدن ضما ضعفا)"},{"id":"shafiya:183","bookId":"shafiya","type":"section","seq":183,"chapter":"تعريف التصريف","title":"139-","page":"ص0","text":"(وفي المضاعف المعدي الضم ... يلزم مثل ضمه يضم)\nمضارع فعل"},{"id":"shafiya:184","bookId":"shafiya","type":"section","seq":184,"chapter":"تعريف التصريف","title":"140-","page":"ص0","text":"(وإن يكن ماض على وزن فعل ... بالكسر تفتح عينه مثل عجل)"},{"id":"shafiya:185","bookId":"shafiya","type":"section","seq":185,"chapter":"تعريف التصريف","title":"141-","page":"ص0","text":"(وجاء كسر العين في المثال ... كأن تمق زيدا ترث للمال)"},{"id":"shafiya:186","bookId":"shafiya","type":"section","seq":186,"chapter":"تعريف التصريف","title":"142-","page":"ص0","text":"(وطيىء تقول في يلقى لقي ... يلقى لقى وهكذا فيما بقي)"},{"id":"shafiya:187","bookId":"shafiya","type":"section","seq":187,"chapter":"تعريف التصريف","title":"143-","page":"ص0","text":"(وقولهم فضلت ثم تفضل ... فيه تداخل على ما نقلوا)\nمضارع فعل"},{"id":"shafiya:188","bookId":"shafiya","type":"section","seq":188,"chapter":"تعريف التصريف","title":"144-","page":"ص0","text":"(وإن أتى ماض له على فعل ... بالضم ضمت عينه مثل ثقل)"},{"id":"shafiya:189","bookId":"shafiya","type":"section","seq":189,"chapter":"تعريف التصريف","title":"145-","page":"ص0","text":"(وإن يكن غير مجرد مضى ... فكسر ما قبل الأخير افترضا)"},{"id":"shafiya:190","bookId":"shafiya","type":"section","seq":190,"chapter":"تعريف التصريف","title":"146-","page":"ص0","text":"(ما لم يكن أول ماضيه بتا ... فلا يغير كتصدى مثبتا)"},{"id":"shafiya:191","bookId":"shafiya","type":"section","seq":191,"chapter":"تعريف التصريف","title":"147-","page":"ص0","text":"(ورفضهم للهمز في يؤفعل ... من حذر الهمزين في أؤفعل)"},{"id":"shafiya:192","bookId":"shafiya","type":"section","seq":192,"chapter":"تعريف التصريف","title":"148-","page":"ص0","text":"(فخففوا الجميع كي ينتظما ... وشذذوا أهل لأن يؤكرما)"},{"id":"shafiya:193","bookId":"shafiya","type":"section","seq":193,"chapter":"تعريف التصريف","title":"149-","page":"ص0","text":"(الأمر كالفاعل والمفعول ... في النحو مثل أفعل التفضيل)"},{"id":"shafiya:194","bookId":"shafiya","type":"section","seq":194,"chapter":"تعريف التصريف","title":"الصفة المشبهة","page":"ص0","text":"من فعل"},{"id":"shafiya:195","bookId":"shafiya","type":"section","seq":195,"chapter":"تعريف التصريف","title":"150-","page":"ص0","text":"(الوصف ذو التشبيه من نحو فرح ... يجيء غالبا على وزن الفرح)"},{"id":"shafiya:196","bookId":"shafiya","type":"section","seq":196,"chapter":"تعريف التصريف","title":"151-","page":"ص0","text":"(والضم للعين مع الكسر ذكر ... في ندس وعجل مثل حذر)"},{"id":"shafiya:197","bookId":"shafiya","type":"section","seq":197,"chapter":"تعريف التصريف","title":"152-","page":"ص0","text":"(وجاء شكس وسليم وكذا ... حر وصفر وغيور أخذ)"},{"id":"shafiya:198","bookId":"shafiya","type":"section","seq":198,"chapter":"تعريف التصريف","title":"153-","page":"ص0","text":"(وهو من الألوان والحلى على ... أفعل كالعيوب مثل أشهلا)\nمن فعل"},{"id":"shafiya:199","bookId":"shafiya","type":"section","seq":199,"chapter":"تعريف التصريف","title":"154-","page":"ص0","text":"(ويغلب القريب من باب قرب ... وقد أتى على جبان وجنب)"},{"id":"shafiya:200","bookId":"shafiya","type":"section","seq":200,"chapter":"تعريف التصريف","title":"155-","page":"ص0","text":"(وخشن صعب وصلب وحسن ... مثل شجاع ووقور اطمأن)\nمن فعل"},{"id":"shafiya:201","bookId":"shafiya","type":"section","seq":201,"chapter":"تعريف التصريف","title":"156-","page":"ص0","text":"(وقل في المفتوح عينا كأبى ... مثل حريص ضيق وأشيبا)\nمن الجميع"},{"id":"shafiya:202","bookId":"shafiya","type":"section","seq":202,"chapter":"تعريف التصريف","title":"157-","page":"ص0","text":"(وجاء في الكل لمعنى العطش ... والجوع فعلان لضد قد غشي)"},{"id":"shafiya:203","bookId":"shafiya","type":"section","seq":203,"chapter":"تعريف التصريف","title":"158-","page":"ص0","text":"(كمثل عطشان كذا جوعان ... ضداهما الريان والشبعان)"},{"id":"shafiya:204","bookId":"shafiya","type":"section","seq":204,"chapter":"تعريف التصريف","title":"المصدر","page":"ص0","text":"أبنية مصدر الثلاثي المجرد"},{"id":"shafiya:205","bookId":"shafiya","type":"section","seq":205,"chapter":"تعريف التصريف","title":"159-","page":"ص0","text":"(أبنية المصدر في المجرد ... من الثلاثي فشت فلتعدد)"},{"id":"shafiya:206","bookId":"shafiya","type":"section","seq":206,"chapter":"تعريف التصريف","title":"160-","page":"ص0","text":"(قتل وفسق ثم شغل رحمه ... ومحنة من بعدها ودهمه)"},{"id":"shafiya:207","bookId":"shafiya","type":"section","seq":207,"chapter":"تعريف التصريف","title":"161-","page":"ص0","text":"(دعوى وذكرى بعدها ليان ... بشرى وحرمان كما غفران)"},{"id":"shafiya:208","bookId":"shafiya","type":"section","seq":208,"chapter":"تعريف التصريف","title":"162-","page":"ص0","text":"(وجاء فيها نزوان وصدى ... مع خنق وصغر ثم هدى)"},{"id":"shafiya:209","bookId":"shafiya","type":"section","seq":209,"chapter":"تعريف التصريف","title":"163-","page":"ص0","text":"(وقد أتى غلبة مع سرقه ... ثم ذهاب وإياب لحقه)"},{"id":"shafiya:210","bookId":"shafiya","type":"section","seq":210,"chapter":"تعريف التصريف","title":"164-","page":"ص0","text":"(ثم سؤال وزهادة كذا ... سيادة ثم خشوع أخذا)"},{"id":"shafiya:211","bookId":"shafiya","type":"section","seq":211,"chapter":"تعريف التصريف","title":"165-","page":"ص0","text":"(ثم قبول ووجيف يقع ... سهولة ومدخل ومرجع)"},{"id":"shafiya:212","bookId":"shafiya","type":"section","seq":212,"chapter":"تعريف التصريف","title":"166-","page":"ص0","text":"(مرحمة مغفرة رفاهيه ... بغاية فاعرف بها كماهيه)\nمصدر فعل"},{"id":"shafiya:213","bookId":"shafiya","type":"section","seq":213,"chapter":"تعريف التصريف","title":"167-","page":"ص0","text":"(ويغلب المصدر بالفعول ... في فعل اللازم كالدخول)"},{"id":"shafiya:214","bookId":"shafiya","type":"section","seq":214,"chapter":"تعريف التصريف","title":"168-","page":"ص0","text":"(وفي المعدى منه فعل غلبا ... كالضرب والقتل ووعد وجبا)"},{"id":"shafiya:215","bookId":"shafiya","type":"section","seq":215,"chapter":"تعريف التصريف","title":"169-","page":"ص0","text":"(في صنعة ونحوها فعاله ... كتابة عبارة بطاله)"},{"id":"shafiya:216","bookId":"shafiya","type":"section","seq":216,"chapter":"تعريف التصريف","title":"170-","page":"ص0","text":"(والفعلان في اضطراب عال ... والصوت والداء على فعال)"},{"id":"shafiya:217","bookId":"shafiya","type":"section","seq":217,"chapter":"تعريف التصريف","title":"171-","page":"ص0","text":"(وقال فراء إذا جاء فعل ... لم تدر ما مصدره لدى المحل)"},{"id":"shafiya:218","bookId":"shafiya","type":"section","seq":218,"chapter":"تعريف التصريف","title":"172-","page":"ص0","text":"(فاجعله للنجد على فعول ... وللحجاز الفعل بالمعمول)"},{"id":"shafiya:219","bookId":"shafiya","type":"section","seq":219,"chapter":"تعريف التصريف","title":"173-","page":"ج2 ص26","text":"(وخص بالمنقوص أمثال هدى ... كذاك أشباه قرى مطردا)"},{"id":"shafiya:220","bookId":"shafiya","type":"section","seq":220,"chapter":"تعريف التصريف","title":"174-","page":"ج2 ص26","text":"(واختص ذو الضم بنحو الطلب ... والغلب استثني مثل الجلب)\nمصدر فعل"},{"id":"shafiya:221","bookId":"shafiya","type":"section","seq":221,"chapter":"تعريف التصريف","title":"175-","page":"ج2 ص26","text":"(وفعل في لازم من فعلا ... وفي المعدى الفعل مثل جهلا)"},{"id":"shafiya:222","bookId":"shafiya","type":"section","seq":222,"chapter":"تعريف التصريف","title":"176-","page":"ج2 ص26","text":"(فعلة في الألوان والعيوب ... وفي الحلى كبلجة المحبوب)\nمصدر فعل"},{"id":"shafiya:223","bookId":"shafiya","type":"section","seq":223,"chapter":"تعريف التصريف","title":"177-","page":"ج2 ص26","text":"(فعالة فعولة في فعلا ... وعظم مع كرم قد نقلا)\nمصدر المزيد فيه"},{"id":"shafiya:224","bookId":"shafiya","type":"section","seq":224,"chapter":"تعريف التصريف","title":"178-","page":"ج2 ص26","text":"(يقاس في المزيد والرباعي ... فنحو أجمعت على إجماع)"},{"id":"shafiya:225","bookId":"shafiya","type":"section","seq":225,"chapter":"تعريف التصريف","title":"179-","page":"ج2 ص26","text":"(فعلت تفعيلا به وتفعله ... وجاء كذاب مع الكذاب له)"},{"id":"shafiya:226","bookId":"shafiya","type":"section","seq":226,"chapter":"تعريف التصريف","title":"180-","page":"ج2 ص26","text":"(والتزموا التعويض في الإجازه ... توصية كذاك واستجازه)"},{"id":"shafiya:227","bookId":"shafiya","type":"section","seq":227,"chapter":"تعريف التصريف","title":"181-","page":"ج2 ص26","text":"(لفاعل الفعال والمفاعله ... وشذ مراء كذا القيتال له)"},{"id":"shafiya:228","bookId":"shafiya","type":"section","seq":228,"chapter":"تعريف التصريف","title":"182-","page":"ج2 ص26","text":"(وقل تكرمت تكرم الفتى ... وفي تملقت تملاق أتى)"},{"id":"shafiya:229","bookId":"shafiya","type":"section","seq":229,"chapter":"تعريف التصريف","title":"183-","page":"ج2 ص26","text":"(ونحو ترداد وحثيثى على ... إفادة التكثير فيما نقلا)\nالمصدر الميمي"},{"id":"shafiya:230","bookId":"shafiya","type":"section","seq":230,"chapter":"تعريف التصريف","title":"184-","page":"ج2 ص26","text":"(والمصدر الميمي من مجرد ... قياسه من مفعل كمصعد)"},{"id":"shafiya:231","bookId":"shafiya","type":"section","seq":231,"chapter":"تعريف التصريف","title":"185-","page":"ج2 ص26","text":"(ويندر المكرم والمعون به ... وقيل جمعان لذي التا فانتبه)"},{"id":"shafiya:232","bookId":"shafiya","type":"section","seq":232,"chapter":"تعريف التصريف","title":"186-","page":"ج2 ص26","text":"(ووزن مفعول لغيره يجي ... كمخرج مستخرج مدحرج)\nما جاء عليه المصدر قليلا"},{"id":"shafiya:233","bookId":"shafiya","type":"section","seq":233,"chapter":"تعريف التصريف","title":"187-","page":"ج2 ص26","text":"(وقل في المصادر الميسور ... ومثله المفتون والمعسور)"},{"id":"shafiya:234","bookId":"shafiya","type":"section","seq":234,"chapter":"تعريف التصريف","title":"188-","page":"ج2 ص26","text":"(أقل من ذلك مثل الكاذبه ... عافية باقية كالعاقبة)\nمصدر الرباعي المجرد"},{"id":"shafiya:235","bookId":"shafiya","type":"section","seq":235,"chapter":"تعريف التصريف","title":"189-","page":"ج2 ص26","text":"(في دحرج الدحراج بالكسر وفي ... زلزل بالكسر وبالفتح يفي)"},{"id":"shafiya:236","bookId":"shafiya","type":"section","seq":236,"chapter":"تعريف التصريف","title":"اسما المرة والهيئة","page":"ص0","text":"من الثلاثي"},{"id":"shafiya:237","bookId":"shafiya","type":"section","seq":237,"chapter":"تعريف التصريف","title":"190-","page":"ص0","text":"(ومرة المجرد الثلاثي ... إن يخل عن تاء لدى الإحداث)"},{"id":"shafiya:238","bookId":"shafiya","type":"section","seq":238,"chapter":"تعريف التصريف","title":"191-","page":"ص0","text":"(فعلة بالفتح كمثل قتله ... ونوعه بالكسر نحو قتله)\nمن غيره"},{"id":"shafiya:239","bookId":"shafiya","type":"section","seq":239,"chapter":"تعريف التصريف","title":"192-","page":"ص0","text":"(في غيره كالمصدر المستعمل ... بالتاء كاستفصالة للمجمل)\nالشاذ"},{"id":"shafiya:240","bookId":"shafiya","type":"section","seq":240,"chapter":"تعريف التصريف","title":"193-","page":"ص0","text":"(وشذ الاتيانة حيث جاءه ... كقولهم لقيته لقاءه)"},{"id":"shafiya:241","bookId":"shafiya","type":"section","seq":241,"chapter":"تعريف التصريف","title":"اسما الزمان والمكان","page":"ص0","text":"من يفعل ويفعل"},{"id":"shafiya:242","bookId":"shafiya","type":"section","seq":242,"chapter":"تعريف التصريف","title":"194-","page":"ص0","text":"(اسم الزمان والمكان مفعل ... بالفتح من يفعل أو من يفعل)"},{"id":"shafiya:243","bookId":"shafiya","type":"section","seq":243,"chapter":"تعريف التصريف","title":"195-","page":"ص0","text":"(كذاك في المنقوص مثل المعنى ... ومهرب ومشرب مهنى)\nمن يفعل والمثال"},{"id":"shafiya:244","bookId":"shafiya","type":"section","seq":244,"chapter":"تعريف التصريف","title":"196-","page":"ص0","text":"(والكسر في المكسور والمثال ... كموجل ومحفل محلال)\nالشاذ"},{"id":"shafiya:245","bookId":"shafiya","type":"section","seq":245,"chapter":"تعريف التصريف","title":"197-","page":"ص0","text":"(وجاء من مضموم عين مجزر ... ومنسك ومنبت ومنخر)"},{"id":"shafiya:246","bookId":"shafiya","type":"section","seq":246,"chapter":"تعريف التصريف","title":"198-","page":"ص0","text":"(ومطلع ومغرب ومشرق ... ومسقط ومرفق ومفرق)"},{"id":"shafiya:247","bookId":"shafiya","type":"section","seq":247,"chapter":"تعريف التصريف","title":"199-","page":"ص0","text":"(وهكذا المسجد نحو المسكن ... ومنخر فرع كمثل منتن)"},{"id":"shafiya:248","bookId":"shafiya","type":"section","seq":248,"chapter":"تعريف التصريف","title":"200-","page":"ص0","text":"(وليس بالقياس نحو المقبره ... بالفتح والضم على المقرره)\nمن المزيد فيه"},{"id":"shafiya:249","bookId":"shafiya","type":"section","seq":249,"chapter":"تعريف التصريف","title":"201-","page":"ص0","text":"(واسمهما فيما سوى المجرد ... بصيغة المفعول كالممرد)"},{"id":"shafiya:250","bookId":"shafiya","type":"section","seq":250,"chapter":"تعريف التصريف","title":"202-","page":"ص0","text":"(وآلة الفعل على مفعل أو ... مفعال أو مفعلة كما رأوا)\nالشاذ"},{"id":"shafiya:251","bookId":"shafiya","type":"section","seq":251,"chapter":"تعريف التصريف","title":"203-","page":"ص0","text":"(وشذ مسعط مدق منخل ... مكحلة ومدهن مستعمل)"},{"id":"shafiya:252","bookId":"shafiya","type":"section","seq":252,"chapter":"تعريف التصريف","title":"المصغر","page":"ص0","text":"معنى التصغير"},{"id":"shafiya:253","bookId":"shafiya","type":"section","seq":253,"chapter":"تعريف التصريف","title":"204-","page":"ص0","text":"(مصغر الأسماء ما يزاد ... فيه لتقليل به يراد)\nما يعمل في المصغر"},{"id":"shafiya:254","bookId":"shafiya","type":"section","seq":254,"chapter":"تعريف التصريف","title":"205-","page":"ص0","text":"(إن يتمكن ضم منه الأول ... والياء بعد فتح ثان يدخل)"},{"id":"shafiya:255","bookId":"shafiya","type":"section","seq":255,"chapter":"تعريف التصريف","title":"206-","page":"ص0","text":"(وكسروا ما بعدها في الأربعة ... إلا بتا التأنيث أو ما تبعه)"},{"id":"shafiya:256","bookId":"shafiya","type":"section","seq":256,"chapter":"تعريف التصريف","title":"207-","page":"ص0","text":"(من ألفين والمزيدتين أو ... الف أفعال لجمع قد بنوا)"},{"id":"shafiya:257","bookId":"shafiya","type":"section","seq":257,"chapter":"تعريف التصريف","title":"208-","page":"ص0","text":"(ولم يزد في غير ما مر على ... أربعة من بعد ياء أدخلا)"},{"id":"shafiya:258","bookId":"shafiya","type":"section","seq":258,"chapter":"تعريف التصريف","title":"209-","page":"ص0","text":"(فحده فعيل أو فعيعل ... ثم فعيعيل كما يفصل)\nتصغير الخماسي"},{"id":"shafiya:259","bookId":"shafiya","type":"section","seq":259,"chapter":"تعريف التصريف","title":"210-","page":"ص0","text":"(وإن يصغر الخماسي على ... ضعف فحذف خامس قد فضلا)"},{"id":"shafiya:260","bookId":"shafiya","type":"section","seq":260,"chapter":"تعريف التصريف","title":"211-","page":"ص0","text":"(وقيل ما أشبه زائدا يزل ... وقد حكى أخفشهم سفيرجل)\nما يرد إلى أصله"},{"id":"shafiya:261","bookId":"shafiya","type":"section","seq":261,"chapter":"تعريف التصريف","title":"212-","page":"ص0","text":"(يرد ميزان وموقظ إلى ... أصل كباب مع ناب حولا)"},{"id":"shafiya:262","bookId":"shafiya","type":"section","seq":262,"chapter":"تعريف التصريف","title":"213-","page":"ص0","text":"(إذ ذهب الموجب للإعلال ... لا قائم أو أدد يوالي)"},{"id":"shafiya:263","bookId":"shafiya","type":"section","seq":263,"chapter":"تعريف التصريف","title":"214-","page":"ص0","text":"(لم يبدلوا العييد كالأعياد ... فرقا عن العويد والأعواد)"},{"id":"shafiya:264","bookId":"shafiya","type":"section","seq":264,"chapter":"تعريف التصريف","title":"215-","page":"ص0","text":"(فإن يكن مد مزيد ثان ... أبدل واوا كضويربان)\nتصغير بنات الحرفين"},{"id":"shafiya:265","bookId":"shafiya","type":"section","seq":265,"chapter":"تعريف التصريف","title":"216-","page":"ص0","text":"(يرد في إسم على حرفين ما ... أسقط كالأكيل في كل علما)"},{"id":"shafiya:266","bookId":"shafiya","type":"section","seq":266,"chapter":"تعريف التصريف","title":"217-","page":"ج2 ص29","text":"(في عدة وعيدة وفي دم ... ومذ دمي ومنيذ فاعلم)"},{"id":"shafiya:267","bookId":"shafiya","type":"section","seq":267,"chapter":"تعريف التصريف","title":"218-","page":"ج2 ص29","text":"(كذاك باب ابن وبنت جار ... خلاف باب الميت ثم هار)"},{"id":"shafiya:268","bookId":"shafiya","type":"section","seq":268,"chapter":"تعريف التصريف","title":"219-","page":"ج2 ص29","text":"(إن يل واو ياءه أو ألف ... يقلب إلى الياء بأصل يعرف)"},{"id":"shafiya:269","bookId":"shafiya","type":"section","seq":269,"chapter":"تعريف التصريف","title":"220-","page":"ج2 ص29","text":"(كذاك همز مبدل بعد ألف ... فقل عرية عصية تخف)"},{"id":"shafiya:270","bookId":"shafiya","type":"section","seq":270,"chapter":"تعريف التصريف","title":"221-","page":"ج2 ص29","text":"(تصحيح واو في جديل يقل ... في اللغة الفصحى لضابط نقل)\nما فيه ثلاث ياءات"},{"id":"shafiya:271","bookId":"shafiya","type":"section","seq":271,"chapter":"تعريف التصريف","title":"222-","page":"ج2 ص29","text":"(فإن أتت ثلاث ياءات حذف ... أخيرها في خير قول قد عرف)"},{"id":"shafiya:272","bookId":"shafiya","type":"section","seq":272,"chapter":"تعريف التصريف","title":"223-","page":"ج2 ص29","text":"(تقول في إداوة أدية ... كذاك في غاوية غوية)"},{"id":"shafiya:273","bookId":"shafiya","type":"section","seq":273,"chapter":"تعريف التصريف","title":"224-","page":"ج2 ص29","text":"(معية يجيء في معاوية ... كما عطي في عطاء وافية)"},{"id":"shafiya:274","bookId":"shafiya","type":"section","seq":274,"chapter":"تعريف التصريف","title":"225-","page":"ج2 ص29","text":"(أحي في أحوى ولا ينصرف ... وقال عيسى بل أحي يصرف)"},{"id":"shafiya:275","bookId":"shafiya","type":"section","seq":275,"chapter":"تعريف التصريف","title":"226-","page":"ج2 ص29","text":"(وقال بو عمرو أحي وعلى ... أسيود يأتي أحيو مرسلا)\nتصغير المؤنث"},{"id":"shafiya:276","bookId":"shafiya","type":"section","seq":276,"chapter":"تعريف التصريف","title":"227-","page":"ج2 ص29","text":"(تزاد في المؤنث السماعي ... تاء ولا تزاد في الرباعي)"},{"id":"shafiya:277","bookId":"shafiya","type":"section","seq":277,"chapter":"تعريف التصريف","title":"228-","page":"ج2 ص29","text":"(كقولهم أذينة في أذن ... وشذ في عرس عريس فأذن)"},{"id":"shafiya:278","bookId":"shafiya","type":"section","seq":278,"chapter":"تعريف التصريف","title":"229-","page":"ج2 ص29","text":"(عقيرب في عقرب بالتوطئه ... شذت قديديمة أو وريئه)"},{"id":"shafiya:279","bookId":"shafiya","type":"section","seq":279,"chapter":"تعريف التصريف","title":"230-","page":"ج2 ص29","text":"(وألف التأنيث غير الرابعه ... مقصورة تحذف للمتابعه)"},{"id":"shafiya:280","bookId":"shafiya","type":"section","seq":280,"chapter":"تعريف التصريف","title":"231-","page":"ج2 ص29","text":"(جحيجب في جحجبى قد ثبتا ... كما بحولايا حويلي أتى)\nما فيه مد بعد ياء التصغير"},{"id":"shafiya:281","bookId":"shafiya","type":"section","seq":281,"chapter":"تعريف التصريف","title":"232-","page":"ص0","text":"(تثبت ذات المد مطلقا كما ... يثبت ثاني بعلبك محكما)"},{"id":"shafiya:282","bookId":"shafiya","type":"section","seq":282,"chapter":"تعريف التصريف","title":"233-","page":"ص0","text":"(والمد بعد كسرة المصغر ... يقلب ياء ككريديس السري)\nما فيه زيادتان"},{"id":"shafiya:283","bookId":"shafiya","type":"section","seq":283,"chapter":"تعريف التصريف","title":"234-","page":"ص0","text":"(في ذي الزيادتين غير المدة ... يحذف ما كان أقل عدة)"},{"id":"shafiya:284","bookId":"shafiya","type":"section","seq":284,"chapter":"تعريف التصريف","title":"235-","page":"ص0","text":"(محيرف يقال في محترف ... محارف محرف منحرف)"},{"id":"shafiya:285","bookId":"shafiya","type":"section","seq":285,"chapter":"تعريف التصريف","title":"236-","page":"ص0","text":"(خير إن تساويا أن تثبتا ... مثل حبيط وحبينط أتى)"},{"id":"shafiya:286","bookId":"shafiya","type":"section","seq":286,"chapter":"تعريف التصريف","title":"237-","page":"ص0","text":"(في ذي الثلاث غيرها فضلاها ... تبقى كما مقيعس جلاها)"},{"id":"shafiya:287","bookId":"shafiya","type":"section","seq":287,"chapter":"تعريف التصريف","title":"238-","page":"ص0","text":"(أما زيادات الرباعي عدا ... مدتها فكلها قد طردا)"},{"id":"shafiya:288","bookId":"shafiya","type":"section","seq":288,"chapter":"تعريف التصريف","title":"239-","page":"ص0","text":"(قشيعر في مقشعر حام ... كما حريجيم في الاحرنجام)"},{"id":"shafiya:289","bookId":"shafiya","type":"section","seq":289,"chapter":"تعريف التصريف","title":"240-","page":"ص0","text":"(وجاز مد بعد كسر عوضا ... كما مغيميم بمغتم مضى)\nتصغير جمع الكثرة"},{"id":"shafiya:290","bookId":"shafiya","type":"section","seq":290,"chapter":"تعريف التصريف","title":"241-","page":"ص0","text":"(ورد جمع كثرة لا اسما إلى ... قلته ثمت صغر مكملا)"},{"id":"shafiya:291","bookId":"shafiya","type":"section","seq":291,"chapter":"تعريف التصريف","title":"242-","page":"ص0","text":"(أو صغر الواحد منه فاجمعا ... جمع سلامة على ما سمعا)"},{"id":"shafiya:292","bookId":"shafiya","type":"section","seq":292,"chapter":"تعريف التصريف","title":"243-","page":"ص0","text":"(غليمة بالرد في غلمان ... غليمون بالطريق الثاني)"},{"id":"shafiya:293","bookId":"shafiya","type":"section","seq":293,"chapter":"تعريف التصريف","title":"244-","page":"ص0","text":"(أدير في الدور إن تصغر ... أو الدويرات على المقرر)\nشواذ التصغير"},{"id":"shafiya:294","bookId":"shafiya","type":"section","seq":294,"chapter":"تعريف التصريف","title":"245-","page":"ص0","text":"(شذ خلاف الأوجه المقدمة ... مثل الأنيسيان والأغيلمه)"},{"id":"shafiya:295","bookId":"shafiya","type":"section","seq":295,"chapter":"تعريف التصريف","title":"246-","page":"ص0","text":"(وشذ في عشية عشيشيه ... وهكذا في صبية أصيبيه)"},{"id":"shafiya:296","bookId":"shafiya","type":"section","seq":296,"chapter":"تعريف التصريف","title":"247-","page":"ص0","text":"(دوين هذا وفويقه على ... تقليل ما بينهما منزلا)"},{"id":"shafiya:297","bookId":"shafiya","type":"section","seq":297,"chapter":"تعريف التصريف","title":"248-","page":"ص0","text":"(وشذ في التصغير ما أحيسنه ... والقصد تصغير الذي قد حسنه)\nما ورد مصغرا"},{"id":"shafiya:298","bookId":"shafiya","type":"section","seq":298,"chapter":"تعريف التصريف","title":"249-","page":"ج2 ص31","text":"(نحو جميل وكعيت وضعا ... مصغرا مثل كميت سمعا)\nتصغير الترخيم"},{"id":"shafiya:299","bookId":"shafiya","type":"section","seq":299,"chapter":"تعريف التصريف","title":"250-","page":"ج2 ص31","text":"(تصغير ترخيم على أن يحذفا ... مزيده نحو صفي في اصطفى)\nتصغير غير المتمكن"},{"id":"shafiya:300","bookId":"shafiya","type":"section","seq":300,"chapter":"تعريف التصريف","title":"251-","page":"ج2 ص31","text":"(خولف بالموصول والإشاره ... بالياء قبل آخر العباره)"},{"id":"shafiya:301","bookId":"shafiya","type":"section","seq":301,"chapter":"تعريف التصريف","title":"252-","page":"ج2 ص31","text":"(وألحقت في آخر منها ألف ... فقيل ذيا واللذيا وصرف)"},{"id":"shafiya:302","bookId":"shafiya","type":"section","seq":302,"chapter":"تعريف التصريف","title":"253-","page":"ج2 ص31","text":"(لم يرد التصغير في الضمائر ... والظرف واسم الشرط والنظائر)"},{"id":"shafiya:303","bookId":"shafiya","type":"section","seq":303,"chapter":"تعريف التصريف","title":"254-","page":"ج2 ص31","text":"(ولم يجىء تصغير الاسم عاملا ... فلم يجز حويمل محاملا)"},{"id":"shafiya:304","bookId":"shafiya","type":"section","seq":304,"chapter":"تعريف التصريف","title":"النسب","page":"ج2 ص31","text":"تعريفه"},{"id":"shafiya:305","bookId":"shafiya","type":"section","seq":305,"chapter":"تعريف التصريف","title":"255-","page":"ج2 ص31","text":"(منسوبهم ما لحق اليا طرفه ... لنسبة إلى الذي قد ردفه)\nقياسه"},{"id":"shafiya:306","bookId":"shafiya","type":"section","seq":306,"chapter":"تعريف التصريف","title":"256-","page":"ج2 ص31","text":"(ويحذف التاء قياسا وكذا ... زيادة اثنين وجمع أخذا)"},{"id":"shafiya:307","bookId":"shafiya","type":"section","seq":307,"chapter":"تعريف التصريف","title":"257-","page":"ج2 ص31","text":"(ما لم يكونا علما قد أعربا ... بالحركات فلتقرا نسبا)"},{"id":"shafiya:308","bookId":"shafiya","type":"section","seq":308,"chapter":"تعريف التصريف","title":"258-","page":"ج2 ص31","text":"(يفتح ثاني نمر مثل دئل ... لا تغلبي في فصيح ذا نقل)"},{"id":"shafiya:309","bookId":"shafiya","type":"section","seq":309,"chapter":"تعريف التصريف","title":"259-","page":"ج2 ص31","text":"(وتحذف الياء من الفعيله ... وهكذا الواو من الفعوله)"},{"id":"shafiya:310","bookId":"shafiya","type":"section","seq":310,"chapter":"تعريف التصريف","title":"260-","page":"ج2 ص31","text":"(إن صحت العين ولم تضعف ... كالشنئي نسبة والحنفي)"},{"id":"shafiya:311","bookId":"shafiya","type":"section","seq":311,"chapter":"تعريف التصريف","title":"261-","page":"ج2 ص31","text":"(ويحذفون الياء من فعيله ... غير مضاعف فأوف كيله)"},{"id":"shafiya:312","bookId":"shafiya","type":"section","seq":312,"chapter":"تعريف التصريف","title":"262-","page":"ج2 ص31","text":"(شذ سليمي بأزد وكذا ... شذ سيلقي على ما أخذا)"},{"id":"shafiya:313","bookId":"shafiya","type":"section","seq":313,"chapter":"تعريف التصريف","title":"263-","page":"ج2 ص31","text":"(والجذمي في بني جذيمه ... أشذ من ضمتها الضميمه)"},{"id":"shafiya:314","bookId":"shafiya","type":"section","seq":314,"chapter":"تعريف التصريف","title":"264-","page":"ج2 ص32","text":"(شذ خريبي لدى النسبة في ... خريبة وفي ثقيف ثقفي)"},{"id":"shafiya:315","bookId":"shafiya","type":"section","seq":315,"chapter":"تعريف التصريف","title":"265-","page":"ج2 ص32","text":"(والقرشي شذ مثل الفقمي ... والملحي في مليح منتمي)"},{"id":"shafiya:316","bookId":"shafiya","type":"section","seq":316,"chapter":"تعريف التصريف","title":"266-","page":"ج2 ص32","text":"(وتحذف الياء من الناقص في ... مذكر وغيره فينتفي)"},{"id":"shafiya:317","bookId":"shafiya","type":"section","seq":317,"chapter":"تعريف التصريف","title":"267-","page":"ج2 ص32","text":"(ويقلب الأخير واوا فالغني ... قل غنوي فيه مثل الأموي)"},{"id":"shafiya:318","bookId":"shafiya","type":"section","seq":318,"chapter":"تعريف التصريف","title":"268-","page":"ج2 ص32","text":"(جاء أميي على التتبع ... لأصله بالجمع بين الأربع)"},{"id":"shafiya:319","bookId":"shafiya","type":"section","seq":319,"chapter":"تعريف التصريف","title":"269-","page":"ج2 ص32","text":"(ولم يجىء بدون حذف غنوي ... لكسرة وشذ فتح الأموي)"},{"id":"shafiya:320","bookId":"shafiya","type":"section","seq":320,"chapter":"تعريف التصريف","title":"270-","page":"ج2 ص32","text":"(والتحوي في تحية جرى ... مجرى فعيلة لصورة ترى)"},{"id":"shafiya:321","bookId":"shafiya","type":"section","seq":321,"chapter":"تعريف التصريف","title":"271-","page":"ج2 ص32","text":"(وفي عدو قل عدوي وفي ... عدوة عند المبرد اصطفى)"},{"id":"shafiya:322","bookId":"shafiya","type":"section","seq":322,"chapter":"تعريف التصريف","title":"272-","page":"ج2 ص32","text":"(وقال سيبويه فيه العدوي ... نحو صحيح اللام مثل الشنئي)"},{"id":"shafiya:323","bookId":"shafiya","type":"section","seq":323,"chapter":"تعريف التصريف","title":"273-","page":"ج2 ص32","text":"(ويحذف الثاني من المهيم ... أصلاكذا من سيد متيم)"},{"id":"shafiya:324","bookId":"shafiya","type":"section","seq":324,"chapter":"تعريف التصريف","title":"274-","page":"ج2 ص32","text":"(فإن يكن مصغر المهوم ... فهو المهييمي حين ينتمي)\nالنسب إلى ما آخر ألف"},{"id":"shafiya:325","bookId":"shafiya","type":"section","seq":325,"chapter":"تعريف التصريف","title":"275-","page":"ج2 ص32","text":"(ويقلبون الألف الأخيره ... ثالثة واوا على الوتيرة)"},{"id":"shafiya:326","bookId":"shafiya","type":"section","seq":326,"chapter":"تعريف التصريف","title":"276-","page":"ج2 ص32","text":"(كذلك الرابعة المنقلبه ... عن واو أو ياء من المنتسبه)"},{"id":"shafiya:327","bookId":"shafiya","type":"section","seq":327,"chapter":"تعريف التصريف","title":"277-","page":"ج2 ص32","text":"(كالعصوي في عصا والملهوي ... والرحوي في رحى ومرموي)"},{"id":"shafiya:328","bookId":"shafiya","type":"section","seq":328,"chapter":"تعريف التصريف","title":"278-","page":"ج2 ص32","text":"(غيرهما يحذف كالحبلي ... والجمزي والقبعثري)"},{"id":"shafiya:329","bookId":"shafiya","type":"section","seq":329,"chapter":"تعريف التصريف","title":"279-","page":"ص0","text":"(وحبلوي جا وحبلاوي ... ولم يجىء في جمزى واوي)\nما آخره ياء"},{"id":"shafiya:330","bookId":"shafiya","type":"section","seq":330,"chapter":"تعريف التصريف","title":"280-","page":"ص0","text":"(والياء من نحو شج أو من عم ... تقلب واوا بعد فتح ينتمي)"},{"id":"shafiya:331","bookId":"shafiya","type":"section","seq":331,"chapter":"تعريف التصريف","title":"281-","page":"ص0","text":"(يحذف في الأفصح من قاضي ... يسقط ما زاد كمقتضي)"},{"id":"shafiya:332","bookId":"shafiya","type":"section","seq":332,"chapter":"تعريف التصريف","title":"282-","page":"ص0","text":"(باب محيي محوي وكذا ... جاء محيي على ما أخذ)\nما آخره واو أو ياء ساكن ما قبلها"},{"id":"shafiya:333","bookId":"shafiya","type":"section","seq":333,"chapter":"تعريف التصريف","title":"283-","page":"ص0","text":"(وظبية وقنية وغزوة ... ورقية وعروة ورشوة)"},{"id":"shafiya:334","bookId":"shafiya","type":"section","seq":334,"chapter":"تعريف التصريف","title":"284-","page":"ص0","text":"(على القياس عند سيبويه ... والقروي خارج لديه)"},{"id":"shafiya:335","bookId":"shafiya","type":"section","seq":335,"chapter":"تعريف التصريف","title":"285-","page":"ص0","text":"(ليونس الفتح فقط في الغزوي ... والفتح والقلب معا في الظبوي)"},{"id":"shafiya:336","bookId":"shafiya","type":"section","seq":336,"chapter":"تعريف التصريف","title":"286-","page":"ص0","text":"(واتفقا في باب ظبي وكذا ... غزو وفتح البدوي شذذا)\nما آخره ياء قبلها حرف علة"},{"id":"shafiya:337","bookId":"shafiya","type":"section","seq":337,"chapter":"تعريف التصريف","title":"287-","page":"ص0","text":"(طي وحي طووي حيوي ... خلاف دوي وكوي روي)"},{"id":"shafiya:338","bookId":"shafiya","type":"section","seq":338,"chapter":"تعريف التصريف","title":"288-","page":"ص0","text":"(يقال مرمي ومرموي ... أيضا إذا ما ينسب المرمي)\nما آخره ياء مشددة بعد ثلاثة"},{"id":"shafiya:339","bookId":"shafiya","type":"section","seq":339,"chapter":"تعريف التصريف","title":"289-","page":"ص0","text":"(وإن تكن زائدة مشدده ... تحذف كالكرسي في الممهده)\nما آخره همزة بعد مدة"},{"id":"shafiya:340","bookId":"shafiya","type":"section","seq":340,"chapter":"تعريف التصريف","title":"290-","page":"ص0","text":"(والهمز بعد المد للمؤنث ... يقلب للواو لدى التحدث)"},{"id":"shafiya:341","bookId":"shafiya","type":"section","seq":341,"chapter":"تعريف التصريف","title":"291-","page":"ص0","text":"(فنسبة الصحراء صحراوي ... ونسبة الحمراء حمراوي)"},{"id":"shafiya:342","bookId":"shafiya","type":"section","seq":342,"chapter":"تعريف التصريف","title":"292-","page":"ص0","text":"(وشذ في صنعاء صنعاني ... كذاك في بهراء بهراني)"},{"id":"shafiya:343","bookId":"shafiya","type":"section","seq":343,"chapter":"تعريف التصريف","title":"293-","page":"ص0","text":"(ثم جلولي لديهم شذذا ... وفي حروراء حروري كذا)"},{"id":"shafiya:344","bookId":"shafiya","type":"section","seq":344,"chapter":"تعريف التصريف","title":"294-","page":"ص0","text":"(وان تكن همزته أصليه ... تثبت على الأكثر بالرويه)"},{"id":"shafiya:345","bookId":"shafiya","type":"section","seq":345,"chapter":"تعريف التصريف","title":"295-","page":"ص0","text":"(فشاع في القراء قرائي ... وجاء بالقلة قراوي)"},{"id":"shafiya:346","bookId":"shafiya","type":"section","seq":346,"chapter":"تعريف التصريف","title":"296-","page":"ص0","text":"(أو لا فوجهان كعلباوي ... أو ككسائي وعلباوي)\nما آخره واو أو ياء بعد ألف"},{"id":"shafiya:347","bookId":"shafiya","type":"section","seq":347,"chapter":"تعريف التصريف","title":"297-","page":"ص0","text":"(وفي سقاية سقائي عهد ... وفي شقاوة شقاوي يرد)"},{"id":"shafiya:348","bookId":"shafiya","type":"section","seq":348,"chapter":"تعريف التصريف","title":"298-","page":"ص0","text":"(وباب راي راية رائي ... وجاء راوي كذا رايي)\nبنات الحرفين"},{"id":"shafiya:349","bookId":"shafiya","type":"section","seq":349,"chapter":"تعريف التصريف","title":"299-","page":"ص0","text":"(واسم على حرفين إن تحركا ... أو سطه واللام منه تركا)"},{"id":"shafiya:350","bookId":"shafiya","type":"section","seq":350,"chapter":"تعريف التصريف","title":"300-","page":"ص0","text":"(ولم يعوض همز وصل أو بدا ... محذوف فاء ناقصا فليرددا)"},{"id":"shafiya:351","bookId":"shafiya","type":"section","seq":351,"chapter":"تعريف التصريف","title":"301-","page":"ص0","text":"(كالأبوي في أب والأخوي ... والستهي في ست والوشوي)"},{"id":"shafiya:352","bookId":"shafiya","type":"section","seq":352,"chapter":"تعريف التصريف","title":"302-","page":"ص0","text":"(والأخفش الوشيي بالياء يرى ... حملا على الأصل الذي تقررا)"},{"id":"shafiya:353","bookId":"shafiya","type":"section","seq":353,"chapter":"تعريف التصريف","title":"303-","page":"ص0","text":"(إن صحت اللام وغيرها ردي ... لم يأت رد كسهي وعدي)"},{"id":"shafiya:354","bookId":"shafiya","type":"section","seq":354,"chapter":"تعريف التصريف","title":"304-","page":"ص0","text":"(وجاء أيضا عدوي في عده ... وليس ردا بل أتى ليعضده)"},{"id":"shafiya:355","bookId":"shafiya","type":"section","seq":355,"chapter":"تعريف التصريف","title":"305-","page":"ص0","text":"(وجهان في غيرهما كالغدوي ... كذلك ابني غدي بنوي)"},{"id":"shafiya:356","bookId":"shafiya","type":"section","seq":356,"chapter":"تعريف التصريف","title":"306-","page":"ص0","text":"(وسكن الأخفش ما الأصل سكن ... فيه كغدوي وجرحي علن)"},{"id":"shafiya:357","bookId":"shafiya","type":"section","seq":357,"chapter":"تعريف التصريف","title":"307-","page":"ص0","text":"(والبنت كابن عند سيبويه ... والكلوي قد جرى عليه)"},{"id":"shafiya:358","bookId":"shafiya","type":"section","seq":358,"chapter":"تعريف التصريف","title":"308-","page":"ص0","text":"(يونس بنتي وكلتوي ... فيه وكلتي وكلتاوي)\nالمركب"},{"id":"shafiya:359","bookId":"shafiya","type":"section","seq":359,"chapter":"تعريف التصريف","title":"309-","page":"ص0","text":"(ينسب للصدر من المركب ... يقال معدي لمعدي كرب)"},{"id":"shafiya:360","bookId":"shafiya","type":"section","seq":360,"chapter":"تعريف التصريف","title":"310-","page":"ص0","text":"(تأبطي وكذا الخمسي في ... خمسة عشر نسبة لموقف)"},{"id":"shafiya:361","bookId":"shafiya","type":"section","seq":361,"chapter":"تعريف التصريف","title":"311-","page":"ص0","text":"(لم ينسبوا إليه في الأعداد ... صونا عن الإخلال بالمراد)"},{"id":"shafiya:362","bookId":"shafiya","type":"section","seq":362,"chapter":"تعريف التصريف","title":"312-","page":"ص0","text":"(وفي الإضافي إن الثاني قصد ... كابن الزبير بالزبيري اقتصد)"},{"id":"shafiya:363","bookId":"shafiya","type":"section","seq":363,"chapter":"تعريف التصريف","title":"313-","page":"ص0","text":"(وإن يكن مثل امرىء القيس فذا ... بالامرئي في انتساب أخذا)\nالجمع"},{"id":"shafiya:364","bookId":"shafiya","type":"section","seq":364,"chapter":"تعريف التصريف","title":"314-","page":"ص0","text":"(رد إلى الواحد جمعا في النسب ... مثل كتابي إلى الكتب انتسب)"},{"id":"shafiya:365","bookId":"shafiya","type":"section","seq":365,"chapter":"تعريف التصريف","title":"315-","page":"ص0","text":"(والصحفي نسبة والفرضي ... في صحف وفي الفرائض ارتضي)"},{"id":"shafiya:366","bookId":"shafiya","type":"section","seq":366,"chapter":"تعريف التصريف","title":"316-","page":"ص0","text":"(مساجدي جاء في مساجد ... إن يكن اسما علما لماجد)"},{"id":"shafiya:367","bookId":"shafiya","type":"section","seq":367,"chapter":"تعريف التصريف","title":"317-","page":"ص0","text":"(كمثل الأنصاري والكلابي ... وشذ ما خالف في انتساب)\nالنسب بغير ياء"},{"id":"shafiya:368","bookId":"shafiya","type":"section","seq":368,"chapter":"تعريف التصريف","title":"318-","page":"ص0","text":"(في حرف قد كثر الفعال ... مثاله الحمال والجمال)"},{"id":"shafiya:369","bookId":"shafiya","type":"section","seq":369,"chapter":"تعريف التصريف","title":"319-","page":"ص0","text":"(وفاعل جاء بمعنى ذي كذا ... كتامر ولابن قد أخذا)"},{"id":"shafiya:370","bookId":"shafiya","type":"section","seq":370,"chapter":"تعريف التصريف","title":"320-","page":"ص0","text":"(ومنه وصف عيشة براضيه ... والطاعم الكاسي بدعوى الماضيه)"},{"id":"shafiya:371","bookId":"shafiya","type":"section","seq":371,"chapter":"تعريف التصريف","title":"جمع التكسير","page":"ص0","text":"الثلاثي المذكر اسما فعل"},{"id":"shafiya:372","bookId":"shafiya","type":"section","seq":372,"chapter":"تعريف التصريف","title":"321-","page":"ص0","text":"(في نحو فلس غالبا فعول ... وافعل كلاهما منقول)"},{"id":"shafiya:373","bookId":"shafiya","type":"section","seq":373,"chapter":"تعريف التصريف","title":"322-","page":"ص0","text":"(في باب ثوب يغلب الأثواب ... وفي سوى سيل أتى الثياب)"},{"id":"shafiya:374","bookId":"shafiya","type":"section","seq":374,"chapter":"تعريف التصريف","title":"323-","page":"ص0","text":"(رئلان بطنان كمثل الغرده ... وسقف جاءت وشذت أنجده)\nفعل"},{"id":"shafiya:375","bookId":"shafiya","type":"section","seq":375,"chapter":"تعريف التصريف","title":"324-","page":"ص0","text":"(في حمل الأحمال والحمول ... لقلة وكثرة معمول)"},{"id":"shafiya:376","bookId":"shafiya","type":"section","seq":376,"chapter":"تعريف التصريف","title":"325-","page":"ص0","text":"(وجاء بالقداح والصنوان ... وأرجل قردة ذؤبان)\nفعل"},{"id":"shafiya:377","bookId":"shafiya","type":"section","seq":377,"chapter":"تعريف التصريف","title":"326-","page":"ص0","text":"(قرء على القروء والأقراء ... في كثرة وقلة للرائي)"},{"id":"shafiya:378","bookId":"shafiya","type":"section","seq":378,"chapter":"تعريف التصريف","title":"327-","page":"ص0","text":"(وجاء فلك وخفاف قرطه ... عود على العيدان أعلل وسطه)\nفعل"},{"id":"shafiya:379","bookId":"shafiya","type":"section","seq":379,"chapter":"تعريف التصريف","title":"328-","page":"ص0","text":"(في الجمل الأجمال والجمال ... والتاج تيجان به اعتلال)"},{"id":"shafiya:380","bookId":"shafiya","type":"section","seq":380,"chapter":"تعريف التصريف","title":"329-","page":"ص0","text":"(وجاءت الأزمن والخربان ... حجلى ذكور جيرة حملان)\nفعل"},{"id":"shafiya:381","bookId":"shafiya","type":"section","seq":381,"chapter":"تعريف التصريف","title":"330-","page":"ص0","text":"(في الفخذ الأفخاذ من دون عسر ... وجاء في ذاك نمور ونمر)\nفعل"},{"id":"shafiya:382","bookId":"shafiya","type":"section","seq":382,"chapter":"تعريف التصريف","title":"331-","page":"ص0","text":"(في عجز قد غلب الأعجاز ... في السبع السباع يستجاز)"},{"id":"shafiya:383","bookId":"shafiya","type":"section","seq":383,"chapter":"تعريف التصريف","title":"332-","page":"ص0","text":"(وليس رجلة بتكسير الرجل ... بل اسم جمع راجل حيث تحل)\nفعل"},{"id":"shafiya:384","bookId":"shafiya","type":"section","seq":384,"chapter":"تعريف التصريف","title":"333-","page":"ص0","text":"(في العنب الأعناب غالبا وقع ... وجاء أضلاع ضلوع في ضلع)"},{"id":"shafiya:385","bookId":"shafiya","type":"section","seq":385,"chapter":"تعريف التصريف","title":"334-","page":"ص0","text":"(في إبل قد غلب الأبال ... في قلة وكثرة تنال)\nفعل"},{"id":"shafiya:386","bookId":"shafiya","type":"section","seq":386,"chapter":"تعريف التصريف","title":"335-","page":"ص0","text":"(في الصرد الصردان بالشياع ... وجاء بالأرطاب والرباع)\nفعل"},{"id":"shafiya:387","bookId":"shafiya","type":"section","seq":387,"chapter":"تعريف التصريف","title":"336-","page":"ص0","text":"(في عنق ونحوه أعناق ... في قلة وكثرة تنساق)\nالممتنع"},{"id":"shafiya:388","bookId":"shafiya","type":"section","seq":388,"chapter":"تعريف التصريف","title":"337-","page":"ص0","text":"(وامتنعوا من أفعل في الأجوف ... وشذ نحو أقوس وأسيف)"},{"id":"shafiya:389","bookId":"shafiya","type":"section","seq":389,"chapter":"تعريف التصريف","title":"338-","page":"ص0","text":"(وأعرضوا في الياء عن فعال ... لا الواو والثياب للمثال)"},{"id":"shafiya:390","bookId":"shafiya","type":"section","seq":390,"chapter":"تعريف التصريف","title":"339-","page":"ص0","text":"(في الواو لم يستعمل الفعول ... وشذت الفووج لا الخيول)\nالثلاثي المؤنث اسما فعلة"},{"id":"shafiya:391","bookId":"shafiya","type":"section","seq":391,"chapter":"تعريف التصريف","title":"340-","page":"ص0","text":"(في قصعة فتحا قصاع قد غلب ... مع بدر جاء بدور ونوب)\nفعلة"},{"id":"shafiya:392","bookId":"shafiya","type":"section","seq":392,"chapter":"تعريف التصريف","title":"341-","page":"ج2 ص37","text":"(وشائع في جزية كسرا جزى ... وأنعم مثل لقاح جوزا)\nفعلة"},{"id":"shafiya:393","bookId":"shafiya","type":"section","seq":393,"chapter":"تعريف التصريف","title":"342-","page":"ج2 ص37","text":"(وغالب في عروة ضما عرى ... وبالحجوز والبرام قد جرى)\nفعله"},{"id":"shafiya:394","bookId":"shafiya","type":"section","seq":394,"chapter":"تعريف التصريف","title":"343-","page":"ج2 ص37","text":"(رقبة على الرقاب أشهر ... وجاء أينق وبدن تير)\nفعلة فعلة"},{"id":"shafiya:395","bookId":"shafiya","type":"section","seq":395,"chapter":"تعريف التصريف","title":"344-","page":"ج2 ص37","text":"(وشاع عنهم كلم في كلمه ... كذاك قالوا تخم في تخمه)\nحكم عين المؤنث اسما"},{"id":"shafiya:396","bookId":"shafiya","type":"section","seq":396,"chapter":"تعريف التصريف","title":"345-","page":"ج2 ص37","text":"(للتمرات الفتح في المشهوره ... في الجمع والإسكان للضروره)"},{"id":"shafiya:397","bookId":"shafiya","type":"section","seq":397,"chapter":"تعريف التصريف","title":"346-","page":"ج2 ص37","text":"(ويسكن الأجوف دون ميل ... ويستوي النوعان في هذيل)"},{"id":"shafiya:398","bookId":"shafiya","type":"section","seq":398,"chapter":"تعريف التصريف","title":"347-","page":"ج2 ص37","text":"(وكسرة بالكسرات تجمع ... بالفتح والكسر على ما تسمع)"},{"id":"shafiya:399","bookId":"shafiya","type":"section","seq":399,"chapter":"تعريف التصريف","title":"348-","page":"ج2 ص37","text":"(والناقص الواوي ثم الأجوف ... يسكن أو يفتح إذ يصرف)"},{"id":"shafiya:400","bookId":"shafiya","type":"section","seq":400,"chapter":"تعريف التصريف","title":"349-","page":"ج2 ص37","text":"(والحجرات عند جمع حجره ... بالضم أو بالفتح مستمرة)"},{"id":"shafiya:401","bookId":"shafiya","type":"section","seq":401,"chapter":"تعريف التصريف","title":"350-","page":"ج2 ص37","text":"(أجوفها وناقص بالياء ... يسكن أو يفتح في البناء)"},{"id":"shafiya:402","bookId":"shafiya","type":"section","seq":402,"chapter":"تعريف التصريف","title":"351-","page":"ج2 ص37","text":"(والعين قد تسكن في كسرات ... عند التميمي وفي حجرات)\nالصفات بالإسكان"},{"id":"shafiya:403","bookId":"shafiya","type":"section","seq":403,"chapter":"تعريف التصريف","title":"352-","page":"ج2 ص37","text":"(وساكن في كلها ما ضعفا ... وفي الصفات بالسكون صرفا)"},{"id":"shafiya:404","bookId":"shafiya","type":"section","seq":404,"chapter":"تعريف التصريف","title":"353-","page":"ج2 ص37","text":"(في لجبات ربعات لمحا ... اسمية وصفية إذ فتحا)"},{"id":"shafiya:405","bookId":"shafiya","type":"section","seq":405,"chapter":"تعريف التصريف","title":"354-","page":"ج2 ص37","text":"(والأرض والأهل وعرس جمعا ... بالتاء كالعير على ما سمعا)\nبنات الحرفين"},{"id":"shafiya:406","bookId":"shafiya","type":"section","seq":406,"chapter":"تعريف التصريف","title":"355-","page":"ج2 ص38","text":"(في سنة قد جاءت السنونا ... ومثلها القلون والثبونا)"},{"id":"shafiya:407","bookId":"shafiya","type":"section","seq":407,"chapter":"تعريف التصريف","title":"356-","page":"ج2 ص38","text":"(والسنوات جاء والثبات ... والعضوات بعدها الهنات)"},{"id":"shafiya:408","bookId":"shafiya","type":"section","seq":408,"chapter":"تعريف التصريف","title":"357-","page":"ج2 ص38","text":"(وجاء آم عند تكسير الأمه ... كآكم مكسرا للأكمه)\nالثلاثي المذكر صفة فعل"},{"id":"shafiya:409","bookId":"shafiya","type":"section","seq":409,"chapter":"تعريف التصريف","title":"358-","page":"ج2 ص38","text":"(في نحو صعب غالبا صعاب ... والشيخ بالأشياخ يستطاب)"},{"id":"shafiya:410","bookId":"shafiya","type":"section","seq":410,"chapter":"تعريف التصريف","title":"359-","page":"ج2 ص38","text":"(وجاء ورد سحل وغدان ... والسمحاء الشيخة الضيفان)"},{"id":"shafiya:411","bookId":"shafiya","type":"section","seq":411,"chapter":"تعريف التصريف","title":"360-","page":"ج2 ص38","text":"(وجاءت الكهول جمع الكهل ... وهكذا رطلة في رطل)\nفعل"},{"id":"shafiya:412","bookId":"shafiya","type":"section","seq":412,"chapter":"تعريف التصريف","title":"361-","page":"ج2 ص38","text":"(جلف بأجلاف وأجلف ندر ... حر على الأحرار جمعه استمر)\nفعل"},{"id":"shafiya:413","bookId":"shafiya","type":"section","seq":413,"chapter":"تعريف التصريف","title":"362-","page":"ج2 ص38","text":"(في البطل الأبطال والذكران ... والنصف الحسان والإخوان)\nفعل"},{"id":"shafiya:414","bookId":"shafiya","type":"section","seq":414,"chapter":"تعريف التصريف","title":"363-","page":"ج2 ص38","text":"(في نكد أنكاد أو وجاع ... أو خشن مجموعها يشاع)"},{"id":"shafiya:415","bookId":"shafiya","type":"section","seq":415,"chapter":"تعريف التصريف","title":"364-","page":"ج2 ص38","text":"(وقد أتى أيضا وجاعى في وجع ... كذا حباطى وحذارى قد سمع)\nفعل"},{"id":"shafiya:416","bookId":"shafiya","type":"section","seq":416,"chapter":"تعريف التصريف","title":"365-","page":"ج2 ص38","text":"(في اليقظ الأيقاظ للجمع استقل ... وبابه التصحيح والتكسير قل)\nفعل"},{"id":"shafiya:417","bookId":"shafiya","type":"section","seq":417,"chapter":"تعريف التصريف","title":"366-","page":"ج2 ص38","text":"(في الجنب الأجناب والكل جمع ... بواوه للعاقلين إذ وضع)\nالصفات بالتصحيح"},{"id":"shafiya:418","bookId":"shafiya","type":"section","seq":418,"chapter":"تعريف التصريف","title":"367-","page":"ج2 ص39","text":"(أما الذي أنث من صفات ... فسالم لا غير كالعبلات)"},{"id":"shafiya:419","bookId":"shafiya","type":"section","seq":419,"chapter":"تعريف التصريف","title":"368-","page":"ج2 ص39","text":"(ولم يجىء فيها مكسر خرج ... إلا عبال وكماش وعلج)\nما زيادته مدة ثالثة اسما مذكرا فعال"},{"id":"shafiya:420","bookId":"shafiya","type":"section","seq":420,"chapter":"تعريف التصريف","title":"369-","page":"ج2 ص39","text":"(للاسم في نحو زمان أزمنه ... غالبة وفي مكان أمكنه)"},{"id":"shafiya:421","bookId":"shafiya","type":"section","seq":421,"chapter":"تعريف التصريف","title":"370-","page":"ج2 ص39","text":"(وقد أتى الغزلان ثم القذل ... وهكذا العنوق فيما نقلوا)\nفعال"},{"id":"shafiya:422","bookId":"shafiya","type":"section","seq":422,"chapter":"تعريف التصريف","title":"371-","page":"ج2 ص39","text":"(وفي حمار حمر وأحمره ... غالبة ففي سوار أسوره)"},{"id":"shafiya:423","bookId":"shafiya","type":"section","seq":423,"chapter":"تعريف التصريف","title":"372-","page":"ج2 ص39","text":"(وجاءت الصيران في الصوار ... واشتهرت شمائل الأبرار)\nفعال"},{"id":"shafiya:424","bookId":"shafiya","type":"section","seq":424,"chapter":"تعريف التصريف","title":"373-","page":"ج2 ص39","text":"(أغربة جمع غراب إذ تعد ... وجاء غربان وزقان قرد)"},{"id":"shafiya:425","bookId":"shafiya","type":"section","seq":425,"chapter":"تعريف التصريف","title":"374-","page":"ج2 ص39","text":"(وغلمة قلت وذب ندرا ... جمع غلام وذباب كسرا)\nالمؤنث منها بغير تاء"},{"id":"shafiya:426","bookId":"shafiya","type":"section","seq":426,"chapter":"تعريف التصريف","title":"375-","page":"ج2 ص39","text":"(وإن تؤنث فالجميع أعنق ... وأذرع وأعقب تتفق)"},{"id":"shafiya:427","bookId":"shafiya","type":"section","seq":427,"chapter":"تعريف التصريف","title":"376-","page":"ج2 ص39","text":"(وأمكن قد شذ في المكان ... لأنه مذكر البنيان)\nفعيل"},{"id":"shafiya:428","bookId":"shafiya","type":"section","seq":428,"chapter":"تعريف التصريف","title":"377-","page":"ج2 ص39","text":"(وفي رغيف رغف رغفان ... أرغفة وقلت الظلمان)"},{"id":"shafiya:429","bookId":"shafiya","type":"section","seq":429,"chapter":"تعريف التصريف","title":"378-","page":"ج2 ص39","text":"(وجاء بالفصال والأفائل ... والأنصباء في نصيب نائل)"},{"id":"shafiya:430","bookId":"shafiya","type":"section","seq":430,"chapter":"تعريف التصريف","title":"379-","page":"ج2 ص40","text":"(وربما جاء على وزن دسر ... مضاعفا نحو سرير وسرر)\nفعول"},{"id":"shafiya:431","bookId":"shafiya","type":"section","seq":431,"chapter":"تعريف التصريف","title":"380-","page":"ج2 ص40","text":"(وفي عمود عمد وأعمده ... في قلة وكثرة مطرده)"},{"id":"shafiya:432","bookId":"shafiya","type":"section","seq":432,"chapter":"تعريف التصريف","title":"381-","page":"ج2 ص40","text":"(وجاءت القعدان والأفلاء كما أتى الذنائب الملاء)\nذو المدة الثالثة مؤنثا بالتاء"},{"id":"shafiya:433","bookId":"shafiya","type":"section","seq":433,"chapter":"تعريف التصريف","title":"382-","page":"ج2 ص40","text":"(يجمع بالفعائل العلامه ... وهكذا ذؤابة عمامه)"},{"id":"shafiya:434","bookId":"shafiya","type":"section","seq":434,"chapter":"تعريف التصريف","title":"383-","page":"ج2 ص40","text":"(سفينة كذاك والحموله ... وجاء أيضا سفن معمولة)\nوما زيادته مدة ثالثة وصفا مذكرا فعال"},{"id":"shafiya:435","bookId":"shafiya","type":"section","seq":435,"chapter":"تعريف التصريف","title":"384-","page":"ج2 ص40","text":"(والجبناء في جبان يقع ... ويذكر الجياد ثم الصنع)\nفعال"},{"id":"shafiya:436","bookId":"shafiya","type":"section","seq":436,"chapter":"تعريف التصريف","title":"385-","page":"ج2 ص40","text":"(وفي هجان وكناز كنز ... كذا هجان عند جمع يبرز)\nفعال"},{"id":"shafiya:437","bookId":"shafiya","type":"section","seq":437,"chapter":"تعريف التصريف","title":"386-","page":"ج2 ص40","text":"(وفي شجاع جاء بالشجعان ... والشجعاء الغر والشجعان)\nفعيل"},{"id":"shafiya:438","bookId":"shafiya","type":"section","seq":438,"chapter":"تعريف التصريف","title":"387-","page":"ج2 ص40","text":"(وفي نذير نذر ثنيان ... أشراف اصدقاء والخصيان)"},{"id":"shafiya:439","bookId":"shafiya","type":"section","seq":439,"chapter":"تعريف التصريف","title":"388-","page":"ج2 ص40","text":"(وهم كرام كرماء قد سموا ... ثم ظروف وأشحة نموا)\nفعول"},{"id":"shafiya:440","bookId":"shafiya","type":"section","seq":440,"chapter":"تعريف التصريف","title":"389-","page":"ج2 ص40","text":"(وفي صبور صبر مشتهرا ... والودداء مثل الأعداء ترى)\nفعيل بمعنى مفعول"},{"id":"shafiya:441","bookId":"shafiya","type":"section","seq":441,"chapter":"تعريف التصريف","title":"390-","page":"ج2 ص40","text":"(فعيل مفعول يقاس فعلى ... في جمعه كمثل جرحى قتلى)"},{"id":"shafiya:442","bookId":"shafiya","type":"section","seq":442,"chapter":"تعريف التصريف","title":"391-","page":"ج2 ص41","text":"(وقد أتى فيه أسارى إذ جمع ... وشذ فيه القتلاء فاستمع)"},{"id":"shafiya:443","bookId":"shafiya","type":"section","seq":443,"chapter":"تعريف التصريف","title":"392-","page":"ج2 ص41","text":"(ولايجوز جمعه تصحيحا ... للفرق عن ذي فاعل صريحا)"},{"id":"shafiya:444","bookId":"shafiya","type":"section","seq":444,"chapter":"تعريف التصريف","title":"393-","page":"ج2 ص41","text":"(ونحو مرضى في مريض حملا ... وضعا على جرحى لوصف حصلا)"},{"id":"shafiya:445","bookId":"shafiya","type":"section","seq":445,"chapter":"تعريف التصريف","title":"394-","page":"ج2 ص41","text":"(وهم إذا كانوا عليه حملوا ... هلكى وموتى فالمريض أمثل)"},{"id":"shafiya:446","bookId":"shafiya","type":"section","seq":446,"chapter":"تعريف التصريف","title":"395-","page":"ج2 ص41","text":"(كحملهم في جمعهم أيامى ... على وجاعى وكذا يتامى)\nالمؤنث مما زيادته مدة ثالثة صفة"},{"id":"shafiya:447","bookId":"shafiya","type":"section","seq":447,"chapter":"تعريف التصريف","title":"396-","page":"ج2 ص41","text":"(صبيحة في الكلم الفصائح ... جاءت على الصباح والصبائح)"},{"id":"shafiya:448","bookId":"shafiya","type":"section","seq":448,"chapter":"تعريف التصريف","title":"397-","page":"ج2 ص41","text":"(والخلفاء جاء فيه قولا ... وجعله جمع الخليف أولى)"},{"id":"shafiya:449","bookId":"shafiya","type":"section","seq":449,"chapter":"تعريف التصريف","title":"398-","page":"ج2 ص41","text":"(مؤنث الفعول في اسم الفاعل ... يجمع كالعجوز بالفعائل)\nفاعل اسما مذكرا"},{"id":"shafiya:450","bookId":"shafiya","type":"section","seq":450,"chapter":"تعريف التصريف","title":"399-","page":"ج2 ص41","text":"(كواهل في كاهل الحيوان ... وجاء جنان مع الحجران)\nوهو مؤنثا"},{"id":"shafiya:451","bookId":"shafiya","type":"section","seq":451,"chapter":"تعريف التصريف","title":"400-","page":"ج2 ص41","text":"(في الاسم ذي التاء بحكم واصب ... كاثبة تأتي على كواثب)\nفاعلاء بمنزلته"},{"id":"shafiya:452","bookId":"shafiya","type":"section","seq":452,"chapter":"تعريف التصريف","title":"401-","page":"ج2 ص41","text":"(ونزلوا في الاسم فاعلاء ... منزل ذي التاء كقاصعاء)\nفاعل وصفا مذكرا"},{"id":"shafiya:453","bookId":"shafiya","type":"section","seq":453,"chapter":"تعريف التصريف","title":"402-","page":"ج2 ص41","text":"(ونحو جاهل على جهال ... وجهل في غالب الأحوال)"},{"id":"shafiya:454","bookId":"shafiya","type":"section","seq":454,"chapter":"تعريف التصريف","title":"403-","page":"ج2 ص41","text":"(وقد جرى فيه كثيرا فسقه ... كحاذق تجمعه بالحذقه)"},{"id":"shafiya:455","bookId":"shafiya","type":"section","seq":455,"chapter":"تعريف التصريف","title":"404-","page":"ج2 ص41","text":"(ناقصه يأتي على دعاة ... مثل رعاة العلم والسعاة)"},{"id":"shafiya:456","bookId":"shafiya","type":"section","seq":456,"chapter":"تعريف التصريف","title":"405-","page":"ج2 ص42","text":"(وقد أتى القعود والصحبان ... بزل تجار شعراء بانوا)"},{"id":"shafiya:457","bookId":"shafiya","type":"section","seq":457,"chapter":"تعريف التصريف","title":"406-","page":"ج2 ص42","text":"(ومن صفات العاقلين الفارس ... فشذ في تكسيره الفوارس)\nوهو مؤنثا"},{"id":"shafiya:458","bookId":"shafiya","type":"section","seq":458,"chapter":"تعريف التصريف","title":"407-","page":"ج2 ص42","text":"(رائضة من روض روائض ... كحائض من حيض حوائض)\nالمؤنث بالألف اسما"},{"id":"shafiya:459","bookId":"shafiya","type":"section","seq":459,"chapter":"تعريف التصريف","title":"408-","page":"ج2 ص42","text":"(اسم مؤنث بحرف الألف ... رابعة مختلف التصرف)"},{"id":"shafiya:460","bookId":"shafiya","type":"section","seq":460,"chapter":"تعريف التصريف","title":"409-","page":"ج2 ص42","text":"(فنحو صحراء على صحارى ... أنثى على الإناث فليدارا)\nوهو صفة"},{"id":"shafiya:461","bookId":"shafiya","type":"section","seq":461,"chapter":"تعريف التصريف","title":"410-","page":"ج2 ص42","text":"(الوصف كالحرمى على الحرامى ... عطشى على العطاش فليحاما)"},{"id":"shafiya:462","bookId":"shafiya","type":"section","seq":462,"chapter":"تعريف التصريف","title":"411-","page":"ج2 ص42","text":"(ونحو بطحاء على بطاح ... والعشراء بالعشارصاح)"},{"id":"shafiya:463","bookId":"shafiya","type":"section","seq":463,"chapter":"تعريف التصريف","title":"412-","page":"ج2 ص42","text":"(وجمع فعلى أفعل على الفعل ... كما تقول الحرميات الفضل)"},{"id":"shafiya:464","bookId":"shafiya","type":"section","seq":464,"chapter":"تعريف التصريف","title":"413-","page":"ج2 ص42","text":"(ذو الألف الخامس كالحبارى ... على الحباريات إذ يجارى) أفعل اسما"},{"id":"shafiya:465","bookId":"shafiya","type":"section","seq":465,"chapter":"تعريف التصريف","title":"414-","page":"ج2 ص42","text":"(أفعل الاسمي على الأفاعل ... كيف أتى التصريف كالأجادل)"},{"id":"shafiya:466","bookId":"shafiya","type":"section","seq":466,"chapter":"تعريف التصريف","title":"415-","page":"ج2 ص42","text":"(وقولهم حوص لجمع الأحوص ... في علم للمح وصف الحوص)\nوهو صفة"},{"id":"shafiya:467","bookId":"shafiya","type":"section","seq":467,"chapter":"تعريف التصريف","title":"416-","page":"ج2 ص42","text":"(وأفعل الوصف على الفعلان ... والفعل مثل الحمر والحمران)"},{"id":"shafiya:468","bookId":"shafiya","type":"section","seq":468,"chapter":"تعريف التصريف","title":"417-","page":"ج2 ص42","text":"(ولم يصحح جمعه ليفرقا ... عن أفعل التفضيل كي يحققا)"},{"id":"shafiya:469","bookId":"shafiya","type":"section","seq":469,"chapter":"تعريف التصريف","title":"418-","page":"ج2 ص42","text":"(وجاء في الخضراء خضراوات ... إذ غلبت فجاء فعلاوات)"},{"id":"shafiya:470","bookId":"shafiya","type":"section","seq":470,"chapter":"تعريف التصريف","title":"419-","page":"ج2 ص42","text":"(ويجمع الأفضل بالأفاضل ... والأفضلين السادة الأماثل)\nفعلان اسما"},{"id":"shafiya:471","bookId":"shafiya","type":"section","seq":471,"chapter":"تعريف التصريف","title":"420-","page":"ج2 ص43","text":"(يكسر الشيطان والسرحان ... على الشياطين كذا السلطان)\nوهو صفة"},{"id":"shafiya:472","bookId":"shafiya","type":"section","seq":472,"chapter":"تعريف التصريف","title":"421-","page":"ج2 ص43","text":"(ونحو غضبان على غضاب ... وبالسكارى جاء في الخطاب)"},{"id":"shafiya:473","bookId":"shafiya","type":"section","seq":473,"chapter":"تعريف التصريف","title":"422-","page":"ج2 ص43","text":"(أربعة ضمت على فعالى ... وفتحها جاز فلا يبالى)"},{"id":"shafiya:474","bookId":"shafiya","type":"section","seq":474,"chapter":"تعريف التصريف","title":"423-","page":"ج2 ص43","text":"(وهي كسالى بعدها سكارى ... ثم عجالى بعدها غيارى)\nفيعل"},{"id":"shafiya:475","bookId":"shafiya","type":"section","seq":475,"chapter":"تعريف التصريف","title":"424-","page":"ج2 ص43","text":"(في فيعل جياد أبيناء ... كذاك أموات بها يجاء)\nما استغني فيه بالتصحيح"},{"id":"shafiya:476","bookId":"shafiya","type":"section","seq":476,"chapter":"تعريف التصريف","title":"425-","page":"ج2 ص43","text":"(واستغن بالتصحيح في فعال ... ونحوه من مشبه الأفعال)"},{"id":"shafiya:477","bookId":"shafiya","type":"section","seq":477,"chapter":"تعريف التصريف","title":"426-","page":"ج2 ص43","text":"(كمثل حسانون صديقونا ... معطون مكرمون مرزوقونا)"},{"id":"shafiya:478","bookId":"shafiya","type":"section","seq":478,"chapter":"تعريف التصريف","title":"427-","page":"ج2 ص43","text":"(وبالمفاعيل وبالمفاعل ... قد وقع السماع كالمطافل)\nتكسير الرباعي"},{"id":"shafiya:479","bookId":"shafiya","type":"section","seq":479,"chapter":"تعريف التصريف","title":"428-","page":"ج2 ص43","text":"(وفي الرباعي الذي يجرد ... فعالل جمع له مطرد)"},{"id":"shafiya:480","bookId":"shafiya","type":"section","seq":480,"chapter":"تعريف التصريف","title":"429-","page":"ج2 ص43","text":"(في نحو قرطاس قراطيس وما ... وازهما مجراهما قد لزما)"},{"id":"shafiya:481","bookId":"shafiya","type":"section","seq":481,"chapter":"تعريف التصريف","title":"430-","page":"ج2 ص43","text":"(ثم الجواربة والجعافره ... في الأعجمي والنسيب وافره)\nوالخماسي"},{"id":"shafiya:482","bookId":"shafiya","type":"section","seq":482,"chapter":"تعريف التصريف","title":"431-","page":"ج2 ص43","text":"(واستكره التكسير في الخماسي ... بحذف حرف منه للإلباس)\nواسم الجمع"},{"id":"shafiya:483","bookId":"shafiya","type":"section","seq":483,"chapter":"تعريف التصريف","title":"432-","page":"ج2 ص43","text":"(وباب تمر ليس جمعا في الأصح ... وغير مصنوع لوضعه صلح)"},{"id":"shafiya:484","bookId":"shafiya","type":"section","seq":484,"chapter":"تعريف التصريف","title":"433-","page":"ج2 ص43","text":"(وليس بالقياس مثل اللبن ... كذا قلنس وسفين منحني)"},{"id":"shafiya:485","bookId":"shafiya","type":"section","seq":485,"chapter":"تعريف التصريف","title":"434-","page":"ج2 ص44","text":"(وكمأة وجبأة بعكس ذا ... واحدها بغير تاء أخذا)"},{"id":"shafiya:486","bookId":"shafiya","type":"section","seq":486,"chapter":"تعريف التصريف","title":"435-","page":"ج2 ص44","text":"(ونحو ركب ليس جمعا في الأحق ... كجامل ثم سراة وحلق)"},{"id":"shafiya:487","bookId":"shafiya","type":"section","seq":487,"chapter":"تعريف التصريف","title":"436-","page":"ج2 ص44","text":"(وليس جمعا فرهة ولاغزي ... وهكذا التؤام غير ملغز)\nشواذ التكسير"},{"id":"shafiya:488","bookId":"shafiya","type":"section","seq":488,"chapter":"تعريف التصريف","title":"437-","page":"ج2 ص44","text":"(وقد أتى من جهة السماع ... بعض الموازين بالاتساع)"},{"id":"shafiya:489","bookId":"shafiya","type":"section","seq":489,"chapter":"تعريف التصريف","title":"438-","page":"ج2 ص44","text":"(مثل أحاديث مع الأهالي ... كذا أعاريض مع الليالي)\nجمع الجمع"},{"id":"shafiya:490","bookId":"shafiya","type":"section","seq":490,"chapter":"تعريف التصريف","title":"439-","page":"ج2 ص44","text":"(والجمع قد يجمع كالجمائل ... كذا بيوتات أولي الفضائل)"},{"id":"shafiya:491","bookId":"shafiya","type":"section","seq":491,"chapter":"تعريف التصريف","title":"التقاء الساكنين","page":"ج2 ص44","text":"المغتفر منه"},{"id":"shafiya:492","bookId":"shafiya","type":"section","seq":492,"chapter":"تعريف التصريف","title":"440-","page":"ج2 ص44","text":"(في الوقف جاز الالتقاء مطلقا ... من حرف مد أو سواه منتقى)"},{"id":"shafiya:493","bookId":"shafiya","type":"section","seq":493,"chapter":"تعريف التصريف","title":"441-","page":"ج2 ص44","text":"(وجاز في المدغم مسبوقا بمد ... في كلمة كالضالين إذ يشد)"},{"id":"shafiya:494","bookId":"shafiya","type":"section","seq":494,"chapter":"تعريف التصريف","title":"442-","page":"ج2 ص44","text":"(وفي الذي عد ولم يركب ... وقفا ووصلا كتهجي الكتب)"},{"id":"shafiya:495","bookId":"shafiya","type":"section","seq":495,"chapter":"تعريف التصريف","title":"443-","page":"ج2 ص44","text":"(ونحو الأمير زان المجلسا ... وآيمن الله لئلا يلبسا)"},{"id":"shafiya:496","bookId":"shafiya","type":"section","seq":496,"chapter":"تعريف التصريف","title":"444-","page":"ج2 ص44","text":"(وجاز إي الله ولاها الله ... ظاهرة المد بلا اشتباه)"},{"id":"shafiya:497","bookId":"shafiya","type":"section","seq":497,"chapter":"تعريف التصريف","title":"445-","page":"ج2 ص44","text":"(وحلقتا البطان بالمد يشذ ... إذ ليس ثان مدغما كما أخذ)\nيحذف أول الساكنين إن كان مدة"},{"id":"shafiya:498","bookId":"shafiya","type":"section","seq":498,"chapter":"تعريف التصريف","title":"446-","page":"ج2 ص44","text":"(في غير ما قد مر والسابق مد ... يحذف مد قل أعد ولم يعد)"},{"id":"shafiya:499","bookId":"shafiya","type":"section","seq":499,"chapter":"تعريف التصريف","title":"447-","page":"ج2 ص44","text":"(واغزن وارمن كذا اغز وارمي ... ونحن نغزوا القوم نرمي المرمي)\nويحرك إن كان غير ذلك"},{"id":"shafiya:500","bookId":"shafiya","type":"section","seq":500,"chapter":"تعريف التصريف","title":"448-","page":"ج2 ص45","text":"(لم يعن بالتحريك في خف الأسد ... ومثله خلاف خافن الأحد)"},{"id":"shafiya:501","bookId":"shafiya","type":"section","seq":501,"chapter":"تعريف التصريف","title":"449-","page":"ج2 ص45","text":"(ودون مد حركوا في أوله ... نحو اذهب اذهب وكذا لم أبله)"},{"id":"shafiya:502","bookId":"shafiya","type":"section","seq":502,"chapter":"تعريف التصريف","title":"450-","page":"ج2 ص45","text":"(كذاك ميم الله حيث كانا ... مثل اخشوا الله اخشي الرحمانا)"},{"id":"shafiya:503","bookId":"shafiya","type":"section","seq":503,"chapter":"تعريف التصريف","title":"451-","page":"ج2 ص45","text":"(ومن هنا قيل اخشون واخشين ... لأنه كذي انفصال قد قرن)"},{"id":"shafiya:504","bookId":"shafiya","type":"section","seq":504,"chapter":"تعريف التصريف","title":"452-","page":"ج2 ص45","text":"(إلا بنحو انطلق عن مكاني ... ووالد لم يلده أبان)"},{"id":"shafiya:505","bookId":"shafiya","type":"section","seq":505,"chapter":"تعريف التصريف","title":"453-","page":"ج2 ص45","text":"(ونحو لم يرد في تميم ... إذ حرك الأخير لتتميم)"},{"id":"shafiya:506","bookId":"shafiya","type":"section","seq":506,"chapter":"تعريف التصريف","title":"454-","page":"ج2 ص45","text":"(وليس يتقه به على الأصح ... فالهاء فيه مضمر كما وضح)\nالكسر الأصل في التحريك للساكنين"},{"id":"shafiya:507","bookId":"shafiya","type":"section","seq":507,"chapter":"تعريف التصريف","title":"455-","page":"ج2 ص45","text":"(والأصل في التحريك كسر فمتى ... خولف فالخلف لعارض أتى)"},{"id":"shafiya:508","bookId":"shafiya","type":"section","seq":508,"chapter":"تعريف التصريف","title":"456-","page":"ج2 ص45","text":"(كضم ميم الجمع أو مذ ملزما ... وفتح ميم الله كي يفخما)"},{"id":"shafiya:509","bookId":"shafiya","type":"section","seq":509,"chapter":"تعريف التصريف","title":"457-","page":"ج2 ص45","text":"(وسوغ ضم حيث ضم أصلا ... في لفظ ثان بعده تحصلا)"},{"id":"shafiya:510","bookId":"shafiya","type":"section","seq":510,"chapter":"تعريف التصريف","title":"458-","page":"ج2 ص45","text":"(كقالت اخرج قالت اغزي من ملك ... لا قالت ارموا وإن امرؤ هلك)"},{"id":"shafiya:511","bookId":"shafiya","type":"section","seq":511,"chapter":"تعريف التصريف","title":"459-","page":"ج2 ص45","text":"(ولا إن الحكم فإن اللاما ... مفردة برأسها مقاما)"},{"id":"shafiya:512","bookId":"shafiya","type":"section","seq":512,"chapter":"تعريف التصريف","title":"460-","page":"ج2 ص45","text":"(وحسن ضم في اخشو الرحمانا ... عكس لو استطعنا خرجنا الآنا)"},{"id":"shafiya:513","bookId":"shafiya","type":"section","seq":513,"chapter":"تعريف التصريف","title":"461-","page":"ج2 ص45","text":"(ومثل سوغ الضم والفتح معا ... في رد كي يخف أو كي يتبعا)"},{"id":"shafiya:514","bookId":"shafiya","type":"section","seq":514,"chapter":"تعريف التصريف","title":"462-","page":"ج2 ص45","text":"(لا نحو رد المنتقى في الأكثر ... مما يليه ساكن فليكسر)"},{"id":"shafiya:515","bookId":"shafiya","type":"section","seq":515,"chapter":"تعريف التصريف","title":"463-","page":"ج2 ص45","text":"(وكالتزام الفتح للتخفف ... في ردها بالهاء قبل الألف)"},{"id":"shafiya:516","bookId":"shafiya","type":"section","seq":516,"chapter":"تعريف التصريف","title":"464-","page":"ج2 ص45","text":"(ومثل فرض الضم بالفصيح ... في رده والكسر ذو تقبيح)"},{"id":"shafiya:517","bookId":"shafiya","type":"section","seq":517,"chapter":"تعريف التصريف","title":"465-","page":"ج2 ص45","text":"(وثعلب غلط إذ أجازا ... فتحا بحمله على ما جازا)"},{"id":"shafiya:518","bookId":"shafiya","type":"section","seq":518,"chapter":"تعريف التصريف","title":"466-","page":"ج2 ص45","text":"(ومثل حتم الفتح في من الصحف ... عكس من ابني وخلافه ضعف)"},{"id":"shafiya:519","bookId":"shafiya","type":"section","seq":519,"chapter":"تعريف التصريف","title":"467-","page":"ج2 ص46","text":"(وعن على الأصل بكسر ما ثقل ... والضم يستضعف في عن الرجل)"},{"id":"shafiya:520","bookId":"shafiya","type":"section","seq":520,"chapter":"تعريف التصريف","title":"468-","page":"ج2 ص46","text":"(وجاء في مغتفر هذا النقر ... وعلمه دأبة هي البقر)"},{"id":"shafiya:521","bookId":"shafiya","type":"section","seq":521,"chapter":"تعريف التصريف","title":"469-","page":"ج2 ص46","text":"(ولم يجىء في نحو تأمروني ... مشددا تحريك ذي السكون)"},{"id":"shafiya:522","bookId":"shafiya","type":"section","seq":522,"chapter":"تعريف التصريف","title":"470-","page":"ج2 ص46","text":"(لا يبتدا إلا بما تحركا ... وقف على الساكن لا ما حركا)","bab":"باب الابتداء"},{"id":"shafiya:523","bookId":"shafiya","type":"section","seq":523,"chapter":"تعريف التصريف","title":"471-","page":"ج2 ص46","text":"(فإن يكن أول لفظ سكنا ... يبدأ بهمز الوصل حتى يتقنا)","bab":"باب الابتداء"},{"id":"shafiya:524","bookId":"shafiya","type":"section","seq":524,"chapter":"تعريف التصريف","title":"472-","page":"ج2 ص46","text":"(وذاك في عشرة أسماء سمع ... اثنان واثنتان وابن قد تبع)","bab":"باب الابتداء"},{"id":"shafiya:525","bookId":"shafiya","type":"section","seq":525,"chapter":"تعريف التصريف","title":"473-","page":"ج2 ص46","text":"(وابنه است وابنم مع ايمن ... وامرأة ثم امرؤ واسم سني)","bab":"باب الابتداء"},{"id":"shafiya:526","bookId":"shafiya","type":"section","seq":526,"chapter":"تعريف التصريف","title":"474-","page":"ج2 ص46","text":"(وهكذا في كل مصدر عرف ... أربعة في فعله بعد الألف)","bab":"باب الابتداء"},{"id":"shafiya:527","bookId":"shafiya","type":"section","seq":527,"chapter":"تعريف التصريف","title":"475-","page":"ج2 ص46","text":"(كالانتهاض ثم الاستنهاض ... وفعله من أمر أو من ماضي)","bab":"باب الابتداء"},{"id":"shafiya:528","bookId":"shafiya","type":"section","seq":528,"chapter":"تعريف التصريف","title":"476-","page":"ج2 ص46","text":"(وصيغة الأمر من المجرد ... ولام تعريف وميم مفرد)","bab":"باب الابتداء"},{"id":"shafiya:529","bookId":"shafiya","type":"section","seq":529,"chapter":"تعريف التصريف","title":"477-","page":"ج2 ص46","text":"(ويكسر الهمز سوى ما حصلا ... بعد سكون فيه ضم أصلا)","bab":"باب الابتداء"},{"id":"shafiya:530","bookId":"shafiya","type":"section","seq":530,"chapter":"تعريف التصريف","title":"478-","page":"ج2 ص46","text":"(والضم كاقتليه واغزي لا ارموا ... والفتح في آل وايمن وايم)","bab":"باب الابتداء"},{"id":"shafiya:531","bookId":"shafiya","type":"section","seq":531,"chapter":"تعريف التصريف","title":"479-","page":"ج2 ص46","text":"(وقطعه لحن في الاختيار ... وشذ في الشعر للاضطرار)","bab":"باب الابتداء"},{"id":"shafiya:532","bookId":"shafiya","type":"section","seq":532,"chapter":"تعريف التصريف","title":"480-","page":"ج2 ص46","text":"(والتزموا أن يجعلوه ألفا ... لا بين بين في فصيح ألفا)","bab":"باب الابتداء"},{"id":"shafiya:533","bookId":"shafiya","type":"section","seq":533,"chapter":"تعريف التصريف","title":"481-","page":"ج2 ص46","text":"(في نحو آلأمير قام للخفا ... وآيمن الله يمين الشرفا)","bab":"باب الابتداء"},{"id":"shafiya:534","bookId":"shafiya","type":"section","seq":534,"chapter":"تعريف التصريف","title":"482-","page":"ج2 ص46","text":"(أما سكون الهاء من لهو الفتى ... ونحوه فهو لعارض أتى)","bab":"باب الابتداء"},{"id":"shafiya:535","bookId":"shafiya","type":"section","seq":535,"chapter":"تعريف التصريف","title":"483-","page":"ج2 ص46","text":"(كذاك لام الأمر في فليفرحوا ... وشبهوا أهو وثم ليسرحوا)","bab":"باب الابتداء"},{"id":"shafiya:536","bookId":"shafiya","type":"section","seq":536,"chapter":"تعريف التصريف","title":"484-","page":"ج2 ص46","text":"(وأن يمل هو قليل عرفا ... إذ سبب الإسكان فيه ضعفا)","bab":"باب الابتداء"},{"id":"shafiya:537","bookId":"shafiya","type":"section","seq":537,"chapter":"تعريف التصريف","title":"485-","page":"ج2 ص47","text":"(الوقف في الكلام قطع الكلمه ... عما تلا وهو وجوه ملزمه)","bab":"باب الوقف"},{"id":"shafiya:538","bookId":"shafiya","type":"section","seq":538,"chapter":"تعريف التصريف","title":"486-","page":"ج2 ص47","text":"(اختلفت في الحسن والمكان ... أولها مجرد الإسكان)","bab":"باب الوقف"},{"id":"shafiya:539","bookId":"shafiya","type":"section","seq":539,"chapter":"تعريف التصريف","title":"487-","page":"ج2 ص47","text":"(والروم إظهار خفي الحركة ... وقل في المفتوح فاعرف مدركه)","bab":"باب الوقف"},{"id":"shafiya:540","bookId":"shafiya","type":"section","seq":540,"chapter":"تعريف التصريف","title":"488-","page":"ج2 ص47","text":"(إشمام مضموم بضمات الشفه ... من بعد ما أسكنته كي تصفه)","bab":"باب الوقف"},{"id":"shafiya:541","bookId":"shafiya","type":"section","seq":541,"chapter":"تعريف التصريف","title":"489-","page":"ج2 ص47","text":"(ولا يرى الإشمام والروم لدى ... أكثرهم في هاء تأنيث بدا)","bab":"باب الوقف"},{"id":"shafiya:542","bookId":"shafiya","type":"section","seq":542,"chapter":"تعريف التصريف","title":"490-","page":"ج2 ص47","text":"(وهكذا في الحركات العارضه ... وميم جمع كدهاهم عارضه)","bab":"باب الوقف"},{"id":"shafiya:543","bookId":"shafiya","type":"section","seq":543,"chapter":"تعريف التصريف","title":"491-","page":"ج2 ص47","text":"(ومن وجوه الوقف إبدال الألف ... في النصب عن تنوينه كما عرف)","bab":"باب الوقف"},{"id":"shafiya:544","bookId":"shafiya","type":"section","seq":544,"chapter":"تعريف التصريف","title":"492-","page":"ج2 ص47","text":"(وفي إذا وفي اضربن بلا مفر ... لا الواو والياء لدى رفع وجر)","bab":"باب الوقف"},{"id":"shafiya:545","bookId":"shafiya","type":"section","seq":545,"chapter":"تعريف التصريف","title":"493-","page":"ج2 ص47","text":"(وباتفاق يبدلون الألفا ... للوقف في باب رحى مثل قفا)","bab":"باب الوقف"},{"id":"shafiya:546","bookId":"shafiya","type":"section","seq":546,"chapter":"تعريف التصريف","title":"494-","page":"ج2 ص47","text":"(وقلبها وقلب كل ألف ... همزا لدى الوقف ضعيف فقف)","bab":"باب الوقف"},{"id":"shafiya:547","bookId":"shafiya","type":"section","seq":547,"chapter":"تعريف التصريف","title":"495-","page":"ج2 ص47","text":"(كذاك قلب مدة الحبلى إلى ... همز أو واو وياء فاعدلا)","bab":"باب الوقف"},{"id":"shafiya:548","bookId":"shafiya","type":"section","seq":548,"chapter":"تعريف التصريف","title":"496-","page":"ج2 ص47","text":"(والوقف في أمثال رحمة بها ... في أكثر الأحوال كي تنتبها)","bab":"باب الوقف"},{"id":"shafiya:549","bookId":"shafiya","type":"section","seq":549,"chapter":"تعريف التصريف","title":"497-","page":"ج2 ص47","text":"(وقل في هيهات وقفا فقفا ... وسوقه في سالمات ضعفا)","bab":"باب الوقف"},{"id":"shafiya:550","bookId":"shafiya","type":"section","seq":550,"chapter":"تعريف التصريف","title":"498-","page":"ج2 ص47","text":"(والوقف في العرقات بالهاء متى ... فتحته نصبا وإلا فبتا)","bab":"باب الوقف"},{"id":"shafiya:551","bookId":"shafiya","type":"section","seq":551,"chapter":"تعريف التصريف","title":"499-","page":"ج2 ص47","text":"(وفتح من قال ثلاثة أربعه ... نقل لتحريكه همز أتبعه)","bab":"باب الوقف"},{"id":"shafiya:552","bookId":"shafiya","type":"section","seq":552,"chapter":"تعريف التصريف","title":"500-","page":"ج2 ص47","text":"(خلاف ميم الله في القرآن ... إذ التقى بالوصل ساكنان)","bab":"باب الوقف"},{"id":"shafiya:553","bookId":"shafiya","type":"section","seq":553,"chapter":"تعريف التصريف","title":"501-","page":"ج2 ص47","text":"(ومن وجوهه زيادة الألف ... في أنا من ثم بلكنا وقف)","bab":"باب الوقف"},{"id":"shafiya:554","bookId":"shafiya","type":"section","seq":554,"chapter":"تعريف التصريف","title":"502-","page":"ص0","text":"(والوقف بالهاء قليل في أنه ... وقوله مه فاعرفن موطنه)","bab":"باب الوقف"},{"id":"shafiya:555","bookId":"shafiya","type":"section","seq":555,"chapter":"تعريف التصريف","title":"503-","page":"ص0","text":"(وقد أتى الوقف بهاء ملزمه ... في وقه وضرب مه ومثل مه)","bab":"باب الوقف"},{"id":"shafiya:556","bookId":"shafiya","type":"section","seq":556,"chapter":"تعريف التصريف","title":"504-","page":"ص0","text":"(وجاز في اخشه وارم واغزه يا فتى ... علام حتى مه إلى مه مثبتا)","bab":"باب الوقف"},{"id":"shafiya:557","bookId":"shafiya","type":"section","seq":557,"chapter":"تعريف التصريف","title":"505-","page":"ص0","text":"(وكل ما تحريكه موجها ... لم يك إعرابا ولا مشبها)","bab":"باب الوقف"},{"id":"shafiya:558","bookId":"shafiya","type":"section","seq":558,"chapter":"تعريف التصريف","title":"506-","page":"ص0","text":"(فلم يجز ذلك في الماضي ولا ... في باب يا أحمد أو لا رجلا)","bab":"باب الوقف"},{"id":"shafiya:559","bookId":"shafiya","type":"section","seq":559,"chapter":"تعريف التصريف","title":"507-","page":"ص0","text":"(وجائز إلحاقه في ههنا ... وهؤلاء ونحوه وأحسنا)","bab":"باب الوقف"},{"id":"shafiya:560","bookId":"shafiya","type":"section","seq":560,"chapter":"تعريف التصريف","title":"508-","page":"ص0","text":"(وجاز حذف الياء من غلامي ... حرك أو سكن كالمرامي)","bab":"باب الوقف"},{"id":"shafiya:561","bookId":"shafiya","type":"section","seq":561,"chapter":"تعريف التصريف","title":"509-","page":"ص0","text":"(إثباتها أكثر عكس داع ... وذكرها في يا مري إجماعي)","bab":"باب الوقف"},{"id":"shafiya:562","bookId":"shafiya","type":"section","seq":562,"chapter":"تعريف التصريف","title":"510-","page":"ص0","text":"(يفصح ذكر الواء والياء كما ... حذفهما في السجع حتى يحكما)","bab":"باب الوقف"},{"id":"shafiya:563","bookId":"shafiya","type":"section","seq":563,"chapter":"تعريف التصريف","title":"511-","page":"ص0","text":"(والحذف في أمثال لم ترم يقل ... سجعا كذا في صنعوا كما نقل)","bab":"باب الوقف"},{"id":"shafiya:564","bookId":"shafiya","type":"section","seq":564,"chapter":"تعريف التصريف","title":"512-","page":"ص0","text":"(ويحذف الواو لوقف مطلقا ... في صده وصدهم إن ألحقا)","bab":"باب الوقف"},{"id":"shafiya:565","bookId":"shafiya","type":"section","seq":565,"chapter":"تعريف التصريف","title":"513-","page":"ص0","text":"(وتحذف الياء كذاك من به ... وهذه مثل ته فانتبه)","bab":"باب الوقف"},{"id":"shafiya:566","bookId":"shafiya","type":"section","seq":566,"chapter":"تعريف التصريف","title":"514-","page":"ص0","text":"(ويبدل الهمزة بعض العرب ... بحرف تحريكته كذي الخبي)","bab":"باب الوقف"},{"id":"shafiya:567","bookId":"shafiya","type":"section","seq":567,"chapter":"تعريف التصريف","title":"515-","page":"ص0","text":"(وذي الكلي وذي البطي وذي الردي ... هذا الردو رد الردى في المورد)","bab":"باب الوقف"},{"id":"shafiya:568","bookId":"shafiya","type":"section","seq":568,"chapter":"تعريف التصريف","title":"516-","page":"ص0","text":"(وبعضهم يقول حيث يسمع ... هذا الردي من البطو فيتبع)","bab":"باب الوقف"},{"id":"shafiya:569","bookId":"shafiya","type":"section","seq":569,"chapter":"تعريف التصريف","title":"517-","page":"ص0","text":"(وضعفوا حرفا صحيحا حركا ... لا همزة ما قبله تحركا)","bab":"باب الوقف"},{"id":"shafiya:570","bookId":"shafiya","type":"section","seq":570,"chapter":"تعريف التصريف","title":"518-","page":"ص0","text":"(وهو قليل مثل شد جعفر ... شذ القصبا والفصيح مضطر)","bab":"باب الوقف"},{"id":"shafiya:571","bookId":"shafiya","type":"section","seq":571,"chapter":"تعريف التصريف","title":"519-","page":"ص0","text":"(ونقل تحريكه ما قد اتصل ... بساكن صح سوى الفتحة قل)","bab":"باب الوقف"},{"id":"shafiya:572","bookId":"shafiya","type":"section","seq":572,"chapter":"تعريف التصريف","title":"520-","page":"ص0","text":"(تقول قد شاع خبو جاء بكر ... خذ بخبي عند بكر حين يكر)","bab":"باب الوقف"},{"id":"shafiya:573","bookId":"shafiya","type":"section","seq":573,"chapter":"تعريف التصريف","title":"521-","page":"ص0","text":"(وجاء في الهمزة نقل الفتح ... كيخرج الخبا بغير قدح)","bab":"باب الوقف"},{"id":"shafiya:574","bookId":"shafiya","type":"section","seq":574,"chapter":"تعريف التصريف","title":"522-","page":"ص0","text":"(ولا تقل لا أشتري البكر ولا ... هذا حبر ومن قفل إذ أهملا)","bab":"باب الوقف"},{"id":"shafiya:575","bookId":"shafiya","type":"section","seq":575,"chapter":"تعريف التصريف","title":"523-","page":"ص0","text":"(وجائز هذا الردؤ من البطىء ... وبعضهم يتبع من غير بطىء)","bab":"باب الوقف"},{"id":"shafiya:576","bookId":"shafiya","type":"section","seq":576,"chapter":"تعريف التصريف","title":"524-","page":"ص0","text":"(مقصورهم ما ختمه بالألف ... من غير همز كالعصا في الطرف)","bab":"باب المقصور والممدود"},{"id":"shafiya:577","bookId":"shafiya","type":"section","seq":577,"chapter":"تعريف التصريف","title":"525-","page":"ص0","text":"(ممدودهم ما آخر منه ألف ... يتلوه همز كعطاء لا يقف)","bab":"باب المقصور والممدود"},{"id":"shafiya:578","bookId":"shafiya","type":"section","seq":578,"chapter":"تعريف التصريف","title":"526-","page":"ص0","text":"(قياس قصر أن يكون الفتح في ... نظيره الصحيح قبل الطرف)","bab":"باب المقصور والممدود"},{"id":"shafiya:579","bookId":"shafiya","type":"section","seq":579,"chapter":"تعريف التصريف","title":"527-","page":"ص0","text":"(قياس مد أن يكون الطرف ... يسبقه من النظير الألف)","bab":"باب المقصور والممدود"},{"id":"shafiya:580","bookId":"shafiya","type":"section","seq":580,"chapter":"تعريف التصريف","title":"528-","page":"ص0","text":"(فالقصر في معطى ومجتبي وجب ... إذ النظير مكرم ومنتخب)","bab":"باب المقصور والممدود"},{"id":"shafiya:581","bookId":"shafiya","type":"section","seq":581,"chapter":"تعريف التصريف","title":"529-","page":"ص0","text":"(ومصدر كاسم الزمان فاقصرا ... ملهى ومغزى إذ يوازي منصرا)","bab":"باب المقصور والممدود"},{"id":"shafiya:582","bookId":"shafiya","type":"section","seq":582,"chapter":"تعريف التصريف","title":"530-","page":"ص0","text":"(كذاك في مصدر فعل كفعل ... أفعل أو فعلان فيه أو فعل)","bab":"باب المقصور والممدود"},{"id":"shafiya:583","bookId":"shafiya","type":"section","seq":583,"chapter":"تعريف التصريف","title":"531-","page":"ص0","text":"(مثل الصدى أو الطوى أو العشى ... موازيات فرقا أوعطشا)","bab":"باب المقصور والممدود"},{"id":"shafiya:584","bookId":"shafiya","type":"section","seq":584,"chapter":"تعريف التصريف","title":"532-","page":"ص0","text":"(شذ غراء من غر أي مولع ... يقصره على القاس الأصمعي)","bab":"باب المقصور والممدود"},{"id":"shafiya:585","bookId":"shafiya","type":"section","seq":585,"chapter":"تعريف التصريف","title":"533-","page":"ص0","text":"(يقصر جمع فعلة أو فعلة ... مثل عرى ثم جزى للعلة)","bab":"باب المقصور والممدود"},{"id":"shafiya:586","bookId":"shafiya","type":"section","seq":586,"chapter":"تعريف التصريف","title":"534-","page":"ص0","text":"(يمد الاشتراء كالرماء ... للاقتتال والنزال الجائي)","bab":"باب المقصور والممدود"},{"id":"shafiya:587","bookId":"shafiya","type":"section","seq":587,"chapter":"تعريف التصريف","title":"535-","page":"ص0","text":"(والصوت ذو الضم في الافتتاح ... مثل العواء فهو كالنباح)","bab":"باب المقصور والممدود"},{"id":"shafiya:588","bookId":"shafiya","type":"section","seq":588,"chapter":"تعريف التصريف","title":"536-","page":"ص0","text":"(كذا يمد مفرد لأقبيه ... وفي الندا شذ بناء أنديه)","bab":"باب المقصور والممدود"},{"id":"shafiya:589","bookId":"shafiya","type":"section","seq":589,"chapter":"تعريف التصريف","title":"537-","page":"ص0","text":"(ولا نظير للسماعي يرى ... مثل الصفاء والصفا فليبصرا)","bab":"باب المقصور والممدود"},{"id":"shafiya:590","bookId":"shafiya","type":"section","seq":590,"chapter":"تعريف التصريف","title":"باب ذي الزيادة","page":"ص0","text":"حروف الزيادة","bab":"باب ذي الزيادة"},{"id":"shafiya:591","bookId":"shafiya","type":"section","seq":591,"chapter":"تعريف التصريف","title":"538-","page":"ص0","text":"(سألتمونيها تزاد مطلقا ... وغيرها مضعفا أو ملحقا)\nمعنى الإلحاق","bab":"باب ذي الزيادة"},{"id":"shafiya:592","bookId":"shafiya","type":"section","seq":592,"chapter":"تعريف التصريف","title":"539-","page":"ص0","text":"(والقصد بالإلحاق أينما بدا ... جعل مثال كمثال أزيدا)","bab":"باب ذي الزيادة"},{"id":"shafiya:593","bookId":"shafiya","type":"section","seq":593,"chapter":"تعريف التصريف","title":"540-","page":"ص0","text":"(فقردد كجعفر لا مقتل ... إذ قيس في معنى المكان مفعل)","bab":"باب ذي الزيادة"},{"id":"shafiya:594","bookId":"shafiya","type":"section","seq":594,"chapter":"تعريف التصريف","title":"541-","page":"ص0","text":"(وهكذا صدق مثل أصدقا ... قد قيس للمعنى فليس ملحقا)","bab":"باب ذي الزيادة"},{"id":"shafiya:595","bookId":"shafiya","type":"section","seq":595,"chapter":"تعريف التصريف","title":"542-","page":"ص0","text":"(وخالف المصدر من ذي أفعلا ... وفعل المصدر من ذي فعللا)","bab":"باب ذي الزيادة"},{"id":"shafiya:596","bookId":"shafiya","type":"section","seq":596,"chapter":"تعريف التصريف","title":"543-","page":"ص0","text":"(ولم يصادف ألف الإلحاق ... في الاسم حشوا حسب الإطلاق)","bab":"باب ذي الزيادة"},{"id":"shafiya:597","bookId":"shafiya","type":"section","seq":597,"chapter":"تعريف التصريف","title":"544-","page":"ص0","text":"(لأنها يلزم أن تحركا ... إن كسرت أو صغرت فليدركا)\nما تعرف به الزيادة","bab":"باب ذي الزيادة"},{"id":"shafiya:598","bookId":"shafiya","type":"section","seq":598,"chapter":"تعريف التصريف","title":"545-","page":"ص0","text":"(ويعرف الزائد باشتقاق ... والفقد للنظير في الإطلاق)","bab":"باب ذي الزيادة"},{"id":"shafiya:599","bookId":"shafiya","type":"section","seq":599,"chapter":"تعريف التصريف","title":"546-","page":"ص0","text":"(وكثرة ازدياد ما يزاد ... وعندما تعارض اجتهاد)\nالاشتقاق المحقق مقدم","bab":"باب ذي الزيادة"},{"id":"shafiya:600","bookId":"shafiya","type":"section","seq":600,"chapter":"تعريف التصريف","title":"547-","page":"ص0","text":"(والاشتقاق حيثما تحققا ... مقدم على الجميع مطلقا)","bab":"باب ذي الزيادة"},{"id":"shafiya:601","bookId":"shafiya","type":"section","seq":601,"chapter":"تعريف التصريف","title":"548-","page":"ص0","text":"(من أجل ذا ثلث حكما عنسل ... ونئدل وشأمل وشمأل)","bab":"باب ذي الزيادة"},{"id":"shafiya:602","bookId":"shafiya","type":"section","seq":602,"chapter":"تعريف التصريف","title":"549-","page":"ص0","text":"(حطائط ثم بلغن فرسن ... دلامص قمارص ورعشن)","bab":"باب ذي الزيادة"},{"id":"shafiya:603","bookId":"shafiya","type":"section","seq":603,"chapter":"تعريف التصريف","title":"550-","page":"ص0","text":"(وترنموت زرقم هرماس ... وبعده قنعاس أو فرناس)","bab":"باب ذي الزيادة"},{"id":"shafiya:604","bookId":"shafiya","type":"section","seq":604,"chapter":"تعريف التصريف","title":"551-","page":"ص0","text":"(ألندد أفنعل من لدد ... معد كالفعل للتمعدد)","bab":"باب ذي الزيادة"},{"id":"shafiya:605","bookId":"shafiya","type":"section","seq":605,"chapter":"تعريف التصريف","title":"552-","page":"ص0","text":"(ولم يبالوا بتمدرع ولا ... تمندل إذ الشذوذ قد جلا)","bab":"باب ذي الزيادة"},{"id":"shafiya:606","bookId":"shafiya","type":"section","seq":606,"chapter":"تعريف التصريف","title":"553-","page":"ص0","text":"(مراجل فعالل إذ قد أتى ... ثوب ممرجل بميم ثبتا)","bab":"باب ذي الزيادة"},{"id":"shafiya:607","bookId":"shafiya","type":"section","seq":607,"chapter":"تعريف التصريف","title":"554-","page":"ص0","text":"(وضهيأ فعلأ للضهياء ... فينان فعلان لغصن جائي)","bab":"باب ذي الزيادة"},{"id":"shafiya:608","bookId":"shafiya","type":"section","seq":608,"chapter":"تعريف التصريف","title":"555-","page":"ص0","text":"(جرائض فعالل حين يعد ... فإن جرواضا بمعناه ورد)","bab":"باب ذي الزيادة"},{"id":"shafiya:609","bookId":"shafiya","type":"section","seq":609,"chapter":"تعريف التصريف","title":"556-","page":"ص0","text":"(معزى على فعلى لمعز ينبي ... سنبتة فعلته من سنب)","bab":"باب ذي الزيادة"},{"id":"shafiya:610","bookId":"shafiya","type":"section","seq":610,"chapter":"تعريف التصريف","title":"557-","page":"ص0","text":"(وعيشة بلهاء في بلهنيه ... فوزنها من أجل ذا فعلنيه)","bab":"باب ذي الزيادة"},{"id":"shafiya:611","bookId":"shafiya","type":"section","seq":611,"chapter":"تعريف التصريف","title":"558-","page":"ص0","text":"(عرضنة فعلنة من اعترض ... ليست على فعلة إذ تفترض)","bab":"باب ذي الزيادة"},{"id":"shafiya:612","bookId":"shafiya","type":"section","seq":612,"chapter":"تعريف التصريف","title":"559-","page":"ص0","text":"(وأول أفعل من أجل الأول ... وحقه من وول لا من وأل)","bab":"باب ذي الزيادة"},{"id":"shafiya:613","bookId":"shafiya","type":"section","seq":613,"chapter":"تعريف التصريف","title":"560-","page":"ص0","text":"(إنقحل إنفعل لشيخ كبرا ... من قحل الشيء ليبس قد طرا)","bab":"باب ذي الزيادة"},{"id":"shafiya:614","bookId":"shafiya","type":"section","seq":614,"chapter":"تعريف التصريف","title":"561-","page":"ص0","text":"(والأفعوان أفعلان موضحا ... والإضحيان إفعلان من ضحى)","bab":"باب ذي الزيادة"},{"id":"shafiya:615","bookId":"shafiya","type":"section","seq":615,"chapter":"تعريف التصريف","title":"562-","page":"ص0","text":"(وخنفقيق فنعليل من خفق ... كما عفرنى بفعلنى قد رفق)\nرجوع الكلمة إلى اشتقاقين واضحين","bab":"باب ذي الزيادة"},{"id":"shafiya:616","bookId":"shafiya","type":"section","seq":616,"chapter":"تعريف التصريف","title":"563-","page":"ص0","text":"(فإن يضح وجهان لاشتقاق ... يصح الامران بالاتفاق)","bab":"باب ذي الزيادة"},{"id":"shafiya:617","bookId":"shafiya","type":"section","seq":617,"chapter":"تعريف التصريف","title":"564-","page":"ص0","text":"(كمثل أرطى إذ يقال راط ... وآرط للآكل المواطي)","bab":"باب ذي الزيادة"},{"id":"shafiya:618","bookId":"shafiya","type":"section","seq":618,"chapter":"تعريف التصريف","title":"565-","page":"ص0","text":"(وأولق حيث أتى مألوق ... في وصفه كما أتى مولوق)","bab":"باب ذي الزيادة"},{"id":"shafiya:619","bookId":"shafiya","type":"section","seq":619,"chapter":"تعريف التصريف","title":"566-","page":"ص0","text":"(والصرف والمنع بحسان لذا ... حمار قبان كذا فليؤخذا)\nفإن اختلفا وضوحا","bab":"باب ذي الزيادة"},{"id":"shafiya:620","bookId":"shafiya","type":"section","seq":620,"chapter":"تعريف التصريف","title":"567-","page":"ص0","text":"(فإن يكونا اختلفا وضوحا ... فرجح الأولى ودع مرجوحا)","bab":"باب ذي الزيادة"},{"id":"shafiya:621","bookId":"shafiya","type":"section","seq":621,"chapter":"تعريف التصريف","title":"568-","page":"ص0","text":"(فملأك كمفعل من الكا ... وعند بعض فعال من ملكا)","bab":"باب ذي الزيادة"},{"id":"shafiya:622","bookId":"shafiya","type":"section","seq":622,"chapter":"تعريف التصريف","title":"569-","page":"ص0","text":"(موسى من الإيساء فهو مفعل ... وقيل من ماس ففعلى يجعل)","bab":"باب ذي الزيادة"},{"id":"shafiya:623","bookId":"shafiya","type":"section","seq":623,"chapter":"تعريف التصريف","title":"570-","page":"ص0","text":"(من أنس الإنسان كالفعلان ... وقيل إفعان من النسيان)","bab":"باب ذي الزيادة"},{"id":"shafiya:624","bookId":"shafiya","type":"section","seq":624,"chapter":"تعريف التصريف","title":"571-","page":"ص0","text":"(لأنه جاء أنيسيان ... وكان من شيمته النسيان)","bab":"باب ذي الزيادة"},{"id":"shafiya:625","bookId":"shafiya","type":"section","seq":625,"chapter":"تعريف التصريف","title":"572-","page":"ص0","text":"(والتربوت فعلوت من ترب ... لسيبويه فالذلول كالترب)","bab":"باب ذي الزيادة"},{"id":"shafiya:626","bookId":"shafiya","type":"section","seq":626,"chapter":"تعريف التصريف","title":"573-","page":"ص0","text":"(ويجعل السبروت كالفعلول ... وقيل من سبر بلا محصول)","bab":"باب ذي الزيادة"},{"id":"shafiya:627","bookId":"shafiya","type":"section","seq":627,"chapter":"تعريف التصريف","title":"574-","page":"ص0","text":"(وقال في تنبالة فعلاله ... وقيل من نبل فكالتفعاله)","bab":"باب ذي الزيادة"},{"id":"shafiya:628","bookId":"shafiya","type":"section","seq":628,"chapter":"تعريف التصريف","title":"575-","page":"ص0","text":"(سرية فعلية سرارا ... وقيل فعيلة اختيار)","bab":"باب ذي الزيادة"},{"id":"shafiya:629","bookId":"shafiya","type":"section","seq":629,"chapter":"تعريف التصريف","title":"576-","page":"ص0","text":"(مؤونة من مان كالفعوله ... وقيل من أون فذي ثقيله)","bab":"باب ذي الزيادة"},{"id":"shafiya:630","bookId":"shafiya","type":"section","seq":630,"chapter":"تعريف التصريف","title":"577-","page":"ص0","text":"(وقال في وزانها الفراء ... تشتق من اين هو الإعياء)","bab":"باب ذي الزيادة"},{"id":"shafiya:631","bookId":"shafiya","type":"section","seq":631,"chapter":"تعريف التصريف","title":"578-","page":"ص0","text":"(في منجنيق جنقوا منقول ... فإن به اعتد فمنفعيل)","bab":"باب ذي الزيادة"},{"id":"shafiya:632","bookId":"shafiya","type":"section","seq":632,"chapter":"تعريف التصريف","title":"579-","page":"ص0","text":"(وبالمجانيق إن اعتددنا ... في جمعه ففنعليل وزنا)","bab":"باب ذي الزيادة"},{"id":"shafiya:633","bookId":"shafiya","type":"section","seq":633,"chapter":"تعريف التصريف","title":"580-","page":"ص0","text":"(ومن يرى كثرة سلسبيل ... يجعله وزان فعلليل)","bab":"باب ذي الزيادة"},{"id":"shafiya:634","bookId":"shafiya","type":"section","seq":634,"chapter":"تعريف التصريف","title":"581-","page":"ص0","text":"(وإن طرحت كل ما قد قيلا ... جعلته في الوزن فعلنيلا)","bab":"باب ذي الزيادة"},{"id":"shafiya:635","bookId":"shafiya","type":"section","seq":635,"chapter":"تعريف التصريف","title":"582-","page":"ص0","text":"(وفي المجانيق الثلاث تحتمل ... ومنجنون مثله في المحتمل)","bab":"باب ذي الزيادة"},{"id":"shafiya:636","bookId":"shafiya","type":"section","seq":636,"chapter":"تعريف التصريف","title":"583-","page":"ص0","text":"(إذ جاء في معناه منجنين ... ومنفعيل فيه لا يبين)","bab":"باب ذي الزيادة"},{"id":"shafiya:637","bookId":"shafiya","type":"section","seq":637,"chapter":"تعريف التصريف","title":"584-","page":"ص0","text":"(لو لم يجىء ذلك في المضبوط ... لكان في الوزن كعضرفوط)","bab":"باب ذي الزيادة"},{"id":"shafiya:638","bookId":"shafiya","type":"section","seq":638,"chapter":"تعريف التصريف","title":"585-","page":"ص0","text":"(وخندريس مثل منجنين ... في الاحتمالين لدى التبيين)\nما فقد فيه الاشتقاق","bab":"باب ذي الزيادة"},{"id":"shafiya:639","bookId":"shafiya","type":"section","seq":639,"chapter":"تعريف التصريف","title":"586-","page":"ص0","text":"(إن فقد اشتقاقها يستعلم ... من الخروج عن أصول الكلم)","bab":"باب ذي الزيادة"},{"id":"shafiya:640","bookId":"shafiya","type":"section","seq":640,"chapter":"تعريف التصريف","title":"587-","page":"ص0","text":"(كتاء ترتب وتاء تتفل ... ونون كنتأل مع الكنهبل)","bab":"باب ذي الزيادة"},{"id":"shafiya:641","bookId":"shafiya","type":"section","seq":641,"chapter":"تعريف التصريف","title":"588-","page":"ص0","text":"(ونون قنفخر وخنفساء ... دون كنهور من الأسماء)","bab":"باب ذي الزيادة"},{"id":"shafiya:642","bookId":"shafiya","type":"section","seq":642,"chapter":"تعريف التصريف","title":"589-","page":"ص0","text":"(وربما يعرف من أن يخرجا ... موازن آخر فيها خرجا)","bab":"باب ذي الزيادة"},{"id":"shafiya:643","bookId":"shafiya","type":"section","seq":643,"chapter":"تعريف التصريف","title":"590-","page":"ص0","text":"(كمثل تاء تتفل وترتب ... مضمومة مع تتفل وترتب)","bab":"باب ذي الزيادة"},{"id":"shafiya:644","bookId":"shafiya","type":"section","seq":644,"chapter":"تعريف التصريف","title":"591-","page":"ص0","text":"(ونون خنفساء أو قنفخر ... مع وضع خنفساء والقنفخر)","bab":"باب ذي الزيادة"},{"id":"shafiya:645","bookId":"shafiya","type":"section","seq":645,"chapter":"تعريف التصريف","title":"592-","page":"ص0","text":"(ومثله الهمزة في ألنجج ... مع الألنجوج لعود أرج)","bab":"باب ذي الزيادة"},{"id":"shafiya:646","bookId":"shafiya","type":"section","seq":646,"chapter":"تعريف التصريف","title":"593-","page":"ص0","text":"(فإن كلا الوزنين عنها خرجا ... فزائد أيضا متى تخرجا)","bab":"باب ذي الزيادة"},{"id":"shafiya:647","bookId":"shafiya","type":"section","seq":647,"chapter":"تعريف التصريف","title":"594-","page":"ص0","text":"(كنون نرجس وحنطأو يلي ... وجندب إن جخدب لم يقبل)","bab":"باب ذي الزيادة"},{"id":"shafiya:648","bookId":"shafiya","type":"section","seq":648,"chapter":"تعريف التصريف","title":"595-","page":"ص0","text":"(إلا إذا ما شذت الزياده ... كنون برناساء باستفاده)","bab":"باب ذي الزيادة"},{"id":"shafiya:649","bookId":"shafiya","type":"section","seq":649,"chapter":"تعريف التصريف","title":"596-","page":"ص0","text":"(والميم من لفظة مرزنجوش ... لا نونها بالضابط المنقوش)","bab":"باب ذي الزيادة"},{"id":"shafiya:650","bookId":"shafiya","type":"section","seq":650,"chapter":"تعريف التصريف","title":"597-","page":"ص0","text":"(أما كنأبيل لدى القياس ... فكالخزعبيل بلا التباس)\nمعرفة الزائد بغلبة الزيادة","bab":"باب ذي الزيادة"},{"id":"shafiya:651","bookId":"shafiya","type":"section","seq":651,"chapter":"تعريف التصريف","title":"598-","page":"ص0","text":"(إن هي لم تخرج في الاستفاده ... يحكم به من غلب الزياده)","bab":"باب ذي الزيادة"},{"id":"shafiya:652","bookId":"shafiya","type":"section","seq":652,"chapter":"تعريف التصريف","title":"599-","page":"ص0","text":"(كمثل تضعيف له في موضع ... أو موضعين مع ثلاث موقع)","bab":"باب ذي الزيادة"},{"id":"shafiya:653","bookId":"shafiya","type":"section","seq":653,"chapter":"تعريف التصريف","title":"600-","page":"ص0","text":"(لملحق أو غيره كقردد ... عصبصب ومرمريس مورد)","bab":"باب ذي الزيادة"},{"id":"shafiya:654","bookId":"shafiya","type":"section","seq":654,"chapter":"تعريف التصريف","title":"601-","page":"ص0","text":"(وهكذا همرش والأخفش ... يقول إن أصله هنمرش)","bab":"باب ذي الزيادة"},{"id":"shafiya:655","bookId":"shafiya","type":"section","seq":655,"chapter":"تعريف التصريف","title":"602-","page":"ص0","text":"(إذ لم يجىء فعلل من الكلم ... من أجل ذا لم يظهروا حيث علم)","bab":"باب ذي الزيادة"},{"id":"shafiya:656","bookId":"shafiya","type":"section","seq":656,"chapter":"تعريف التصريف","title":"603-","page":"ص0","text":"(والزائد الثاني لنحو خولا ... ويجعل الخليل ذاك الأولا)","bab":"باب ذي الزيادة"},{"id":"shafiya:657","bookId":"shafiya","type":"section","seq":657,"chapter":"تعريف التصريف","title":"604-","page":"ص0","text":"(وسيبويه جوز الأمرين ... حيث رأى تعارض الوجهين)","bab":"باب ذي الزيادة"},{"id":"shafiya:658","bookId":"shafiya","type":"section","seq":658,"chapter":"تعريف التصريف","title":"605-","page":"ص0","text":"(ولم يجىء في اللفظ باطراد ... تكرر الفاء بالانفراد)","bab":"باب ذي الزيادة"},{"id":"shafiya:659","bookId":"shafiya","type":"section","seq":659,"chapter":"تعريف التصريف","title":"606-","page":"ص0","text":"(ونحو زلزلت رباعي كما ... ضوضيت والياء إلى الواو انتمى)","bab":"باب ذي الزيادة"},{"id":"shafiya:660","bookId":"shafiya","type":"section","seq":660,"chapter":"تعريف التصريف","title":"607-","page":"ص0","text":"(وليس تكريرا ولا زياده ... للفصل والحكم بلا شهاده)","bab":"باب ذي الزيادة"},{"id":"shafiya:661","bookId":"shafiya","type":"section","seq":661,"chapter":"تعريف التصريف","title":"608-","page":"ص0","text":"(وهكذا سبيل سلسبيل ... فهو خماسي كفعلليل)","bab":"باب ذي الزيادة"},{"id":"shafiya:662","bookId":"shafiya","type":"section","seq":662,"chapter":"تعريف التصريف","title":"609-","page":"ص0","text":"(وقال أهل الكوفه الأعلام ... زلزل من زل به الأقدام)","bab":"باب ذي الزيادة"},{"id":"shafiya:663","bookId":"shafiya","type":"section","seq":663,"chapter":"تعريف التصريف","title":"610-","page":"ص0","text":"(وهكذا صرصر من صركما ... دمدم من دم لمعنى لزما)\nزيادة الهمزة","bab":"باب ذي الزيادة"},{"id":"shafiya:664","bookId":"shafiya","type":"section","seq":664,"chapter":"تعريف التصريف","title":"611-","page":"ص0","text":"(ومثل همز جاء في الأول مع ... ثلاثة فحسب في الأصل تقع)","bab":"باب ذي الزيادة"},{"id":"shafiya:665","bookId":"shafiya","type":"section","seq":665,"chapter":"تعريف التصريف","title":"612-","page":"ص0","text":"(فأفكل أفعل والإصطبل ... وزان قرطعب مضى فعلل)\nالميم","bab":"باب ذي الزيادة"},{"id":"shafiya:666","bookId":"shafiya","type":"section","seq":666,"chapter":"تعريف التصريف","title":"613-","page":"ص0","text":"(والميم كالهمز مزيدا واطرد ... فيما على الفعل جرى كالمسترد)\nالياء","bab":"باب ذي الزيادة"},{"id":"shafiya:667","bookId":"shafiya","type":"section","seq":667,"chapter":"تعريف التصريف","title":"614-","page":"ص0","text":"(والياء مع ثلاثة فما علا ... إلا الرباعي بحرف أولا)","bab":"باب ذي الزيادة"},{"id":"shafiya:668","bookId":"shafiya","type":"section","seq":668,"chapter":"تعريف التصريف","title":"615-","page":"ص0","text":"(سوى رباعي على الفعل جرى ... مثل يقوقي علما مقررا)","bab":"باب ذي الزيادة"},{"id":"shafiya:669","bookId":"shafiya","type":"section","seq":669,"chapter":"تعريف التصريف","title":"616-","page":"ص0","text":"(فيستعور عضرفوط تقفيه ... وزيدت الياء من السلحفيه)\nالألف والواو","bab":"باب ذي الزيادة"},{"id":"shafiya:670","bookId":"shafiya","type":"section","seq":670,"chapter":"تعريف التصريف","title":"617-","page":"ص0","text":"(والألف مع ثلاثة فما علا ... كالواو إلا عند حرف أولا)","bab":"باب ذي الزيادة"},{"id":"shafiya:671","bookId":"shafiya","type":"section","seq":671,"chapter":"تعريف التصريف","title":"618-","page":"ص0","text":"(من ثم كان الوزن في ورنتل ... مثل جحنفل على فعنلل)\nالنون","bab":"باب ذي الزيادة"},{"id":"shafiya:672","bookId":"shafiya","type":"section","seq":672,"chapter":"تعريف التصريف","title":"619-","page":"ص0","text":"(والنون في الآخر بعد الألف ... وثالثا مسكنا في الأعرف)","bab":"باب ذي الزيادة"},{"id":"shafiya:673","bookId":"shafiya","type":"section","seq":673,"chapter":"تعريف التصريف","title":"620-","page":"ص0","text":"(مثل شرنبث وفي المضارع ... يطرد المزيد كالمطاوع)\nالسين","bab":"باب ذي الزيادة"},{"id":"shafiya:674","bookId":"shafiya","type":"section","seq":674,"chapter":"تعريف التصريف","title":"621-","page":"ص0","text":"(والسين في استفعل باطراد ... وشذ في اسطاع بالانفراد)","bab":"باب ذي الزيادة"},{"id":"shafiya:675","bookId":"shafiya","type":"section","seq":675,"chapter":"تعريف التصريف","title":"622-","page":"ص0","text":"(وهو أطاع عند سيبويه ... فالضم في يسطيعه لديه)","bab":"باب ذي الزيادة"},{"id":"shafiya:676","bookId":"shafiya","type":"section","seq":676,"chapter":"تعريف التصريف","title":"623-","page":"ص0","text":"(والفتح في يسطيع للفراء ... شذ كفتح الهمز حذف التاء)","bab":"باب ذي الزيادة"},{"id":"shafiya:677","bookId":"shafiya","type":"section","seq":677,"chapter":"تعريف التصريف","title":"624-","page":"ص0","text":"(وعد سين كسكس مستلزم ... لعد شين كشكش لا يحكم)\nاللام","bab":"باب ذي الزيادة"},{"id":"shafiya:678","bookId":"shafiya","type":"section","seq":678,"chapter":"تعريف التصريف","title":"625-","page":"ص0","text":"(قل مزيد اللام مثل زيدل ... وعبدل على وزان فعلل)","bab":"باب ذي الزيادة"},{"id":"shafiya:679","bookId":"shafiya","type":"section","seq":679,"chapter":"تعريف التصريف","title":"626-","page":"ص0","text":"(حتى يقول بعضهم في طيسل ... مع اتفاق الطيس وزن فيعل)","bab":"باب ذي الزيادة"},{"id":"shafiya:680","bookId":"shafiya","type":"section","seq":680,"chapter":"تعريف التصريف","title":"627-","page":"ص0","text":"(وقال في فيشلة وهيقله ... مع فيش أوهيق وزان فيعله)","bab":"باب ذي الزيادة"},{"id":"shafiya:681","bookId":"shafiya","type":"section","seq":681,"chapter":"تعريف التصريف","title":"628-","page":"ص0","text":"(وقال وزن فحجل ذي عوج ... كجعفر مع اطراد أفحج)\nالهاء 629\n(والهاء لا يعدها المبرد ... ونحوه ره لرده لا يرد)","bab":"باب ذي الزيادة"},{"id":"shafiya:682","bookId":"shafiya","type":"section","seq":682,"chapter":"تعريف التصريف","title":"630-","page":"ص0","text":"(فإنها من أحرف المعاني ... كالباء والتنوين لا المباني)","bab":"باب ذي الزيادة"},{"id":"shafiya:683","bookId":"shafiya","type":"section","seq":683,"chapter":"تعريف التصريف","title":"631-","page":"ص0","text":"(وإنما يلزمه أمهتي ... وأمهات جمع أم مثبت)","bab":"باب ذي الزيادة"},{"id":"shafiya:684","bookId":"shafiya","type":"section","seq":684,"chapter":"تعريف التصريف","title":"632-","page":"ص0","text":"(وصيغة الفعل لها معلومه ... إذ جاء في مصدرها الأمومه)","bab":"باب ذي الزيادة"},{"id":"shafiya:685","bookId":"shafiya","type":"section","seq":685,"chapter":"تعريف التصريف","title":"633-","page":"ص0","text":"(وقيل جاز أن تكون أمهه ... فعلة على مثال أبهه)","bab":"باب ذي الزيادة"},{"id":"shafiya:686","bookId":"shafiya","type":"section","seq":686,"chapter":"تعريف التصريف","title":"634-","page":"ص0","text":"(إذ جاء في اتخاذها تأمها ... وجاز أصلية كل فافقها)","bab":"باب ذي الزيادة"},{"id":"shafiya:687","bookId":"shafiya","type":"section","seq":687,"chapter":"تعريف التصريف","title":"635-","page":"ص0","text":"(كمثل ثرة وثرثار معا ... أو دمث ثم دمثر وضعا)","bab":"باب ذي الزيادة"},{"id":"shafiya:688","bookId":"shafiya","type":"section","seq":688,"chapter":"تعريف التصريف","title":"636-","page":"ص0","text":"(وإنما يلزمه أهراقا ... إهراقة وأصله أراقا)","bab":"باب ذي الزيادة"},{"id":"shafiya:689","bookId":"shafiya","type":"section","seq":689,"chapter":"تعريف التصريف","title":"637-","page":"ص0","text":"(والهجرع الطويل عند الأخفش ... من جرع للسهل من مفترس)","bab":"باب ذي الزيادة"},{"id":"shafiya:690","bookId":"shafiya","type":"section","seq":690,"chapter":"تعريف التصريف","title":"638-","page":"ص0","text":"(والهبلع الأكول من بلع أتى ... ونوزع الأخفش فيما أثبتا)","bab":"باب ذي الزيادة"},{"id":"shafiya:691","bookId":"shafiya","type":"section","seq":691,"chapter":"تعريف التصريف","title":"639-","page":"ص0","text":"(ويحكم الخليل في الهركوله ... لضخمة بأنها هفعوله)","bab":"باب ذي الزيادة"},{"id":"shafiya:692","bookId":"shafiya","type":"section","seq":692,"chapter":"تعريف التصريف","title":"640-","page":"ص0","text":"(لأنها في مشيها ركاله ... وخولف الخليل فيما قاله)\nما تعدد الغالب الزيادة فيه","bab":"باب ذي الزيادة"},{"id":"shafiya:693","bookId":"shafiya","type":"section","seq":693,"chapter":"تعريف التصريف","title":"641-","page":"ص0","text":"(إن يتعدد غالب وهو على ... ثلاثة من الأصول اشتملا)","bab":"باب ذي الزيادة"},{"id":"shafiya:694","bookId":"shafiya","type":"section","seq":694,"chapter":"تعريف التصريف","title":"642-","page":"ص0","text":"(فالحكم فيه بزيادة عرف ... نحو حبنطى فيه نون وألف)","bab":"باب ذي الزيادة"},{"id":"shafiya:695","bookId":"shafiya","type":"section","seq":695,"chapter":"تعريف التصريف","title":"643-","page":"ص0","text":"(فإن يعين واحد يرجح ... ما زاد بالخروج إن لم يطرح)","bab":"باب ذي الزيادة"},{"id":"shafiya:696","bookId":"shafiya","type":"section","seq":696,"chapter":"تعريف التصريف","title":"644-","page":"ص0","text":"(كميم مريم وميم مدين ... وهمزة الأيدع بالتبين)","bab":"باب ذي الزيادة"},{"id":"shafiya:697","bookId":"shafiya","type":"section","seq":697,"chapter":"تعريف التصريف","title":"645-","page":"ص0","text":"(وهكذا الياء بتيحان ... فهو على وزان فيعلان)","bab":"باب ذي الزيادة"},{"id":"shafiya:698","bookId":"shafiya","type":"section","seq":698,"chapter":"تعريف التصريف","title":"646-","page":"ص0","text":"(ومثل ذاك التاء في عزويت ... من عدم الفعويل لا الفعليت)","bab":"باب ذي الزيادة"},{"id":"shafiya:699","bookId":"shafiya","type":"section","seq":699,"chapter":"تعريف التصريف","title":"647-","page":"ص0","text":"(طاء قطوطى مثل لام اذ لولى ... إذ ليست افعولى ولا فعولى)","bab":"باب ذي الزيادة"},{"id":"shafiya:700","bookId":"shafiya","type":"section","seq":700,"chapter":"تعريف التصريف","title":"648-","page":"ص0","text":"(والواو دون الياء من حولايا ... فليس من أوزانهم فعلايا)","bab":"باب ذي الزيادة"},{"id":"shafiya:701","bookId":"shafiya","type":"section","seq":701,"chapter":"تعريف التصريف","title":"649-","page":"ص0","text":"(وأول اليهير والتضعيف ... لا الثاني من ياءيه إذ يحيف)","bab":"باب ذي الزيادة"},{"id":"shafiya:702","bookId":"shafiya","type":"section","seq":702,"chapter":"تعريف التصريف","title":"650-","page":"ص0","text":"(وهكذا همزة أرونان ... وإن فقدنا غير أنبجان)","bab":"باب ذي الزيادة"},{"id":"shafiya:703","bookId":"shafiya","type":"section","seq":703,"chapter":"تعريف التصريف","title":"651-","page":"ص0","text":"(إن خرجا كلاهما يرجح ... ما كثر ازدياده فيطرح)","bab":"باب ذي الزيادة"},{"id":"shafiya:704","bookId":"shafiya","type":"section","seq":704,"chapter":"تعريف التصريف","title":"652-","page":"ص0","text":"(كالواو من كوألل قد سمعا ... ونون حنطأو وواها معا)","bab":"باب ذي الزيادة"},{"id":"shafiya:705","bookId":"shafiya","type":"section","seq":705,"chapter":"تعريف التصريف","title":"653-","page":"ص0","text":"(وهكذا تضعيف تيفان ... ففعلان دون تفعلان)","bab":"باب ذي الزيادة"},{"id":"shafiya:706","bookId":"shafiya","type":"section","seq":706,"chapter":"تعريف التصريف","title":"654-","page":"ص0","text":"(فإن هما لم يخرجا يقدم ... بذي شذوذ مظهر لم يدغم)","bab":"باب ذي الزيادة"},{"id":"shafiya:707","bookId":"shafiya","type":"section","seq":707,"chapter":"تعريف التصريف","title":"655-","page":"ص0","text":"(وقيل من شبه اشتقاق مخرج ... ومن هناك اختلفوا في مأجج)","bab":"باب ذي الزيادة"},{"id":"shafiya:708","bookId":"shafiya","type":"section","seq":708,"chapter":"تعريف التصريف","title":"656-","page":"ص0","text":"(ومحبب مؤكد المضعف ... لكنه اشتقاقه غير خفي)","bab":"باب ذي الزيادة"},{"id":"shafiya:709","bookId":"shafiya","type":"section","seq":709,"chapter":"تعريف التصريف","title":"657-","page":"ص0","text":"(إن فيهما شبهة الاشتقاق ... لاحت فبالإظهار باتفاق)","bab":"باب ذي الزيادة"},{"id":"shafiya:710","bookId":"shafiya","type":"section","seq":710,"chapter":"تعريف التصريف","title":"658-","page":"ص0","text":"(كالدال من مهدد في اسم نقلا ... لامرأة فوزنه اجعل فعللا)","bab":"باب ذي الزيادة"},{"id":"shafiya:711","bookId":"shafiya","type":"section","seq":711,"chapter":"تعريف التصريف","title":"659-","page":"ص0","text":"(إن لم يكن في لفظه إظهار ... فشبه الاشتقاق إذ يصار)","bab":"باب ذي الزيادة"},{"id":"shafiya:712","bookId":"shafiya","type":"section","seq":712,"chapter":"تعريف التصريف","title":"660-","page":"ص0","text":"(كميم موظب وميم معلى ... فمفعل في وزن كل أعلى)","bab":"باب ذي الزيادة"},{"id":"shafiya:713","bookId":"shafiya","type":"section","seq":713,"chapter":"تعريف التصريف","title":"661-","page":"ص0","text":"(وأغلب الوزنين هل يرجح ... عليه للرأي هناك مسرح)","bab":"باب ذي الزيادة"},{"id":"shafiya:714","bookId":"shafiya","type":"section","seq":714,"chapter":"تعريف التصريف","title":"662-","page":"ص0","text":"(من ثم رمان على ما قيلا ... فعال إذ شاع له عديلا)","bab":"باب ذي الزيادة"},{"id":"shafiya:715","bookId":"shafiya","type":"section","seq":715,"chapter":"تعريف التصريف","title":"663-","page":"ص0","text":"(إن لاحت الشبهة فيهما معا ... رجح بالأغلب وزنا فاسمعا)","bab":"باب ذي الزيادة"},{"id":"shafiya:716","bookId":"shafiya","type":"section","seq":716,"chapter":"تعريف التصريف","title":"664-","page":"ص0","text":"(وقيل بالأقيس من ثم اختلف ... في مورق من دون حومان عرف)","bab":"باب ذي الزيادة"},{"id":"shafiya:717","bookId":"shafiya","type":"section","seq":717,"chapter":"تعريف التصريف","title":"665-","page":"ص0","text":"(فإن بلفظ ندر الوزنان ... احتملا كمثل أرجوان)","bab":"باب ذي الزيادة"},{"id":"shafiya:718","bookId":"shafiya","type":"section","seq":718,"chapter":"تعريف التصريف","title":"666-","page":"ص0","text":"(إن فقدت شبهة الاشتقاق ... يحكم بالأغلب لارتفاق)","bab":"باب ذي الزيادة"},{"id":"shafiya:719","bookId":"shafiya","type":"section","seq":719,"chapter":"تعريف التصريف","title":"667-","page":"ص0","text":"(كالهمز من أفعى وأوتكان ... والميم من إمعة مهان)","bab":"باب ذي الزيادة"},{"id":"shafiya:720","bookId":"shafiya","type":"section","seq":720,"chapter":"تعريف التصريف","title":"668-","page":"ص0","text":"(إن ندرا جاز كأسطوانه ... إن ثبت افعوالة وزانه)","bab":"باب ذي الزيادة"},{"id":"shafiya:721","bookId":"shafiya","type":"section","seq":721,"chapter":"تعريف التصريف","title":"669-","page":"ص0","text":"(أو لا ففعلوانة فليثبتا ... إذ جمعها على أساطين أتى)","bab":"باب ذي الزيادة"},{"id":"shafiya:722","bookId":"shafiya","type":"section","seq":722,"chapter":"تعريف التصريف","title":"باب الإمالة","page":"ص0","text":"تعريفها","bab":"باب الإمالة"},{"id":"shafiya:723","bookId":"shafiya","type":"section","seq":723,"chapter":"تعريف التصريف","title":"670-","page":"ص0","text":"(إمالة اللفظ بغير عسره ... أن تنحي الفتحة نحو الكسره)\nسببها","bab":"باب الإمالة"},{"id":"shafiya:724","bookId":"shafiya","type":"section","seq":724,"chapter":"تعريف التصريف","title":"671-","page":"ص0","text":"(ووجهها إرادة المناسبه ... لياء أو لكسرة مصاحبه)","bab":"باب الإمالة"},{"id":"shafiya:725","bookId":"shafiya","type":"section","seq":725,"chapter":"تعريف التصريف","title":"672-","page":"ص0","text":"(أو لتلقي ألف قد انقلب ... عن ياء أو واو إلى الكسر انتسب)","bab":"باب الإمالة"},{"id":"shafiya:726","bookId":"shafiya","type":"section","seq":726,"chapter":"تعريف التصريف","title":"673-","page":"ص0","text":"(أو ألف يصير ياء فتحا ... أو لفصول الفقرات كالضحى)","bab":"باب الإمالة"},{"id":"shafiya:727","bookId":"shafiya","type":"section","seq":727,"chapter":"تعريف التصريف","title":"674-","page":"ص0","text":"(وقد يكون الوجه في الإماله ... من ألف سابقه مماله)","bab":"باب الإمالة"},{"id":"shafiya:728","bookId":"shafiya","type":"section","seq":728,"chapter":"تعريف التصريف","title":"675-","page":"ص0","text":"(فالكسر قبل الألف الممال ... في مشبه العماد والشملال)","bab":"باب الإمالة"},{"id":"shafiya:729","bookId":"shafiya","type":"section","seq":729,"chapter":"تعريف التصريف","title":"676-","page":"ص0","text":"(سوغها في نحو درهمان ... خفاء هاء وشذوذ ثان)","bab":"باب الإمالة"},{"id":"shafiya:730","bookId":"shafiya","type":"section","seq":730,"chapter":"تعريف التصريف","title":"677-","page":"ص0","text":"(وبعده في عالم هادي الورى ... ومن كلام قل فالكسر طرا)","bab":"باب الإمالة"},{"id":"shafiya:731","bookId":"shafiya","type":"section","seq":731,"chapter":"تعريف التصريف","title":"678-","page":"ص0","text":"(خلاف من دار لراء جار ... لما به من صفة التكرار)","bab":"باب الإمالة"},{"id":"shafiya:732","bookId":"shafiya","type":"section","seq":732,"chapter":"تعريف التصريف","title":"679-","page":"ص0","text":"(والكسر الاصلي إذا ما قدرا ... ليس كلفظه على ما قررا)","bab":"باب الإمالة"},{"id":"shafiya:733","bookId":"shafiya","type":"section","seq":733,"chapter":"تعريف التصريف","title":"680-","page":"ص0","text":"(مثل اسم فاعل من العفاف ... دون سكون الوقف عند عاف)","bab":"باب الإمالة"},{"id":"shafiya:734","bookId":"shafiya","type":"section","seq":734,"chapter":"تعريف التصريف","title":"681-","page":"ص0","text":"(ولا تمال الألف المقلوبه ... عن واوهم لكسرة مصحوبه)","bab":"باب الإمالة"},{"id":"shafiya:735","bookId":"shafiya","type":"section","seq":735,"chapter":"تعريف التصريف","title":"682-","page":"ص0","text":"(فشذ من ذاك الكبا وشذذا ... من بابه وماله إذ أخذا)","bab":"باب الإمالة"},{"id":"shafiya:736","bookId":"shafiya","type":"section","seq":736,"chapter":"تعريف التصريف","title":"683-","page":"ص0","text":"(وشذ إذ أميل من غير سبب ... باب ومال والمكا حيث انقلب)","bab":"باب الإمالة"},{"id":"shafiya:737","bookId":"shafiya","type":"section","seq":737,"chapter":"تعريف التصريف","title":"684-","page":"ص0","text":"(وهكذا شذ عن القياس ... إمالة الحجاج مثل الناس)","bab":"باب الإمالة"},{"id":"shafiya:738","bookId":"shafiya","type":"section","seq":738,"chapter":"تعريف التصريف","title":"685-","page":"ص0","text":"(أما الربا فإنه أميلا ... من جهة الراء فلا تميلا)","bab":"باب الإمالة"},{"id":"shafiya:739","bookId":"shafiya","type":"section","seq":739,"chapter":"تعريف التصريف","title":"686-","page":"ص0","text":"(والياء قبل الألف الممال ... لا بعد في شيبان أو سيال)","bab":"باب الإمالة"},{"id":"shafiya:740","bookId":"shafiya","type":"section","seq":740,"chapter":"تعريف التصريف","title":"687-","page":"ص0","text":"(والألف المقلوب عن واو كسر ... يختص بالفعل كخاف من حذر)","bab":"باب الإمالة"},{"id":"shafiya:741","bookId":"shafiya","type":"section","seq":741,"chapter":"تعريف التصريف","title":"688-","page":"ص0","text":"(ما أصله الياء كناب وفتى ... سال وفاض إذ رمى ثم أتى)","bab":"باب الإمالة"},{"id":"shafiya:742","bookId":"shafiya","type":"section","seq":742,"chapter":"تعريف التصريف","title":"689-","page":"ص0","text":"(والألف الصائر ياء فتحا ... مثل العلى جمعا وحبلى ورحى)","bab":"باب الإمالة"},{"id":"shafiya:743","bookId":"shafiya","type":"section","seq":743,"chapter":"تعريف التصريف","title":"690-","page":"ص0","text":"(لا جال أو حال عليه الحال ... وو الضحى لفصلها تمال)","bab":"باب الإمالة"},{"id":"shafiya:744","bookId":"shafiya","type":"section","seq":744,"chapter":"تعريف التصريف","title":"691-","page":"ص0","text":"(وفي عمادا جاءت الإماله ... في الثان للسابقة المماله)","bab":"باب الإمالة"},{"id":"shafiya:745","bookId":"shafiya","type":"section","seq":745,"chapter":"تعريف التصريف","title":"692-","page":"ص0","text":"(وقد يمال ألف التنوين ... كخفت زيدا وهو ذو تلوين)\nما يمنع الإمالة","bab":"باب الإمالة"},{"id":"shafiya:746","bookId":"shafiya","type":"section","seq":746,"chapter":"تعريف التصريف","title":"693-","page":"ص0","text":"(يمنع الاستعلاء أن تسوغا ... في غير باب خاف طاب وصغا)","bab":"باب الإمالة"},{"id":"shafiya:747","bookId":"shafiya","type":"section","seq":747,"chapter":"تعريف التصريف","title":"694-","page":"ص0","text":"(مقدما متصلا بحرف أو ... حرفين في لفظ على رأي رأوا)","bab":"باب الإمالة"},{"id":"shafiya:748","bookId":"shafiya","type":"section","seq":748,"chapter":"تعريف التصريف","title":"695-","page":"ص0","text":"(وبعدها متصلا في الأثر ... كذا بحرفين بقول الأكثر)","bab":"باب الإمالة"},{"id":"shafiya:749","bookId":"shafiya","type":"section","seq":749,"chapter":"تعريف التصريف","title":"696-","page":"ص0","text":"(والراء لا ذا كسر ان يتصل ... يمنع كمستعل كرامي الجندل)","bab":"باب الإمالة"},{"id":"shafiya:750","bookId":"shafiya","type":"section","seq":750,"chapter":"تعريف التصريف","title":"697-","page":"ص0","text":"(ويغلب المكسور بعد الألف ... مستعليا وغير مكسور قفي)","bab":"باب الإمالة"},{"id":"shafiya:751","bookId":"shafiya","type":"section","seq":751,"chapter":"تعريف التصريف","title":"698-","page":"ص0","text":"(فطارد وغارم يمال ... ومن قرار هكذا يقال)","bab":"باب الإمالة"},{"id":"shafiya:752","bookId":"shafiya","type":"section","seq":752,"chapter":"تعريف التصريف","title":"699-","page":"ص0","text":"(وإن تناء الراء لم يؤثر ... في المنع والغلب بحكم الأثر)","bab":"باب الإمالة"},{"id":"shafiya:753","bookId":"shafiya","type":"section","seq":753,"chapter":"تعريف التصريف","title":"700-","page":"ص0","text":"(فكافر يمال لا بقادر ... وبعضهم يعكس في التجاور)","bab":"باب الإمالة"},{"id":"shafiya:754","bookId":"shafiya","type":"section","seq":754,"chapter":"تعريف التصريف","title":"701-","page":"ص0","text":"(وقد يمال عند وقف محدث ... ما كان قبل الهاء في المؤنث)","bab":"باب الإمالة"},{"id":"shafiya:755","bookId":"shafiya","type":"section","seq":755,"chapter":"تعريف التصريف","title":"702-","page":"ص0","text":"(توسطت في حقه وتحسن ... في رحمة في كدرة تستهجن)","bab":"باب الإمالة"},{"id":"shafiya:756","bookId":"shafiya","type":"section","seq":756,"chapter":"تعريف التصريف","title":"703-","page":"ص0","text":"(والحرف لا يمال لكن إن جعل ... اسما فحكمه إليه ينتقل)","bab":"باب الإمالة"},{"id":"shafiya:757","bookId":"shafiya","type":"section","seq":757,"chapter":"تعريف التصريف","title":"704-","page":"ص0","text":"(وبعضهم يا وبلى أمالا ... كذاك لا في قولهم إمالا)","bab":"باب الإمالة"},{"id":"shafiya:758","bookId":"shafiya","type":"section","seq":758,"chapter":"تعريف التصريف","title":"705-","page":"ص0","text":"(لأنها نابت مناب الجمله ... فهي على الجملة مستقله)","bab":"باب الإمالة"},{"id":"shafiya:759","bookId":"shafiya","type":"section","seq":759,"chapter":"تعريف التصريف","title":"706-","page":"ص0","text":"(وغير ما مكن كالحرف أتى ... وذا وأنى كبلى مثل متى)","bab":"باب الإمالة"},{"id":"shafiya:760","bookId":"shafiya","type":"section","seq":760,"chapter":"تعريف التصريف","title":"707-","page":"ص0","text":"(وقد أميل في كلامهم عسى ... حيث أتى عسيت عنهم مونسا)","bab":"باب الإمالة"},{"id":"shafiya:761","bookId":"shafiya","type":"section","seq":761,"chapter":"تعريف التصريف","title":"708-","page":"ص0","text":"(وقد يمال الفتح في أولي الضرر ... ونحوه كقوله من الكبر)","bab":"باب الإمالة"},{"id":"shafiya:762","bookId":"shafiya","type":"section","seq":762,"chapter":"تعريف التصريف","title":"709-","page":"ص0","text":"(تخفيف همز كي تقر عينا ... حذف وإبدال وبين بينا)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:763","bookId":"shafiya","type":"section","seq":763,"chapter":"تعريف التصريف","title":"710-","page":"ص0","text":"(أي بينه وبين حرف شكلته ... وقيل أو شكلة ما في قبلته)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:764","bookId":"shafiya","type":"section","seq":764,"chapter":"تعريف التصريف","title":"711-","page":"ص0","text":"(وشرطه أن لا يكون أولا ... والحذف للهمز الأخير في كلا)\nالهمزة الساكنة","bab":"باب تخفيف الهمزة"},{"id":"shafiya:765","bookId":"shafiya","type":"section","seq":765,"chapter":"تعريف التصريف","title":"712-","page":"ص0","text":"(والهمز إما ساكن فيبدل ... بحرف تحريكة ما يتصل)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:766","bookId":"shafiya","type":"section","seq":766,"chapter":"تعريف التصريف","title":"713-","page":"ص0","text":"(كرأس بئر سؤت والذي ائتمن ... ومن يقول ائذن إلى الهدى ائت دن)\nالمتحركة الساكن ما قبلها","bab":"باب تخفيف الهمزة"},{"id":"shafiya:767","bookId":"shafiya","type":"section","seq":767,"chapter":"تعريف التصريف","title":"714-","page":"ص0","text":"(أو غيره فإن تلا ما سكنا ... من واو أو ياء مزيدي البنا)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:768","bookId":"shafiya","type":"section","seq":768,"chapter":"تعريف التصريف","title":"715-","page":"ص0","text":"(لغير إلحاق إليه بدلا ... وأدغم الساكن فيه مرسلا)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:769","bookId":"shafiya","type":"section","seq":769,"chapter":"تعريف التصريف","title":"716-","page":"ص0","text":"(نحو خطية بدت مقروه ... ثم أفيس غدت مكلوه)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:770","bookId":"shafiya","type":"section","seq":770,"chapter":"تعريف التصريف","title":"717-","page":"ص0","text":"(وليس في النبي والبريه ... ملتزما بل كثر القضيه)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:771","bookId":"shafiya","type":"section","seq":771,"chapter":"تعريف التصريف","title":"718-","page":"ص0","text":"(وإن يكن ما قبل همز ألفا ... فبين بين سابقا قد وصفا)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:772","bookId":"shafiya","type":"section","seq":772,"chapter":"تعريف التصريف","title":"719-","page":"ص0","text":"(وإن يكن صحيحا أو ذا عله ... سواه يحذف بعد نقل الشكله)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:773","bookId":"shafiya","type":"section","seq":773,"chapter":"تعريف التصريف","title":"720-","page":"ص0","text":"(نحو شي ثم سو ثم خب ... مسلة مع جيل في حوب)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:774","bookId":"shafiya","type":"section","seq":774,"chapter":"تعريف التصريف","title":"721-","page":"ص0","text":"(اتبعي امرهم ذو امرهم مضى ... قاضوا بيك أبو أيوب قضى)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:775","bookId":"shafiya","type":"section","seq":775,"chapter":"تعريف التصريف","title":"722-","page":"ص0","text":"(وباب شيء وسو قد يدغم ... مشبها بزائد يدغم)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:776","bookId":"shafiya","type":"section","seq":776,"chapter":"تعريف التصريف","title":"723-","page":"ص0","text":"(والتزم التخفيف في باب يرى ... وهكذا أرى يري إذ كثرا)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:777","bookId":"shafiya","type":"section","seq":777,"chapter":"تعريف التصريف","title":"724-","page":"ص0","text":"(ويكثر التخفيف في سل أمرا ... للهمزتين فاعرفن الأمرا)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:778","bookId":"shafiya","type":"section","seq":778,"chapter":"تعريف التصريف","title":"725-","page":"ص0","text":"(والوقف في الهمز الذي تطرفا ... بمقتضاه بعد أن يخففا)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:779","bookId":"shafiya","type":"section","seq":779,"chapter":"تعريف التصريف","title":"726-","page":"ص0","text":"(فالروم والإشمام والسكون ... في قولنا هذا خب يكون)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:780","bookId":"shafiya","type":"section","seq":780,"chapter":"تعريف التصريف","title":"727-","page":"ص0","text":"(كذاك مقرو بري مدغما ... شي وسو نقلا أو أدغما)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:781","bookId":"shafiya","type":"section","seq":781,"chapter":"تعريف التصريف","title":"728-","page":"ص0","text":"(لكن همزا بعد ألف وقفا ... عليه بالسكون يأتي ألفا)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:782","bookId":"shafiya","type":"section","seq":782,"chapter":"تعريف التصريف","title":"729-","page":"ص0","text":"(إذ لم يجز نقل ولا تسهيل\nفجاز فيه القصر والتطويل)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:783","bookId":"shafiya","type":"section","seq":783,"chapter":"تعريف التصريف","title":"730-","page":"ص0","text":"(وإن على ذلك بالروم وقف ... تعين التسهيل كالوصف فقف)\nالمتحركة المتحرك ما قبلها","bab":"باب تخفيف الهمزة"},{"id":"shafiya:784","bookId":"shafiya","type":"section","seq":784,"chapter":"تعريف التصريف","title":"731-","page":"ص0","text":"(وإن تلا محرك محركا ... فالصور التسع ترى فليدركا)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:785","bookId":"shafiya","type":"section","seq":785,"chapter":"تعريف التصريف","title":"732-","page":"ص0","text":"(مفتوح أو مضموم أو مكسور ... وقبلها الثلاث إذ تحور)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:786","bookId":"shafiya","type":"section","seq":786,"chapter":"تعريف التصريف","title":"733-","page":"ص0","text":"(سألتهم عن مائة تؤجل ... إذ سئموا مستهزئين سئلوا)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:787","bookId":"shafiya","type":"section","seq":787,"chapter":"تعريف التصريف","title":"734-","page":"ص0","text":"(وهو رؤوف برؤوس برزوا ... مستهزئون فهي تسع تهمز)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:788","bookId":"shafiya","type":"section","seq":788,"chapter":"تعريف التصريف","title":"735-","page":"ص0","text":"(فمائة تخفيفها بالياء ... مؤجل بالواو بالسواء)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:789","bookId":"shafiya","type":"section","seq":789,"chapter":"تعريف التصريف","title":"736-","page":"ص0","text":"(مستهزئون بين بين الأول ... وقيل بالثاني كذا في سئلوا)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:790","bookId":"shafiya","type":"section","seq":790,"chapter":"تعريف التصريف","title":"737-","page":"ص0","text":"(والباق بين بين بالذي عرف ... وجاء منساة وسال بالألف)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:791","bookId":"shafiya","type":"section","seq":791,"chapter":"تعريف التصريف","title":"738-","page":"ص0","text":"(وخففوا الواجي عند الوصل ... بقلبه وهو خلاف الأصل)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:792","bookId":"shafiya","type":"section","seq":792,"chapter":"تعريف التصريف","title":"739-","page":"ص0","text":"(وقوله بالفهرواجى واقفا ... بأصله وسيبويه خالفا)\nخذ وكل ومر","bab":"باب تخفيف الهمزة"},{"id":"shafiya:793","bookId":"shafiya","type":"section","seq":793,"chapter":"تعريف التصريف","title":"740-","page":"ص0","text":"(والتزموا الحذف بخذ وكل ومر ... وأمر أتى أفصح وصلامن ومر)\nباب الأحمر","bab":"باب تخفيف الهمزة"},{"id":"shafiya:794","bookId":"shafiya","type":"section","seq":794,"chapter":"تعريف التصريف","title":"741-","page":"ص0","text":"(وإن يخفف همز باب الأحمر ... فذكر همز اللام نهج الأكثر)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:795","bookId":"shafiya","type":"section","seq":795,"chapter":"تعريف التصريف","title":"742-","page":"ص0","text":"(فقل الوفى وكذا فلوفى ... مع من لوفى عندما يوفى)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:796","bookId":"shafiya","type":"section","seq":796,"chapter":"تعريف التصريف","title":"743-","page":"ص0","text":"(وقل على الأقل لوفى مسمعا ... كذاك من لوفى وفي لوفى معا)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:797","bookId":"shafiya","type":"section","seq":797,"chapter":"تعريف التصريف","title":"744-","page":"ص0","text":"(وبالأقل جاء عادولا ... إذ لم يحرك نونه معمولا)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:798","bookId":"shafiya","type":"section","seq":798,"chapter":"تعريف التصريف","title":"745-","page":"ص0","text":"(ولم يعيدوا في اسل ولا اقل ... لوحدة الكلمة فاعرف السبل) أحكام الهمزتين في كلمة","bab":"باب تخفيف الهمزة"},{"id":"shafiya:799","bookId":"shafiya","type":"section","seq":799,"chapter":"تعريف التصريف","title":"746-","page":"ص0","text":"(همزان في لفظ وثان سكنا ... يقلب كالإيمان آمن أومنا)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:800","bookId":"shafiya","type":"section","seq":800,"chapter":"تعريف التصريف","title":"747-","page":"ص0","text":"(الحاجبي ليس منه آجره ... لأنه فاعل للمؤاجره)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:801","bookId":"shafiya","type":"section","seq":801,"chapter":"تعريف التصريف","title":"748-","page":"ص0","text":"(وإن يحرك وتلا مسكنا ... يثبت بإدغام كسال المنى)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:802","bookId":"shafiya","type":"section","seq":802,"chapter":"تعريف التصريف","title":"749-","page":"ص0","text":"(إن حركا يقلب ياء ما التحق ... إن ينكسر بالشكل أو ما قد سبق)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:803","bookId":"shafiya","type":"section","seq":803,"chapter":"تعريف التصريف","title":"750-","page":"ص0","text":"(او لا فواوا نحو جاء قادم ... أيمة أو يدم أوادم)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:804","bookId":"shafiya","type":"section","seq":804,"chapter":"تعريف التصريف","title":"751-","page":"ص0","text":"(ومنه في تقديره خطايا ... وخالف الخليل كالبرايا)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:805","bookId":"shafiya","type":"section","seq":805,"chapter":"تعريف التصريف","title":"752-","page":"ص0","text":"(وقد أتى التسهيل والتحقيق في ... أئمة عنهم بلا تخلف)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:806","bookId":"shafiya","type":"section","seq":806,"chapter":"تعريف التصريف","title":"753-","page":"ص0","text":"(وجاء في أكرم حذف الثاني ... ملتزما كسائر المباني)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:807","bookId":"shafiya","type":"section","seq":807,"chapter":"تعريف التصريف","title":"754-","page":"ص0","text":"(وقلبه منفردا ياء فتح ... يلزم في باب مطايا فليصح)\nوهما في كلمتين","bab":"باب تخفيف الهمزة"},{"id":"shafiya:808","bookId":"shafiya","type":"section","seq":808,"chapter":"تعريف التصريف","title":"755-","page":"ص0","text":"(وإن يكن همزان في لفظين ... يحققا أو خففا سيين)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:809","bookId":"shafiya","type":"section","seq":809,"chapter":"تعريف التصريف","title":"756-","page":"ص0","text":"(أو خفف الواحد منهما على ... قياسه فارجع إلى ما نقلا)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:810","bookId":"shafiya","type":"section","seq":810,"chapter":"تعريف التصريف","title":"757-","page":"ص0","text":"(وجاء في يشاء من قبل إلى ... الواو في الثاني كما في رسولا)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:811","bookId":"shafiya","type":"section","seq":811,"chapter":"تعريف التصريف","title":"758-","page":"ص0","text":"(وجاز فيما اتفقا أن ينحذف ... واحد أو يقلب ثان ليخف)","bab":"باب تخفيف الهمزة"},{"id":"shafiya:812","bookId":"shafiya","type":"section","seq":812,"chapter":"تعريف التصريف","title":"باب الإعلال","page":"ص0","text":"تعريفه","bab":"باب الإعلال"},{"id":"shafiya:813","bookId":"shafiya","type":"section","seq":813,"chapter":"تعريف التصريف","title":"759-","page":"ص0","text":"(إعلالهم تغيير حرف العله ... ليحصل التخفيف فادر العله) أقسامه","bab":"باب الإعلال"},{"id":"shafiya:814","bookId":"shafiya","type":"section","seq":814,"chapter":"تعريف التصريف","title":"760-","page":"ص0","text":"(أقسامه ثلاثة تبان ... الحذف والإبدال والإسكان)\nحروفه","bab":"باب الإعلال"},{"id":"shafiya:815","bookId":"shafiya","type":"section","seq":815,"chapter":"تعريف التصريف","title":"761-","page":"ص0","text":"(حروفه واو وياء وألف ... والأولان الأصل فيما قد وصف)\nمواقعها","bab":"باب الإعلال"},{"id":"shafiya:816","bookId":"shafiya","type":"section","seq":816,"chapter":"تعريف التصريف","title":"762-","page":"ص0","text":"(فأين في وعد ويسر وردا ... عينين في قول وبيع وجدا)","bab":"باب الإعلال"},{"id":"shafiya:817","bookId":"shafiya","type":"section","seq":817,"chapter":"تعريف التصريف","title":"763-","page":"ص0","text":"(لامين في الغزو ورمي القوم ... وقدمت كل كويل يوم)","bab":"باب الإعلال"},{"id":"shafiya:818","bookId":"shafiya","type":"section","seq":818,"chapter":"تعريف التصريف","title":"764-","page":"ص0","text":"(وقدم الواو على اليا لاما ... مثل طويت إذ شويت العاما)","bab":"باب الإعلال"},{"id":"shafiya:819","bookId":"shafiya","type":"section","seq":819,"chapter":"تعريف التصريف","title":"765-","page":"ص0","text":"(ولم يجىء بعكسه ليحتمل ... وواو حيوان عن الياء بدل)","bab":"باب الإعلال"},{"id":"shafiya:820","bookId":"shafiya","type":"section","seq":820,"chapter":"تعريف التصريف","title":"766-","page":"ص0","text":"(والياء في يين وفي يدينا ... فاء ولاما جاوفا وعينا)","bab":"باب الإعلال"},{"id":"shafiya:821","bookId":"shafiya","type":"section","seq":821,"chapter":"تعريف التصريف","title":"767-","page":"ص0","text":"(وهكذا فاء وعينا لاما ... قد جاء في يييت لا كلاما)","bab":"باب الإعلال"},{"id":"shafiya:822","bookId":"shafiya","type":"section","seq":822,"chapter":"تعريف التصريف","title":"768-","page":"ص0","text":"(لا الواو إلا أول على الأصح ... والواو في وجهين بالذي اتضح)\nالواو والياء فاءين","bab":"باب الإعلال"},{"id":"shafiya:823","bookId":"shafiya","type":"section","seq":823,"chapter":"تعريف التصريف","title":"769-","page":"ص0","text":"(يقلب واو همزة في الأول ... حتما وفي أواصل أو يصل)","bab":"باب الإعلال"},{"id":"shafiya:824","bookId":"shafiya","type":"section","seq":824,"chapter":"تعريف التصريف","title":"770-","page":"ص0","text":"(إذ حرك الثاني خلاف ووريا ... وجاز في الأجوه مثل أوريا)","bab":"باب الإعلال"},{"id":"shafiya:825","bookId":"shafiya","type":"section","seq":825,"chapter":"تعريف التصريف","title":"771-","page":"ص0","text":"(والمازني في إشاح قد نقل ... والتزم الأولى على نهج الأول)","bab":"باب الإعلال"},{"id":"shafiya:826","bookId":"shafiya","type":"section","seq":826,"chapter":"تعريف التصريف","title":"772-","page":"ص0","text":"(والقلب في أسماء أو أناة ... أو أحد بلا قياس آت)","bab":"باب الإعلال"},{"id":"shafiya:827","bookId":"shafiya","type":"section","seq":827,"chapter":"تعريف التصريف","title":"773-","page":"ص0","text":"(والواو كالياء إلى التاء قلب ... في اتعدوا واتسروا ولم يجب)","bab":"باب الإعلال"},{"id":"shafiya:828","bookId":"shafiya","type":"section","seq":828,"chapter":"تعريف التصريف","title":"774-","page":"ص0","text":"(ولا يقال اتزروا فيقلبا ... ما كان من همز أتى منقلبا)","bab":"باب الإعلال"},{"id":"shafiya:829","bookId":"shafiya","type":"section","seq":829,"chapter":"تعريف التصريف","title":"775-","page":"ص0","text":"(وتبدل الواو إذا ماانكسرا ... ما قبلها ياء كميعاد جرى)","bab":"باب الإعلال"},{"id":"shafiya:830","bookId":"shafiya","type":"section","seq":830,"chapter":"تعريف التصريف","title":"776-","page":"ص0","text":"(وتقلب الياء إلى الواو إذا ... ما قبلها انضم فأبدل موقذا)","bab":"باب الإعلال"},{"id":"shafiya:831","bookId":"shafiya","type":"section","seq":831,"chapter":"تعريف التصريف","title":"777-","page":"ص0","text":"(ويحذفون الواو من نحو يرد ... للياء والكسر بأصل مطرد)","bab":"باب الإعلال"},{"id":"shafiya:832","bookId":"shafiya","type":"section","seq":832,"chapter":"تعريف التصريف","title":"778-","page":"ص0","text":"(من ثم لم يفتح وددت في الكلم ... لأجل إعلالين في يد لزم)","bab":"باب الإعلال"},{"id":"shafiya:833","bookId":"shafiya","type":"section","seq":833,"chapter":"تعريف التصريف","title":"779-","page":"ص0","text":"(وسائر الأحرف كالياء جرى ... وصيغة الأمر كعد مقررا)","bab":"باب الإعلال"},{"id":"shafiya:834","bookId":"shafiya","type":"section","seq":834,"chapter":"تعريف التصريف","title":"780-","page":"ص0","text":"(وفتح عين عارض مستعمل ... في يسع المعلوم لا في يوجل)","bab":"باب الإعلال"},{"id":"shafiya:835","bookId":"shafiya","type":"section","seq":835,"chapter":"تعريف التصريف","title":"781-","page":"ص0","text":"(وشبها بالكسر في التجارب ... وفي التجاري لعروض سارب)","bab":"باب الإعلال"},{"id":"shafiya:836","bookId":"shafiya","type":"section","seq":836,"chapter":"تعريف التصريف","title":"782-","page":"ص0","text":"(والياء لا تحذف نحو ييأس ... وقد أتى ياءس قلت يئس)","bab":"باب الإعلال"},{"id":"shafiya:837","bookId":"shafiya","type":"section","seq":837,"chapter":"تعريف التصريف","title":"783-","page":"ص0","text":"(كما أتى في بابه يا تعد ... واشتق في فاعله موتعد)","bab":"باب الإعلال"},{"id":"shafiya:838","bookId":"shafiya","type":"section","seq":838,"chapter":"تعريف التصريف","title":"784-","page":"ص0","text":"(وشذ قلب واوه في ييجل ... كذاك في ياجل مثل ييجل)","bab":"باب الإعلال"},{"id":"shafiya:839","bookId":"shafiya","type":"section","seq":839,"chapter":"تعريف التصريف","title":"785-","page":"ص0","text":"(وشاع حذف الواو في نحو مقه ... ووجهة قليلة محققه)\nالواو والياء عينين","bab":"باب الإعلال"},{"id":"shafiya:840","bookId":"shafiya","type":"section","seq":840,"chapter":"تعريف التصريف","title":"786-","page":"ص0","text":"(ويقلبان ألفا إن حركا ... والفتح فيما قبل جاء مدركا)","bab":"باب الإعلال"},{"id":"shafiya:841","bookId":"shafiya","type":"section","seq":841,"chapter":"تعريف التصريف","title":"787-","page":"ص0","text":"(في اسم الثلاثي وفعله وما ... عليه محمولا أتى مقوما)","bab":"باب الإعلال"},{"id":"shafiya:842","bookId":"shafiya","type":"section","seq":842,"chapter":"تعريف التصريف","title":"788-","page":"ص0","text":"(كباب ناب تاب إذ أنابا ... وانجاب واغتاب كما استطابا)","bab":"باب الإعلال"},{"id":"shafiya:843","bookId":"shafiya","type":"section","seq":843,"chapter":"تعريف التصريف","title":"789-","page":"ص0","text":"(من ذلك استكان لا كالأكثر ... لبعد مد ولقرب المصدر)","bab":"باب الإعلال"},{"id":"shafiya:844","bookId":"shafiya","type":"section","seq":844,"chapter":"تعريف التصريف","title":"790-","page":"ص0","text":"(كذلك المقام والمقام ... لا قول أو بيع به يقام)","bab":"باب الإعلال"},{"id":"shafiya:845","bookId":"shafiya","type":"section","seq":845,"chapter":"تعريف التصريف","title":"791-","page":"ص0","text":"(وشذ طائي كذاك يا جل ... ولم يعل قاولوا تقاولوا)","bab":"باب الإعلال"},{"id":"shafiya:846","bookId":"shafiya","type":"section","seq":846,"chapter":"تعريف التصريف","title":"792-","page":"ص0","text":"(بايع إذ بين ما تقوما ... تبين الأمر على ما قوما)","bab":"باب الإعلال"},{"id":"shafiya:847","bookId":"shafiya","type":"section","seq":847,"chapter":"تعريف التصريف","title":"793-","page":"ص0","text":"(وشذ نحو أخيلت والقود ... وأغيلت وأغيمت والصيد)","bab":"باب الإعلال"},{"id":"shafiya:848","bookId":"shafiya","type":"section","seq":848,"chapter":"تعريف التصريف","title":"794-","page":"ص0","text":"(صح هوى وهكذا باب قوي ... لرفض إعلالين في الذي روي)","bab":"باب الإعلال"},{"id":"shafiya:849","bookId":"shafiya","type":"section","seq":849,"chapter":"تعريف التصريف","title":"795-","page":"ص0","text":"(وبعد ذاك لم يعلوا طويا ... لأنه فرع هوى كحييا)","bab":"باب الإعلال"},{"id":"shafiya:850","bookId":"shafiya","type":"section","seq":850,"chapter":"تعريف التصريف","title":"796-","page":"ص0","text":"(أو للزوم الضم في يقاي ... كذاك في يطاي أو يحاي)","bab":"باب الإعلال"},{"id":"shafiya:851","bookId":"shafiya","type":"section","seq":851,"chapter":"تعريف التصريف","title":"797-","page":"ص0","text":"(ويكثر الإدغام في باب حيي ... فجاز كسر الفاء لا باب قوي)","bab":"باب الإعلال"},{"id":"shafiya:852","bookId":"shafiya","type":"section","seq":852,"chapter":"تعريف التصريف","title":"798-","page":"ص0","text":"(لأن الاعلال على الإدغام ... مقدم في صيغ الكلام)","bab":"باب الإعلال"},{"id":"shafiya:853","bookId":"shafiya","type":"section","seq":853,"chapter":"تعريف التصريف","title":"799-","page":"ص0","text":"(ومن هنا لم يدغموا في يحيا ... يقوى ويحواوي كمثل يعيا)","bab":"باب الإعلال"},{"id":"shafiya:854","bookId":"shafiya","type":"section","seq":854,"chapter":"تعريف التصريف","title":"00-","page":"ص0","text":"(وجاء الاحويواء واحوياء ... من قال الاشهباب فاحوواء)","bab":"باب الإعلال"},{"id":"shafiya:855","bookId":"shafiya","type":"section","seq":855,"chapter":"تعريف التصريف","title":"01-","page":"ص0","text":"(وعند من يدغم في اقتتال ... فذاك حواء على قتال)","bab":"باب الإعلال"},{"id":"shafiya:856","bookId":"shafiya","type":"section","seq":856,"chapter":"تعريف التصريف","title":"802-","page":"ص0","text":"(وجاز في أحيي دون أحيى ... كذاك في استحيي لا في استحيى)","bab":"باب الإعلال"},{"id":"shafiya:857","bookId":"shafiya","type":"section","seq":857,"chapter":"تعريف التصريف","title":"03-","page":"ص0","text":"(وامتنعوا في نحو يستحيي لما ... يلزم من ضم إلى الرفض انتمى)","bab":"باب الإعلال"},{"id":"shafiya:858","bookId":"shafiya","type":"section","seq":858,"chapter":"تعريف التصريف","title":"04-","page":"ص0","text":"(وما بنوا من باب يقوى فعلا ... بفتح عين أو بضم مثلا)","bab":"باب الإعلال"},{"id":"shafiya:859","bookId":"shafiya","type":"section","seq":859,"chapter":"تعريف التصريف","title":"05-","page":"ص0","text":"(كراهة الواوين في التكلم ... مثل قووت أو قووت فاعلم)","bab":"باب الإعلال"},{"id":"shafiya:860","bookId":"shafiya","type":"section","seq":860,"chapter":"تعريف التصريف","title":"06-","page":"ص0","text":"(والبو والجو كذاك القوه ... محتمل الإدغام مثل الصوه)","bab":"باب الإعلال"},{"id":"shafiya:861","bookId":"shafiya","type":"section","seq":861,"chapter":"تعريف التصريف","title":"07-","page":"ص0","text":"(وباب ما أفعله في الأجوف ... مصحح من عدم التصرف)","bab":"باب الإعلال"},{"id":"shafiya:862","bookId":"shafiya","type":"section","seq":862,"chapter":"تعريف التصريف","title":"08-","page":"ص0","text":"(وأفعل التفضيل محمول على ... ذلك أو للبس فعل حصلا)","bab":"باب الإعلال"},{"id":"shafiya:863","bookId":"shafiya","type":"section","seq":863,"chapter":"تعريف التصريف","title":"09-","page":"ص0","text":"(ولم يعل ازدوجوا واجتوروا ... لأنه تفاعلوا إذ يذكر)","bab":"باب الإعلال"},{"id":"shafiya:864","bookId":"shafiya","type":"section","seq":864,"chapter":"تعريف التصريف","title":"10-","page":"ص0","text":"(ولم يعلوا اسود واعور ولا ... ممدوده لرفع لبس حصلا)","bab":"باب الإعلال"},{"id":"shafiya:865","bookId":"shafiya","type":"section","seq":865,"chapter":"تعريف التصريف","title":"11-","page":"ص0","text":"(وصححوا عورت إذ سودنا ... لأنه كمثله في المعنى)","bab":"باب الإعلال"},{"id":"shafiya:866","bookId":"shafiya","type":"section","seq":866,"chapter":"تعريف التصريف","title":"12-","page":"ص0","text":"(وكل ما يشتق مما صحا ... يلزم في التصريف أن يصحا)","bab":"باب الإعلال"},{"id":"shafiya:867","bookId":"shafiya","type":"section","seq":867,"chapter":"تعريف التصريف","title":"13-","page":"ص0","text":"(كقولك استعورته محاورا ... أعورته مبايعا وعاورا)","bab":"باب الإعلال"},{"id":"shafiya:868","bookId":"shafiya","type":"section","seq":868,"chapter":"تعريف التصريف","title":"14-","page":"ص0","text":"(ومن يقل عار يقل أعارا ... وعائر بالهمز واستعارا)","bab":"باب الإعلال"},{"id":"shafiya:869","bookId":"shafiya","type":"section","seq":869,"chapter":"تعريف التصريف","title":"15-","page":"ص0","text":"(وصح مخياط كما مقوال ... لرفع لبس وكذا تقوال)","bab":"باب الإعلال"},{"id":"shafiya:870","bookId":"shafiya","type":"section","seq":870,"chapter":"تعريف التصريف","title":"16-","page":"ص0","text":"(ومخيط ومقول بعضهما ... أو أديا معناهما فسلما)","bab":"باب الإعلال"},{"id":"shafiya:871","bookId":"shafiya","type":"section","seq":871,"chapter":"تعريف التصريف","title":"17-","page":"ص0","text":"(نحو يقول أو يبيع قد أعل ... بغير ما مر للبس قد نحل)","bab":"باب الإعلال"},{"id":"shafiya:872","bookId":"shafiya","type":"section","seq":872,"chapter":"تعريف التصريف","title":"18-","page":"ص0","text":"(صح جواد وطويل فاقبل ... للبس بالفاعل أو بالفعل)","bab":"باب الإعلال"},{"id":"shafiya:873","bookId":"shafiya","type":"section","seq":873,"chapter":"تعريف التصريف","title":"19-","page":"ص0","text":"(أو أنه لم يأت جاريا على ... فعل فيستعمل كيف استعملا)","bab":"باب الإعلال"},{"id":"shafiya:874","bookId":"shafiya","type":"section","seq":874,"chapter":"تعريف التصريف","title":"820-","page":"ص0","text":"(والحيدى والحيوان قد أتى ... كالصورى والجولان مثبتا)","bab":"باب الإعلال"},{"id":"shafiya:875","bookId":"shafiya","type":"section","seq":875,"chapter":"تعريف التصريف","title":"21-","page":"ص0","text":"(لأنه يخطر من تحركه ... تحرك المعنى ببال مدركه)","bab":"باب الإعلال"},{"id":"shafiya:876","bookId":"shafiya","type":"section","seq":876,"chapter":"تعريف التصريف","title":"22-","page":"ص0","text":"(والموتان لم يعل وافيا ... إذ قد أتى للحيوان نافيا)","bab":"باب الإعلال"},{"id":"shafiya:877","bookId":"shafiya","type":"section","seq":877,"chapter":"تعريف التصريف","title":"23-","page":"ص0","text":"(أو حيث لم يجر على الفعل ولا ... وافقه فصح حيث استعملا)","bab":"باب الإعلال"},{"id":"shafiya:878","bookId":"shafiya","type":"section","seq":878,"chapter":"تعريف التصريف","title":"24-","page":"ص0","text":"(وصح نحو أقوس وأعين ... لرفع الالتباس بالتبين)","bab":"باب الإعلال"},{"id":"shafiya:879","bookId":"shafiya","type":"section","seq":879,"chapter":"تعريف التصريف","title":"25-","page":"ص0","text":"(أو أنه ما جاء جاريا على ... فعل ولا خالفه فانفصلا)","bab":"باب الإعلال"},{"id":"shafiya:880","bookId":"shafiya","type":"section","seq":880,"chapter":"تعريف التصريف","title":"26-","page":"ص0","text":"(وصح نحو جدول وخروع ... وعليب لحفظ الحاق رعي)","bab":"باب الإعلال"},{"id":"shafiya:881","bookId":"shafiya","type":"section","seq":881,"chapter":"تعريف التصريف","title":"27-","page":"ص0","text":"(ويبدلان همزة في فاعل ... أعل عينه كمثل قائل)","bab":"باب الإعلال"},{"id":"shafiya:882","bookId":"shafiya","type":"section","seq":882,"chapter":"تعريف التصريف","title":"28-","page":"ص0","text":"(لا عاور وصايد يحاكي ... وشذ بالكسر وضم شاك)","bab":"باب الإعلال"},{"id":"shafiya:883","bookId":"shafiya","type":"section","seq":883,"chapter":"تعريف التصريف","title":"29-","page":"ص0","text":"(جاء لدى الخليل مقلوب كما ... شاك وغيره القياس حكما)","bab":"باب الإعلال"},{"id":"shafiya:884","bookId":"shafiya","type":"section","seq":884,"chapter":"تعريف التصريف","title":"30-","page":"ص0","text":"(كذاك فيما كان كالدوائر ... من منتهى الجموع كالخيائر)","bab":"باب الإعلال"},{"id":"shafiya:885","bookId":"shafiya","type":"section","seq":885,"chapter":"تعريف التصريف","title":"31-","page":"ص0","text":"(مما يكون فيه قبل الألف ... وبعده واو وياء فاعرف)","bab":"باب الإعلال"},{"id":"shafiya:886","bookId":"shafiya","type":"section","seq":886,"chapter":"تعريف التصريف","title":"32-","page":"ص0","text":"(دون عواوير بياء كائن ... وشذ حفظ الواو في الضياون)","bab":"باب الإعلال"},{"id":"shafiya:887","bookId":"shafiya","type":"section","seq":887,"chapter":"تعريف التصريف","title":"33-","page":"ص0","text":"(وصححوا الواو من العواور ... إذ حذفوا الياء لدى التجاور)","bab":"باب الإعلال"},{"id":"shafiya:888","bookId":"shafiya","type":"section","seq":888,"chapter":"تعريف التصريف","title":"34-","page":"ص0","text":"(عكس العيائيل فلم يصحح ... إذ أشبع الكسر فبالياء دحي)","bab":"باب الإعلال"},{"id":"shafiya:889","bookId":"shafiya","type":"section","seq":889,"chapter":"تعريف التصريف","title":"35-","page":"ص0","text":"(وصححوهما من المقاول ... ونحوه فرقا عن الرسائل)","bab":"باب الإعلال"},{"id":"shafiya:890","bookId":"shafiya","type":"section","seq":890,"chapter":"تعريف التصريف","title":"836-","page":"ص0","text":"(يضعف في المعايش الهمز وفي ... مصائب يلزم سمعا فاقتف)","bab":"باب الإعلال"},{"id":"shafiya:891","bookId":"shafiya","type":"section","seq":891,"chapter":"تعريف التصريف","title":"37-","page":"ص0","text":"(وياء فعلى اسما إلى الواو قلب ... كمثل طوبى ثم كوسى فانتدب)","bab":"باب الإعلال"},{"id":"shafiya:892","bookId":"shafiya","type":"section","seq":892,"chapter":"تعريف التصريف","title":"38-","page":"ص0","text":"(لم ينقلب في صفة لكن كسر ... ما قبله ليسلم اليا فادكر)","bab":"باب الإعلال"},{"id":"shafiya:893","bookId":"shafiya","type":"section","seq":893,"chapter":"تعريف التصريف","title":"39-","page":"ص0","text":"(كمشية حيكى لدى التبختر ... وقسمة ضيزى من التجبر)","bab":"باب الإعلال"},{"id":"shafiya:894","bookId":"shafiya","type":"section","seq":894,"chapter":"تعريف التصريف","title":"40-","page":"ص0","text":"(وهكذا في باب بيض كسر ... واختلفوا في غير ما قد ذكرا)","bab":"باب الإعلال"},{"id":"shafiya:895","bookId":"shafiya","type":"section","seq":895,"chapter":"تعريف التصريف","title":"41-","page":"ص0","text":"(ثانيهما قياس سيبويه ... فشذذت مضوفة لديه)","bab":"باب الإعلال"},{"id":"shafiya:896","bookId":"shafiya","type":"section","seq":896,"chapter":"تعريف التصريف","title":"42-","page":"ص0","text":"(وفي معيشة يجوز مفعله ... بالنقل وحده وجازت مفعله)","bab":"باب الإعلال"},{"id":"shafiya:897","bookId":"shafiya","type":"section","seq":897,"chapter":"تعريف التصريف","title":"43-","page":"ص0","text":"(والأخفش الأول فيه قاسا ... فهو يرى مضوفة قياسا)","bab":"باب الإعلال"},{"id":"shafiya:898","bookId":"shafiya","type":"section","seq":898,"chapter":"تعريف التصريف","title":"44-","page":"ص0","text":"(وعنده مفعلة معيشه ... بالكسر كي لا يلزم المعوشه) 45 - 3 (فترتب من بيعهم تبيع ... لسيبويه غيره تبوع)","bab":"باب الإعلال"},{"id":"shafiya:899","bookId":"shafiya","type":"section","seq":899,"chapter":"تعريف التصريف","title":"46-","page":"ص0","text":"(تقلب في المصدر واو كسرا ... ما قبلها ياء على ما قررا)","bab":"باب الإعلال"},{"id":"shafiya:900","bookId":"shafiya","type":"section","seq":900,"chapter":"تعريف التصريف","title":"47-","page":"ص0","text":"(نحو قياما وعياذا قيما ... إذ حولت أفعالها فانتظما)","bab":"باب الإعلال"},{"id":"shafiya:901","bookId":"shafiya","type":"section","seq":901,"chapter":"تعريف التصريف","title":"48-","page":"ص0","text":"(وشذ حالت حولا كالقود ... دون لواذا حين لم يجرد)","bab":"باب الإعلال"},{"id":"shafiya:902","bookId":"shafiya","type":"section","seq":902,"chapter":"تعريف التصريف","title":"49-","page":"ص0","text":"(تقلب في نحو جياد وتير ... حيث أعل مفرد ولم يقر)","bab":"باب الإعلال"},{"id":"shafiya:903","bookId":"shafiya","type":"section","seq":903,"chapter":"تعريف التصريف","title":"50-","page":"ص0","text":"(كذاك في الرياح والديار ... والديم الدائمة الأمطار)","bab":"باب الإعلال"},{"id":"shafiya:904","bookId":"shafiya","type":"section","seq":904,"chapter":"تعريف التصريف","title":"51-","page":"ص0","text":"(شذ طيال من طويل وكذا ... جياد خيل من جواد شذذا)","bab":"باب الإعلال"},{"id":"shafiya:905","bookId":"shafiya","type":"section","seq":905,"chapter":"تعريف التصريف","title":"52-","page":"ص0","text":"(صح رواء جمع ريان لما ... يلزم من صرفين فليسلما)","bab":"باب الإعلال"},{"id":"shafiya:906","bookId":"shafiya","type":"section","seq":906,"chapter":"تعريف التصريف","title":"53-","page":"ص0","text":"(وصحت النواء جمع ناو ... حيث أتى مفردها بالواو)","bab":"باب الإعلال"},{"id":"shafiya:907","bookId":"shafiya","type":"section","seq":907,"chapter":"تعريف التصريف","title":"54-","page":"ص0","text":"(يبدل في نحو رياض إذ سكن ... في واحد مع ألف بعد علن)","bab":"باب الإعلال"},{"id":"shafiya:908","bookId":"shafiya","type":"section","seq":908,"chapter":"تعريف التصريف","title":"855-","page":"ص0","text":"(لم تنقلب عودة أو كوزه ... إذ ليس فيها ألف مجوزه)","bab":"باب الإعلال"},{"id":"shafiya:909","bookId":"shafiya","type":"section","seq":909,"chapter":"تعريف التصريف","title":"56-","page":"ص0","text":"(وثير شذت لفقدان الألف ... في جمع ثور بقياس قد عرف)","bab":"باب الإعلال"},{"id":"shafiya:910","bookId":"shafiya","type":"section","seq":910,"chapter":"تعريف التصريف","title":"57-","page":"ص0","text":"(ويقلب الواو إذا ما اتفقا ... بالياء إن سكن ما قد سبقا)","bab":"باب الإعلال"},{"id":"shafiya:911","bookId":"shafiya","type":"section","seq":911,"chapter":"تعريف التصريف","title":"58-","page":"ص0","text":"(وبعده يدغم ثم يكسر ... ما قبله إن كان ضم مظهر)","bab":"باب الإعلال"},{"id":"shafiya:912","bookId":"shafiya","type":"section","seq":912,"chapter":"تعريف التصريف","title":"59-","page":"ص0","text":"(مثاله السيد والأيام ... وهكذا القيوم والقيام)","bab":"باب الإعلال"},{"id":"shafiya:913","bookId":"shafiya","type":"section","seq":913,"chapter":"تعريف التصريف","title":"60-","page":"ص0","text":"(ومسلمي عند رفع وكذا ... دلية مرمية فلتؤخذا)","bab":"باب الإعلال"},{"id":"shafiya:914","bookId":"shafiya","type":"section","seq":914,"chapter":"تعريف التصريف","title":"61-","page":"ص0","text":"(وجاء لي جمع ألوى من لوي ... بالضم والكسر على ما قد روي)","bab":"باب الإعلال"},{"id":"shafiya:915","bookId":"shafiya","type":"section","seq":915,"chapter":"تعريف التصريف","title":"62-","page":"ص0","text":"(وشذ من نهي نهو فاركن ... وهكذا حيوة مثل ضيون)","bab":"باب الإعلال"},{"id":"shafiya:916","bookId":"shafiya","type":"section","seq":916,"chapter":"تعريف التصريف","title":"63-","page":"ص0","text":"(وصيم شذ كذا القيم شذ ... وأرق النيام منهما أشد)","bab":"باب الإعلال"},{"id":"shafiya:917","bookId":"shafiya","type":"section","seq":917,"chapter":"تعريف التصريف","title":"64-","page":"ص0","text":"(والنقل في يبيع أو يصون ... وهكذا المبيت والمعون)","bab":"باب الإعلال"},{"id":"shafiya:918","bookId":"shafiya","type":"section","seq":918,"chapter":"تعريف التصريف","title":"65-","page":"ص0","text":"(والحذف بعد النقل في مفعول ... كصيغة المبيع والمقول)","bab":"باب الإعلال"},{"id":"shafiya:919","bookId":"shafiya","type":"section","seq":919,"chapter":"تعريف التصريف","title":"66-","page":"ص0","text":"(وسيبويه واو مفعول حذف ... والأخفش العين وكل قد عرف)","bab":"باب الإعلال"},{"id":"shafiya:920","bookId":"shafiya","type":"section","seq":920,"chapter":"تعريف التصريف","title":"67-","page":"ص0","text":"(وواو مفعول لديه انقلبا ... فخالفا اصليهما إذ ذهبا)","bab":"باب الإعلال"},{"id":"shafiya:921","bookId":"shafiya","type":"section","seq":921,"chapter":"تعريف التصريف","title":"68-","page":"ص0","text":"(شذ مشيب وكذا مهوب ... والأفصح المهيب والمشوب)","bab":"باب الإعلال"},{"id":"shafiya:922","bookId":"shafiya","type":"section","seq":922,"chapter":"تعريف التصريف","title":"69-","page":"ص0","text":"(ويكثر التصحيح في مديون ... ونحوه وقل في مصوون)","bab":"باب الإعلال"},{"id":"shafiya:923","bookId":"shafiya","type":"section","seq":923,"chapter":"تعريف التصريف","title":"70-","page":"ص0","text":"(إعلال يستحيي وتلووا ندرا ... والحذف في قلت وبعت قد جرى)","bab":"باب الإعلال"},{"id":"shafiya:924","bookId":"shafiya","type":"section","seq":924,"chapter":"تعريف التصريف","title":"871-","page":"ص0","text":"(وكسر فاء مع ياء ملتزم ... وعند كسر العين أو لا فيضم)","bab":"باب الإعلال"},{"id":"shafiya:925","bookId":"shafiya","type":"section","seq":925,"chapter":"تعريف التصريف","title":"72-","page":"ص0","text":"(ولست لم تكسر لما فيه علن ... من شبه الحرف فياؤه سكن)","bab":"باب الإعلال"},{"id":"shafiya:926","bookId":"shafiya","type":"section","seq":926,"chapter":"تعريف التصريف","title":"73-","page":"ص0","text":"(يحذف من قل فهو من تقول ... وقل بحذف الياء من تقيل)","bab":"باب الإعلال"},{"id":"shafiya:927","bookId":"shafiya","type":"section","seq":927,"chapter":"تعريف التصريف","title":"74-","page":"ص0","text":"(وتحذف العين من الإقامه ... للساكنين مثل الاستقامه)","bab":"باب الإعلال"},{"id":"shafiya:928","bookId":"shafiya","type":"section","seq":928,"chapter":"تعريف التصريف","title":"75-","page":"ص0","text":"(وحذفها من باب كينونه ... وسيد جاز كما يحكونه)","bab":"باب الإعلال"},{"id":"shafiya:929","bookId":"shafiya","type":"section","seq":929,"chapter":"تعريف التصريف","title":"76-","page":"ص0","text":"(والياء في قيل وبيع قد أتى ... والواو والإشمام أيضا ثبتا)","bab":"باب الإعلال"},{"id":"shafiya:930","bookId":"shafiya","type":"section","seq":930,"chapter":"تعريف التصريف","title":"77-","page":"ص0","text":"(فإن به مسكن لامه اتصل ... فالكسر والإشمام والضم حصل)","bab":"باب الإعلال"},{"id":"shafiya:931","bookId":"shafiya","type":"section","seq":931,"chapter":"تعريف التصريف","title":"78-","page":"ص0","text":"(كبعت يا عبد فأنت متبع ... وقلت يا قول فلست ترجع)","bab":"باب الإعلال"},{"id":"shafiya:932","bookId":"shafiya","type":"section","seq":932,"chapter":"تعريف التصريف","title":"79-","page":"ص0","text":"(واختير وانقيد كذاك فيهما ... دون أقيم واستقيم فافهما)","bab":"باب الإعلال"},{"id":"shafiya:933","bookId":"shafiya","type":"section","seq":933,"chapter":"تعريف التصريف","title":"80-","page":"ص0","text":"(والاسم من غير الثلاثي وما ... يجري على الفعل على ما علما)","bab":"باب الإعلال"},{"id":"shafiya:934","bookId":"shafiya","type":"section","seq":934,"chapter":"تعريف التصريف","title":"81-","page":"ص0","text":"(يشرط في إعلال عين منه أن ... يوافق الفعل بشكل اقترن)","bab":"باب الإعلال"},{"id":"shafiya:935","bookId":"shafiya","type":"section","seq":935,"chapter":"تعريف التصريف","title":"82-","page":"ص0","text":"(مع اختلاف بمزيد أو بنا ... خصا به وضعا على ما زكنا)","bab":"باب الإعلال"},{"id":"shafiya:936","bookId":"shafiya","type":"section","seq":936,"chapter":"تعريف التصريف","title":"83-","page":"ص0","text":"(من ثم لو بنيت مثل مسجد ... وتحلىء من لفظ بيع مرصد)","bab":"باب الإعلال"},{"id":"shafiya:937","bookId":"shafiya","type":"section","seq":937,"chapter":"تعريف التصريف","title":"84-","page":"ص0","text":"(لقلت في وزانه مبيع ... تعله وهكذا تبيع)","bab":"باب الإعلال"},{"id":"shafiya:938","bookId":"shafiya","type":"section","seq":938,"chapter":"تعريف التصريف","title":"85-","page":"ص0","text":"(ولو بنيت منه مثل تفلح ... قلت له تبيع إذ تصحح)\nالواو والياء لامين","bab":"باب الإعلال"},{"id":"shafiya:939","bookId":"shafiya","type":"section","seq":939,"chapter":"تعريف التصريف","title":"886-","page":"ص0","text":"(فيقلبان ألفا إن حركا ... منفتحا ما كان قبل مدركا)","bab":"باب الإعلال"},{"id":"shafiya:940","bookId":"shafiya","type":"section","seq":940,"chapter":"تعريف التصريف","title":"87-","page":"ص0","text":"(إن لم يكن موجب فتح قد تلا ... مثل رمى يحيى ويقوى من علا)","bab":"باب الإعلال"},{"id":"shafiya:941","bookId":"shafiya","type":"section","seq":941,"chapter":"تعريف التصريف","title":"888-","page":"ص0","text":"(لا كغزونا ور مينا وكذا ... يخشين مع غزو ورمي أخذا)","bab":"باب الإعلال"},{"id":"shafiya:942","bookId":"shafiya","type":"section","seq":942,"chapter":"تعريف التصريف","title":"89-","page":"ص0","text":"(ولا كمثل العصوان ملبسا ... أو غزوا أو رميا إذ البسا)","bab":"باب الإعلال"},{"id":"shafiya:943","bookId":"shafiya","type":"section","seq":943,"chapter":"تعريف التصريف","title":"90-","page":"ص0","text":"(ولا اخشيا إذ يحتدي لن تخشيا ... ولا اخشين فهو شبيه لا خشيا)","bab":"باب الإعلال"},{"id":"shafiya:944","bookId":"shafiya","type":"section","seq":944,"chapter":"تعريف التصريف","title":"91-","page":"ص0","text":"(والقلب في اخشوا واخشون واخشين ... واخشي وأمثال بهن تقترن)","bab":"باب الإعلال"},{"id":"shafiya:945","bookId":"shafiya","type":"section","seq":945,"chapter":"تعريف التصريف","title":"92-","page":"ص0","text":"(والواو ياء إن يكن منكسرا ... ما قبلها أو رابعا فأكثرا)","bab":"باب الإعلال"},{"id":"shafiya:946","bookId":"shafiya","type":"section","seq":946,"chapter":"تعريف التصريف","title":"93-","page":"ص0","text":"(ولم يكن ما قبله منضما ... مثل رضيت إذ دعيت عما)","bab":"باب الإعلال"},{"id":"shafiya:947","bookId":"shafiya","type":"section","seq":947,"chapter":"تعريف التصريف","title":"94-","page":"ص0","text":"(كذاك أغزيت ويغزيان ... والغازي القاضي يرضيان)","bab":"باب الإعلال"},{"id":"shafiya:948","bookId":"shafiya","type":"section","seq":948,"chapter":"تعريف التصريف","title":"95-","page":"ص0","text":"(خلاف يدعو صنوه للدنيا ... وقنية شذت كعمي دنيا)","bab":"باب الإعلال"},{"id":"shafiya:949","bookId":"shafiya","type":"section","seq":949,"chapter":"تعريف التصريف","title":"96-","page":"ص0","text":"(وطيىء تقلب ياء ألفا ... في قد فنى الخصم وشره كفى)","bab":"باب الإعلال"},{"id":"shafiya:950","bookId":"shafiya","type":"section","seq":950,"chapter":"تعريف التصريف","title":"97-","page":"ص0","text":"(والواو إن تطرفت تنقلب ... للياء بعد الضم في اسم يعرب)","bab":"باب الإعلال"},{"id":"shafiya:951","bookId":"shafiya","type":"section","seq":951,"chapter":"تعريف التصريف","title":"98-","page":"ص0","text":"(فتقلب الضمة كسرة كما ... في ذات ياء كالترامي محكما)","bab":"باب الإعلال"},{"id":"shafiya:952","bookId":"shafiya","type":"section","seq":952,"chapter":"تعريف التصريف","title":"99-","page":"ص0","text":"(فهو يصير مثل قاض فيعل ... كمثل أدل وقلنس تشتمل)","bab":"باب الإعلال"},{"id":"shafiya:953","bookId":"shafiya","type":"section","seq":953,"chapter":"تعريف التصريف","title":"900-","page":"ص0","text":"(خلاف واو جاء في قلنسوه ... من قبل هاء وكذا قمحدوه)","bab":"باب الإعلال"},{"id":"shafiya:954","bookId":"shafiya","type":"section","seq":954,"chapter":"تعريف التصريف","title":"901-","page":"ص0","text":"(كذاك واو القوباء في العلل ... كنحو ياء الخيلاء لم يعل)","bab":"باب الإعلال"},{"id":"shafiya:955","bookId":"shafiya","type":"section","seq":955,"chapter":"تعريف التصريف","title":"902-","page":"ص0","text":"(والجمع للعاتي عتي وأتى ... مصدره على عتو من عتا)","bab":"باب الإعلال"},{"id":"shafiya:956","bookId":"shafiya","type":"section","seq":956,"chapter":"تعريف التصريف","title":"903-","page":"ص0","text":"(وجاز كسر الفاء حتى يتبعا ... وشذ في النحو نحو فاتبعا)","bab":"باب الإعلال"},{"id":"shafiya:957","bookId":"shafiya","type":"section","seq":957,"chapter":"تعريف التصريف","title":"904-","page":"ص0","text":"(ونحو مغزى كثيرا قد أتى ... والواو في ذاك قياس ثبتا)","bab":"باب الإعلال"},{"id":"shafiya:958","bookId":"shafiya","type":"section","seq":958,"chapter":"تعريف التصريف","title":"905-","page":"ص0","text":"(ويقلبان همزان تطرفا ... في موقع بعد مزيد ألفا)","bab":"باب الإعلال"},{"id":"shafiya:959","bookId":"shafiya","type":"section","seq":959,"chapter":"تعريف التصريف","title":"906-","page":"ص0","text":"(نحو كساء ورداء شملا ... خلاف زاي مثل ثاي أصلا)","bab":"باب الإعلال"},{"id":"shafiya:960","bookId":"shafiya","type":"section","seq":960,"chapter":"تعريف التصريف","title":"907-","page":"ص0","text":"(يعتد بالتاء على القياس في ... شقاوة إذ لزمت في الطرف)","bab":"باب الإعلال"},{"id":"shafiya:961","bookId":"shafiya","type":"section","seq":961,"chapter":"تعريف التصريف","title":"908-","page":"ص0","text":"(وشذت الهمزة في صلاءه ... مثل عظاءة كما عباءه)","bab":"باب الإعلال"},{"id":"shafiya:962","bookId":"shafiya","type":"section","seq":962,"chapter":"تعريف التصريف","title":"909-","page":"ص0","text":"(والياء واوا قلبت في فعلى ... اسما كتقوى ثم بقوى فعلا)","bab":"باب الإعلال"},{"id":"shafiya:963","bookId":"shafiya","type":"section","seq":963,"chapter":"تعريف التصريف","title":"910-","page":"ص0","text":"(لا صفة كنحو صديا ريا ... من الصدى والري إذ تهيا)","bab":"باب الإعلال"},{"id":"shafiya:964","bookId":"shafiya","type":"section","seq":964,"chapter":"تعريف التصريف","title":"911-","page":"ص0","text":"(والواو ياء أبدلت في فعلى ... اسما كما الدنيا بياء تجلى)","bab":"باب الإعلال"},{"id":"shafiya:965","bookId":"shafiya","type":"section","seq":965,"chapter":"تعريف التصريف","title":"912-","page":"ص0","text":"(وشذت القصوى كمثل حزوى ... لا صفة فاضلة كالغزوى)","bab":"باب الإعلال"},{"id":"shafiya:966","bookId":"shafiya","type":"section","seq":966,"chapter":"تعريف التصريف","title":"913-","page":"ص0","text":"(لا فرق في فعلى بواو يروى ... في الاسم والوصف كدعوى شهوى)","bab":"باب الإعلال"},{"id":"shafiya:967","bookId":"shafiya","type":"section","seq":967,"chapter":"تعريف التصريف","title":"914-","page":"ص0","text":"(كذاك في فعله بضم في اليا ... لاسم ووصف مثل فتيا القضيا)","bab":"باب الإعلال"},{"id":"shafiya:968","bookId":"shafiya","type":"section","seq":968,"chapter":"تعريف التصريف","title":"915-","page":"ص0","text":"(والياء بعد همزة بعد ألف ... ولم يكن مفرده كما وصف)","bab":"باب الإعلال"},{"id":"shafiya:969","bookId":"shafiya","type":"section","seq":969,"chapter":"تعريف التصريف","title":"916-","page":"ص0","text":"(يقلب في باب مطايا ألفا ... والهمز ياء كخطايا فاعرفا)","bab":"باب الإعلال"},{"id":"shafiya:970","bookId":"shafiya","type":"section","seq":970,"chapter":"تعريف التصريف","title":"917-","page":"ص0","text":"(وكالصلايا جمع مهموز جعل ... أو جمع منقوص فكل قد أعل)","bab":"باب الإعلال"},{"id":"shafiya:971","bookId":"shafiya","type":"section","seq":971,"chapter":"تعريف التصريف","title":"918-","page":"ص0","text":"(كذا الشوايا عند جمع شاويه ... دون شواء فهو جمع شائيه)","bab":"باب الإعلال"},{"id":"shafiya:972","bookId":"shafiya","type":"section","seq":972,"chapter":"تعريف التصريف","title":"919-","page":"ص0","text":"(ولا شواء وجواء جمعا ... شائية جائية فليسمعا)","bab":"باب الإعلال"},{"id":"shafiya:973","bookId":"shafiya","type":"section","seq":973,"chapter":"تعريف التصريف","title":"920-","page":"ص0","text":"(وروعي المفرد في أداوى ... وفي علاوى وكذا هراوى)","bab":"باب الإعلال"},{"id":"shafiya:974","bookId":"shafiya","type":"section","seq":974,"chapter":"تعريف التصريف","title":"921-","page":"ص0","text":"(وأسكنا في باب يغزو ويقضي ... في الرفع والقاضي برفع خفض)","bab":"باب الإعلال"},{"id":"shafiya:975","bookId":"shafiya","type":"section","seq":975,"chapter":"تعريف التصريف","title":"922-","page":"ص0","text":"(تحريك ياء شذ في رفع وجر ... مثل سكون النصب أينما ظهر)","bab":"باب الإعلال"},{"id":"shafiya:976","bookId":"shafiya","type":"section","seq":976,"chapter":"تعريف التصريف","title":"923-","page":"ص0","text":"(وشذ إثباتهما كالألف ... في الجزم فالقياس حذف الطرف)","bab":"باب الإعلال"},{"id":"shafiya:977","bookId":"shafiya","type":"section","seq":977,"chapter":"تعريف التصريف","title":"924-","page":"ص0","text":"(ولام تغزون وتقضون حذف ... كاغزن واغزن على ما قد عرف)","bab":"باب الإعلال"},{"id":"shafiya:978","bookId":"shafiya","type":"section","seq":978,"chapter":"تعريف التصريف","title":"925-","page":"ص0","text":"(وليس بالقياس نحو اسم ودم ... وابن يد أخ وأخت تحترم)","bab":"باب الإعلال"},{"id":"shafiya:979","bookId":"shafiya","type":"section","seq":979,"chapter":"تعريف التصريف","title":"باب الإبدال","page":"ص0","text":"تعريفه","bab":"باب الإبدال"},{"id":"shafiya:980","bookId":"shafiya","type":"section","seq":980,"chapter":"تعريف التصريف","title":"926-","page":"ص0","text":"(حقيقة الإبدال جعل حرف ... مكان غيره بعرف الصرف)\nما يعرف به الإبدال","bab":"باب الإبدال"},{"id":"shafiya:981","bookId":"shafiya","type":"section","seq":981,"chapter":"تعريف التصريف","title":"927-","page":"ص0","text":"(يعرف بالأمثلة المشتقه ... مثل التراث والأجوه الحقه)","bab":"باب الإبدال"},{"id":"shafiya:982","bookId":"shafiya","type":"section","seq":982,"chapter":"تعريف التصريف","title":"928-","page":"ص0","text":"(وهكذا بقلة استعمال ... كجمع ثعلب على ثعالي)","bab":"باب الإبدال"},{"id":"shafiya:983","bookId":"shafiya","type":"section","seq":983,"chapter":"تعريف التصريف","title":"929-","page":"ص0","text":"(وكونه فرعا وذاك زائد ... مثل رويد وحذاه رائد)","bab":"باب الإبدال"},{"id":"shafiya:984","bookId":"shafiya","type":"section","seq":984,"chapter":"تعريف التصريف","title":"930-","page":"ص0","text":"(أو كونه في الفرع وهو أصل ... نحو مويه وهو قول فصل)","bab":"باب الإبدال"},{"id":"shafiya:985","bookId":"shafiya","type":"section","seq":985,"chapter":"تعريف التصريف","title":"931-","page":"ص0","text":"(أو بلزوم ذي بناء جهلا ... مثل هراق الماء بعدما اصطلى) أحرفه","bab":"باب الإبدال"},{"id":"shafiya:986","bookId":"shafiya","type":"section","seq":986,"chapter":"تعريف التصريف","title":"932-","page":"ص0","text":"(أحرف الابدال بلا اشتباه ... أنصت يوم زل جد طاه)","bab":"باب الإبدال"},{"id":"shafiya:987","bookId":"shafiya","type":"section","seq":987,"chapter":"تعريف التصريف","title":"933-","page":"ص0","text":"(من أدخل السين لأجل اسمعا ... ألزم بالذال وبالظاء معا) إبدال الهمزة","bab":"باب الإبدال"},{"id":"shafiya:988","bookId":"shafiya","type":"section","seq":988,"chapter":"تعريف التصريف","title":"934-","page":"ص0","text":"(فيبدل الهمز من اللينيه ... والعين والهاء على الرويه)","bab":"باب الإبدال"},{"id":"shafiya:989","bookId":"shafiya","type":"section","seq":989,"chapter":"تعريف التصريف","title":"935-","page":"ص0","text":"(فهو من اللين اعتلال لازم ... في نحو بائع طريق دائم)","bab":"باب الإبدال"},{"id":"shafiya:990","bookId":"shafiya","type":"section","seq":990,"chapter":"تعريف التصريف","title":"936-","page":"ص0","text":"(وفي كساء ورداء روعيا ... وجاز في الأجوه مثل أوريا)","bab":"باب الإبدال"},{"id":"shafiya:991","bookId":"shafiya","type":"section","seq":991,"chapter":"تعريف التصريف","title":"937-","page":"ص0","text":"(وشذت الهمزة في دأبه ... ومؤقد وشئمة شأبه)","bab":"باب الإبدال"},{"id":"shafiya:992","bookId":"shafiya","type":"section","seq":992,"chapter":"تعريف التصريف","title":"938-","page":"ص0","text":"(أشذ من ذاك أباب قد طما ... وشذ في الماء ولكن لزما)\nالألف","bab":"باب الإبدال"},{"id":"shafiya:993","bookId":"shafiya","type":"section","seq":993,"chapter":"تعريف التصريف","title":"939-","page":"ص0","text":"(يبدل من أختيه في اللين الألف ... والهمز والنون لدى الوقف فقف)","bab":"باب الإبدال"},{"id":"shafiya:994","bookId":"shafiya","type":"section","seq":994,"chapter":"تعريف التصريف","title":"940-","page":"ص0","text":"(فمنهما يلزم في قال وفي ... باع وفي آل على قول قفي)","bab":"باب الإبدال"},{"id":"shafiya:995","bookId":"shafiya","type":"section","seq":995,"chapter":"تعريف التصريف","title":"941-","page":"ص0","text":"(وشذ طائي ولكن لزما ... يا جل مبدلا بضعف وسما)","bab":"باب الإبدال"},{"id":"shafiya:996","bookId":"shafiya","type":"section","seq":996,"chapter":"تعريف التصريف","title":"942-","page":"ص0","text":"(وهو من الهمزة في راس وفي ... آل من الهاء على رأي يفي)\nالياء","bab":"باب الإبدال"},{"id":"shafiya:997","bookId":"shafiya","type":"section","seq":997,"chapter":"تعريف التصريف","title":"943-","page":"ص0","text":"(ويبدل الياء من أختيه ومن ... همز ومن حرف بتضعيف قرن)","bab":"باب الإبدال"},{"id":"shafiya:998","bookId":"shafiya","type":"section","seq":998,"chapter":"تعريف التصريف","title":"944-","page":"ص0","text":"(والنون والعين كمثل الباء ... والسين والثاء بالاستقراء)","bab":"باب الإبدال"},{"id":"shafiya:999","bookId":"shafiya","type":"section","seq":999,"chapter":"تعريف التصريف","title":"945-","page":"ص0","text":"(فمنهما يلزم في ميعاد ... وفي قيام وحياض عاد)","bab":"باب الإبدال"},{"id":"shafiya:1000","bookId":"shafiya","type":"section","seq":1000,"chapter":"تعريف التصريف","title":"946-","page":"ص0","text":"(وشذ في حبلى ونحو صيم ... وصبية وييجل المقدم)","bab":"باب الإبدال"},{"id":"shafiya:1001","bookId":"shafiya","type":"section","seq":1001,"chapter":"تعريف التصريف","title":"947-","page":"ص0","text":"(من همزة في نحو ذيب وقعا ... ومن بواقيها كثيرا سمعا)","bab":"باب الإبدال"},{"id":"shafiya:1002","bookId":"shafiya","type":"section","seq":1002,"chapter":"تعريف التصريف","title":"948-","page":"ص0","text":"(كنحو أمليت من الإملال ... وكالأناسي على الإبدال)","bab":"باب الإبدال"},{"id":"shafiya:1003","bookId":"shafiya","type":"section","seq":1003,"chapter":"تعريف التصريف","title":"949-","page":"ص0","text":"(ويضعف السادي مع الثعالي ... مثل الضفادي وكذاك الثالي)\nالواو","bab":"باب الإبدال"},{"id":"shafiya:1004","bookId":"shafiya","type":"section","seq":1004,"chapter":"تعريف التصريف","title":"950-","page":"ص0","text":"(والواو من همز وأختيه أتى ... فمنهما يلزم فيما أثبتا)","bab":"باب الإبدال"},{"id":"shafiya:1005","bookId":"shafiya","type":"section","seq":1005,"chapter":"تعريف التصريف","title":"951-","page":"ص0","text":"(مثل جوار وجوير وحوي ... وموقن طوبى وبقوى عصوي)","bab":"باب الإبدال"},{"id":"shafiya:1006","bookId":"shafiya","type":"section","seq":1006,"chapter":"تعريف التصريف","title":"952-","page":"ص0","text":"(يضعف ممضو نهو وكذا ... جباوة وكلها قد شذذا)","bab":"باب الإبدال"},{"id":"shafiya:1007","bookId":"shafiya","type":"section","seq":1007,"chapter":"تعريف التصريف","title":"953-","page":"ص0","text":"(وأبدل الواو بقول قد علن ... من همزة في جونة وفي جون)\nالميم","bab":"باب الإبدال"},{"id":"shafiya:1008","bookId":"shafiya","type":"section","seq":1008,"chapter":"تعريف التصريف","title":"954-","page":"ص0","text":"(والميم من واو ولام يبدل ... والنون والباء كما يمثل)","bab":"باب الإبدال"},{"id":"shafiya:1009","bookId":"shafiya","type":"section","seq":1009,"chapter":"تعريف التصريف","title":"955-","page":"ص0","text":"(فهو من الواو لزوما عند فم ... وضعفت في طيىء في اللام أم)","bab":"باب الإبدال"},{"id":"shafiya:1010","bookId":"shafiya","type":"section","seq":1010,"chapter":"تعريف التصريف","title":"956-","page":"ص0","text":"(ولازم في نون مثل عنبر ... مضعف في طامه لم يختر)","bab":"باب الإبدال"},{"id":"shafiya:1011","bookId":"shafiya","type":"section","seq":1011,"chapter":"تعريف التصريف","title":"957-","page":"ص0","text":"(وهو من الباء أتى في كثم ... وراتم بنات مخر فافهم)\nالنون","bab":"باب الإبدال"},{"id":"shafiya:1012","bookId":"shafiya","type":"section","seq":1012,"chapter":"تعريف التصريف","title":"958-","page":"ص0","text":"(والنون من واو كصنعاني ... في نسبة شذت كبهراني)","bab":"باب الإبدال"},{"id":"shafiya:1013","bookId":"shafiya","type":"section","seq":1013,"chapter":"تعريف التصريف","title":"959-","page":"ص0","text":"(وهو من اللام ضعيف في لعن ... وأصله لعل فاعرف ما علن)\nالتاء","bab":"باب الإبدال"},{"id":"shafiya:1014","bookId":"shafiya","type":"section","seq":1014,"chapter":"تعريف التصريف","title":"960-","page":"ص0","text":"(والتاء من واو وياء في اتعد ... واتسروا على الفصيح قد ورد)","bab":"باب الإبدال"},{"id":"shafiya:1015","bookId":"shafiya","type":"section","seq":1015,"chapter":"تعريف التصريف","title":"961-","page":"ص0","text":"(وشذ في أتلجه وانفردا ... طست بقلب السين تاء مفردا)","bab":"باب الإبدال"},{"id":"shafiya:1016","bookId":"shafiya","type":"section","seq":1016,"chapter":"تعريف التصريف","title":"962-","page":"ص0","text":"(يضعف في لصت من الصاد وفي ... ذعالت من بائه المحرف)\nالهاء","bab":"باب الإبدال"},{"id":"shafiya:1017","bookId":"shafiya","type":"section","seq":1017,"chapter":"تعريف التصريف","title":"963-","page":"ص0","text":"(والهاء من همز على السماع ... نحو هرقت وهرحت الراعي)","bab":"باب الإبدال"},{"id":"shafiya:1018","bookId":"shafiya","type":"section","seq":1018,"chapter":"تعريف التصريف","title":"964-","page":"ص0","text":"(هياك هن فعلت في طي كذا ... لهنه هذا الذي يعني أذا)","bab":"باب الإبدال"},{"id":"shafiya:1019","bookId":"shafiya","type":"section","seq":1019,"chapter":"تعريف التصريف","title":"965-","page":"ص0","text":"(من ألف يشذ هاء في أنه ... حيهله ومه بهاء مسكنه)","bab":"باب الإبدال"},{"id":"shafiya:1020","bookId":"shafiya","type":"section","seq":1020,"chapter":"تعريف التصريف","title":"966-","page":"ص0","text":"(ويا هناه عند بعض من يرى ... والهاء من ياء بهذه ترى)","bab":"باب الإبدال"},{"id":"shafiya:1021","bookId":"shafiya","type":"section","seq":1021,"chapter":"تعريف التصريف","title":"967-","page":"ص0","text":"(ويبدل الهاء من التاء لدى ... وقف بباب رحمة مطردا)\nاللام","bab":"باب الإبدال"},{"id":"shafiya:1022","bookId":"shafiya","type":"section","seq":1022,"chapter":"تعريف التصريف","title":"968-","page":"ص0","text":"(واللام من ضاد رديا في الطجع ... وفي أصيلال من النون وقع)\nالطاء","bab":"باب الإبدال"},{"id":"shafiya:1023","bookId":"shafiya","type":"section","seq":1023,"chapter":"تعريف التصريف","title":"969-","page":"ص0","text":"(والطا من التا لازما في اصطبرا ... وشذ في حصط فلا يعتبرا)\nالدال","bab":"باب الإبدال"},{"id":"shafiya:1024","bookId":"shafiya","type":"section","seq":1024,"chapter":"تعريف التصريف","title":"970-","page":"ص0","text":"(والدال من تاء ازدجرت وادكر ... وشذ في اجدز وفزد في الأثر)","bab":"باب الإبدال"},{"id":"shafiya:1025","bookId":"shafiya","type":"section","seq":1025,"chapter":"تعريف التصريف","title":"971-","page":"ص0","text":"(وشذذت في دولج من تولج ... واجدمعوا من أجل قرب المخرج)\nالجيم","bab":"باب الإبدال"},{"id":"shafiya:1026","bookId":"shafiya","type":"section","seq":1026,"chapter":"تعريف التصريف","title":"972-","page":"ص0","text":"(والجيم من ياء يشد إذ تقف ... نحو فقيمج شذوذه عرف)","bab":"باب الإبدال"},{"id":"shafiya:1027","bookId":"shafiya","type":"section","seq":1027,"chapter":"تعريف التصريف","title":"973-","page":"ص0","text":"(أشذ في نحو أبي علج ... والمطعمان اللحم بالعشج)","bab":"باب الإبدال"},{"id":"shafiya:1028","bookId":"shafiya","type":"section","seq":1028,"chapter":"تعريف التصريف","title":"974-","page":"ص0","text":"(ثم أشذ في قبلت حجتج ... من غير مشدود كما يأتيك بج)","bab":"باب الإبدال"},{"id":"shafiya:1029","bookId":"shafiya","type":"section","seq":1029,"chapter":"تعريف التصريف","title":"975-","page":"ص0","text":"(أشذ في ما أمسجت وأمسجا ... أبدل من ياء به ما لهجا)\nالصاد","bab":"باب الإبدال"},{"id":"shafiya:1030","bookId":"shafiya","type":"section","seq":1030,"chapter":"تعريف التصريف","title":"976-","page":"ص0","text":"(والصاد من سين تلاها خاء ... أو غين أو قاف كذا أو طاء)","bab":"باب الإبدال"},{"id":"shafiya:1031","bookId":"shafiya","type":"section","seq":1031,"chapter":"تعريف التصريف","title":"977-","page":"ص0","text":"(مثل صراط وكذا مس صقر ... واصبغ الماء وصلخ البقر)\nالزاي","bab":"باب الإبدال"},{"id":"shafiya:1032","bookId":"shafiya","type":"section","seq":1032,"chapter":"تعريف التصريف","title":"978-","page":"ص0","text":"(والزاي من سين وصاد وقعا ... أمام دال ساكنين موقعا)","bab":"باب الإبدال"},{"id":"shafiya:1033","bookId":"shafiya","type":"section","seq":1033,"chapter":"تعريف التصريف","title":"979-","page":"ص0","text":"(كيزدل الثوب وفزدي وهو قد ... يشم صوت الزاي لا سين ورد)","bab":"باب الإبدال"},{"id":"shafiya:1034","bookId":"shafiya","type":"section","seq":1034,"chapter":"تعريف التصريف","title":"980-","page":"ص0","text":"(وربما أشمه محركا ... كصدق الصدر صغيرا أدركا)","bab":"باب الإبدال"},{"id":"shafiya:1035","bookId":"shafiya","type":"section","seq":1035,"chapter":"تعريف التصريف","title":"981-","page":"ص0","text":"(والأكثر البيان بالذي استقر ... وقد أتى كلبية مس زقر)","bab":"باب الإبدال"},{"id":"shafiya:1036","bookId":"shafiya","type":"section","seq":1036,"chapter":"تعريف التصريف","title":"982-","page":"ص0","text":"(وقل في أشدقهم والأجدر ... تضارع الشين وجيم فاجهر)","bab":"باب الإبدال"},{"id":"shafiya:1037","bookId":"shafiya","type":"section","seq":1037,"chapter":"تعريف التصريف","title":"باب الإدغام","page":"ص0","text":"تعريفه","bab":"باب الإدغام"},{"id":"shafiya:1038","bookId":"shafiya","type":"section","seq":1038,"chapter":"تعريف التصريف","title":"983-","page":"ص0","text":"(إدغامهم نطقك بالساكن مع ... محرك من مخرج حيث اجتمع)\nما يكون فيه الإدغام","bab":"باب الإدغام"},{"id":"shafiya:1039","bookId":"shafiya","type":"section","seq":1039,"chapter":"تعريف التصريف","title":"984-","page":"ص0","text":"(وذاك قد يكون في مثلين ... اجتمعا أو متقاربين)\nفي المثلين","bab":"باب الإدغام"},{"id":"shafiya:1040","bookId":"shafiya","type":"section","seq":1040,"chapter":"تعريف التصريف","title":"985-","page":"ص0","text":"(فواجب عند سكون الأول ... في كلمة أو كلمتين فاقبل)","bab":"باب الإدغام"},{"id":"shafiya:1041","bookId":"shafiya","type":"section","seq":1041,"chapter":"تعريف التصريف","title":"986-","page":"ص0","text":"(إلا بهمزين عدا سأل ... ونحوه مما عدا فعال)","bab":"باب الإدغام"},{"id":"shafiya:1042","bookId":"shafiya","type":"section","seq":1042,"chapter":"تعريف التصريف","title":"987-","page":"ص0","text":"(ولم يجىء في الألف الإدغام ... لأنه تعذر المرام)","bab":"باب الإدغام"},{"id":"shafiya:1043","bookId":"shafiya","type":"section","seq":1043,"chapter":"تعريف التصريف","title":"988-","page":"ص0","text":"(كذاك في قوول للبس وفي ... تؤوي ورئيا حيثما يخفف)","bab":"باب الإدغام"},{"id":"shafiya:1044","bookId":"shafiya","type":"section","seq":1044,"chapter":"تعريف التصريف","title":"989-","page":"ص0","text":"(وهكذا قالوا وما في يوم ... ليحفظ المد بفتوى القوم)","bab":"باب الإدغام"},{"id":"shafiya:1045","bookId":"shafiya","type":"section","seq":1045,"chapter":"تعريف التصريف","title":"990-","page":"ص0","text":"(وواجب إن حركا في كلمه ... من غير إلحاق ولبس لزمه)","bab":"باب الإدغام"},{"id":"shafiya:1046","bookId":"shafiya","type":"section","seq":1046,"chapter":"تعريف التصريف","title":"991-","page":"ص0","text":"(كرد إلا في لفيف كحيي ... فجائز إدغامه مثل عيي)","bab":"باب الإدغام"},{"id":"shafiya:1047","bookId":"shafiya","type":"section","seq":1047,"chapter":"تعريف التصريف","title":"992-","page":"ص0","text":"(ولم يجب في تتنزلان ... واقتتلوا وتتقاتلان)","bab":"باب الإدغام"},{"id":"shafiya:1048","bookId":"shafiya","type":"section","seq":1048,"chapter":"تعريف التصريف","title":"993-","page":"ج2 ص80","text":"(تحريكه ينقل إن كان سبق ... بساكن ليس بلين كمحق)","bab":"باب الإدغام"},{"id":"shafiya:1049","bookId":"shafiya","type":"section","seq":1049,"chapter":"تعريف التصريف","title":"994-","page":"ج2 ص80","text":"(ثم سكون الوقف مثل الحركه ... لا يمنع الإدغام حين أدركه)","bab":"باب الإدغام"},{"id":"shafiya:1050","bookId":"shafiya","type":"section","seq":1050,"chapter":"تعريف التصريف","title":"995-","page":"ج2 ص80","text":"(مكنني من باب كلمتين ... فلم يجب بل جاز دون شين)","bab":"باب الإدغام"},{"id":"shafiya:1051","bookId":"shafiya","type":"section","seq":1051,"chapter":"تعريف التصريف","title":"996-","page":"ج2 ص80","text":"(وامتنع الإدغام في المثلين في ... همز على الأكثر مثل الألف)","bab":"باب الإدغام"},{"id":"shafiya:1052","bookId":"shafiya","type":"section","seq":1052,"chapter":"تعريف التصريف","title":"997-","page":"ج2 ص80","text":"(وهكذا لدى سكون الثاني ... لغير وقف كمسست الجاني)","bab":"باب الإدغام"},{"id":"shafiya:1053","bookId":"shafiya","type":"section","seq":1053,"chapter":"تعريف التصريف","title":"998-","page":"ج2 ص80","text":"(وفي تميم نحو رد يدغم ... وفي الحجاز فكه ملتزم)","bab":"باب الإدغام"},{"id":"shafiya:1054","bookId":"shafiya","type":"section","seq":1054,"chapter":"تعريف التصريف","title":"999-","page":"ج2 ص80","text":"(وعند إلحاق ولبس بزنه ... كقردد وسرر متضنه)","bab":"باب الإدغام"},{"id":"shafiya:1055","bookId":"shafiya","type":"section","seq":1055,"chapter":"تعريف التصريف","title":"1000-","page":"ج2 ص80","text":"(وهكذا عند صحيح ساكن ... في كلمتين نحو قرم مازن)","bab":"باب الإدغام"},{"id":"shafiya:1056","bookId":"shafiya","type":"section","seq":1056,"chapter":"تعريف التصريف","title":"1001-","page":"ج2 ص80","text":"(وما عن القراء في ذاك نقل ... فهو على الإخفاء للمثل حمل)","bab":"باب الإدغام"},{"id":"shafiya:1057","bookId":"shafiya","type":"section","seq":1057,"chapter":"تعريف التصريف","title":"1002-","page":"ج2 ص80","text":"(وجائز في غير ما قد ذكرا ... كقولك اخشي يا أمية السرى)\nفي المتقاربين","bab":"باب الإدغام"},{"id":"shafiya:1058","bookId":"shafiya","type":"section","seq":1058,"chapter":"تعريف التصريف","title":"1003-","page":"ج2 ص80","text":"(وذان ما تقاربا في المخرج ... هناك أو وصف مقامه يجي)\nمخارج الحروف الأصلية","bab":"باب الإدغام"},{"id":"shafiya:1059","bookId":"shafiya","type":"section","seq":1059,"chapter":"تعريف التصريف","title":"1004-","page":"ج2 ص80","text":"(لكل حرف مخرج حق النظر ... والكل بالتقريب ستة عشر)","bab":"باب الإدغام"},{"id":"shafiya:1060","bookId":"shafiya","type":"section","seq":1060,"chapter":"تعريف التصريف","title":"1005-","page":"ج2 ص80","text":"(للهمز والهاء لدى التعرف ... نهاية الحلق كمثل الألف)","bab":"باب الإدغام"},{"id":"shafiya:1061","bookId":"shafiya","type":"section","seq":1061,"chapter":"تعريف التصريف","title":"1006-","page":"ج2 ص80","text":"(أوسطه للعين ثم الحاء ... مبدؤه للغين ثم الخاء)","bab":"باب الإدغام"},{"id":"shafiya:1062","bookId":"shafiya","type":"section","seq":1062,"chapter":"تعريف التصريف","title":"1007-","page":"ج2 ص80","text":"(للقاف خذ أقصى اللسان والحنك ... للكاف ما يليهما عند الدرك)","bab":"باب الإدغام"},{"id":"shafiya:1063","bookId":"shafiya","type":"section","seq":1063,"chapter":"تعريف التصريف","title":"1008-","page":"ج2 ص80","text":"(للجيم والشين وياء وسطه ... وما علا من حنك إذ تضبطه)","bab":"باب الإدغام"},{"id":"shafiya:1064","bookId":"shafiya","type":"section","seq":1064,"chapter":"تعريف التصريف","title":"1009-","page":"ج2 ص80","text":"(ومخرج الضاد مع الأسنان ... أول إحدى حافتي لسان)","bab":"باب الإدغام"},{"id":"shafiya:1065","bookId":"shafiya","type":"section","seq":1065,"chapter":"تعريف التصريف","title":"1010-","page":"ص0","text":"(وهو من الأيسر منها أيسر ... فهكذا بالضاد يأتي الأكثر)","bab":"باب الإدغام"},{"id":"shafiya:1066","bookId":"shafiya","type":"section","seq":1066,"chapter":"تعريف التصريف","title":"1011-","page":"ص0","text":"(للام خذ ما دون حافة إلى ... آخرها وما علاها موصلا)","bab":"باب الإدغام"},{"id":"shafiya:1067","bookId":"shafiya","type":"section","seq":1067,"chapter":"تعريف التصريف","title":"1012-","page":"ص0","text":"(للراء ما يليهما في المخرج ... للنون ما متصلا به يجي)","bab":"باب الإدغام"},{"id":"shafiya:1068","bookId":"shafiya","type":"section","seq":1068,"chapter":"تعريف التصريف","title":"1013-","page":"ص0","text":"(للدال والطاء وتاء طرفه ... مع الأصول من ثنايا تكنفه)","bab":"باب الإدغام"},{"id":"shafiya:1069","bookId":"shafiya","type":"section","seq":1069,"chapter":"تعريف التصريف","title":"1014-","page":"ص0","text":"(للضاد والزاي مع السين أتى ... ما بين ذاك والثنايا مثبتا)","bab":"باب الإدغام"},{"id":"shafiya:1070","bookId":"shafiya","type":"section","seq":1070,"chapter":"تعريف التصريف","title":"1015-","page":"ص0","text":"(للظاء والذال وثاء طرفه ... وهكذا عليا ثنايا تكنفه)","bab":"باب الإدغام"},{"id":"shafiya:1071","bookId":"shafiya","type":"section","seq":1071,"chapter":"تعريف التصريف","title":"1016-","page":"ص0","text":"(للفاء أطراف الثنايا العليا ... وباطن الشفة إذ تهيا)","bab":"باب الإدغام"},{"id":"shafiya:1072","bookId":"shafiya","type":"section","seq":1072,"chapter":"تعريف التصريف","title":"1017-","page":"ص0","text":"(للباء والميم وواو خرجا ... ما جاء بين الشفتين مخرجا)\nمخرج المتفرع الفصيح","bab":"باب الإدغام"},{"id":"shafiya:1073","bookId":"shafiya","type":"section","seq":1073,"chapter":"تعريف التصريف","title":"1018-","page":"ص0","text":"(وواضح مخرج ما تفرعا ... وثمن الفصيح مما فرعا)","bab":"باب الإدغام"},{"id":"shafiya:1074","bookId":"shafiya","type":"section","seq":1074,"chapter":"تعريف التصريف","title":"1019-","page":"ص0","text":"(ثلاثة همزة بين بينا ... والنون للغنة إذ أتينا)","bab":"باب الإدغام"},{"id":"shafiya:1075","bookId":"shafiya","type":"section","seq":1075,"chapter":"تعريف التصريف","title":"1020-","page":"ص0","text":"(والألف الممال للترخيم ... واللام للتفخيم والتعظيم)","bab":"باب الإدغام"},{"id":"shafiya:1076","bookId":"shafiya","type":"section","seq":1076,"chapter":"تعريف التصريف","title":"1021-","page":"ص0","text":"(والصاد كالزاي لدى العلانيه ... والشين كالجيم فذي ثمانيه)\nوالمستهجن","bab":"باب الإدغام"},{"id":"shafiya:1077","bookId":"shafiya","type":"section","seq":1077,"chapter":"تعريف التصريف","title":"1022-","page":"ص0","text":"(واستهجن الطاء الذي كالتاء ... وهكذا الفاء الذي كالباء)","bab":"باب الإدغام"},{"id":"shafiya:1078","bookId":"shafiya","type":"section","seq":1078,"chapter":"تعريف التصريف","title":"1023-","page":"ص0","text":"(والصاد كالسين وصاد ضعفا ... والكاف كالجيم فكل ضعفا)","bab":"باب الإدغام"},{"id":"shafiya:1079","bookId":"shafiya","type":"section","seq":1079,"chapter":"تعريف التصريف","title":"1024-","page":"ص0","text":"(والجيم مثل الكاف ما تحققا ... كالجيم مثل الشين فليطلقا)\nصفات الحروف","bab":"باب الإدغام"},{"id":"shafiya:1080","bookId":"shafiya","type":"section","seq":1080,"chapter":"تعريف التصريف","title":"1025-","page":"ص0","text":"(مجهورة الحروف حين تلتمس ... ما إن يحرك ينحصر جري النفس)","bab":"باب الإدغام"},{"id":"shafiya:1081","bookId":"shafiya","type":"section","seq":1081,"chapter":"تعريف التصريف","title":"1026-","page":"ص0","text":"(والجهر في غير حروف سلكت ... في قولنا فحثه شخص سكت)","bab":"باب الإدغام"},{"id":"shafiya:1082","bookId":"shafiya","type":"section","seq":1082,"chapter":"تعريف التصريف","title":"1027-","page":"ص0","text":"(خلافها مهموسة ومثلا ... في ققق وككك إذ فصلا)","bab":"باب الإدغام"},{"id":"shafiya:1083","bookId":"shafiya","type":"section","seq":1083,"chapter":"تعريف التصريف","title":"1028-","page":"ص0","text":"(وخالف البعض فقال يهتمس ... ضظغزيعذ والجهر في كت يلتمس)","bab":"باب الإدغام"},{"id":"shafiya:1084","bookId":"shafiya","type":"section","seq":1084,"chapter":"تعريف التصريف","title":"1029-","page":"ص0","text":"(وظن أن الشدة المحسوسه ... بعيدة عن صفة المهموسه)","bab":"باب الإدغام"},{"id":"shafiya:1085","bookId":"shafiya","type":"section","seq":1085,"chapter":"تعريف التصريف","title":"1030-","page":"ص0","text":"(شديدة ما جري صوته انحصر ... في مخرج حالة إسكان ظهر)","bab":"باب الإدغام"},{"id":"shafiya:1086","bookId":"shafiya","type":"section","seq":1086,"chapter":"تعريف التصريف","title":"1031-","page":"ص0","text":"(أجدك قطبت حروف الشده ... ورخوة خلافها معده)","bab":"باب الإدغام"},{"id":"shafiya:1087","bookId":"shafiya","type":"section","seq":1087,"chapter":"تعريف التصريف","title":"1032-","page":"ص0","text":"(بينهما ما فيه إذ يصار ... يعتدل الجري والانحصار)","bab":"باب الإدغام"},{"id":"shafiya:1088","bookId":"shafiya","type":"section","seq":1088,"chapter":"تعريف التصريف","title":"1033-","page":"ص0","text":"(لم يروعنا جمعتها في المثل ... ومثلت بالحج والطش وخل)","bab":"باب الإدغام"},{"id":"shafiya:1089","bookId":"shafiya","type":"section","seq":1089,"chapter":"تعريف التصريف","title":"1034-","page":"ص0","text":"(ينطبق الحنك عند المطبقه ... على المحل وهي صضطظ بالثقه)","bab":"باب الإدغام"},{"id":"shafiya:1090","bookId":"shafiya","type":"section","seq":1090,"chapter":"تعريف التصريف","title":"1035-","page":"ص0","text":"(خلافها في الصفة المنفتحه ... مما عدا الأربعة المفتتحه)","bab":"باب الإدغام"},{"id":"shafiya:1091","bookId":"shafiya","type":"section","seq":1091,"chapter":"تعريف التصريف","title":"1036-","page":"ص0","text":"(في ذات الاستعلاء عند المدرك ... يرتفع اللسان نحو الحنك)","bab":"باب الإدغام"},{"id":"shafiya:1092","bookId":"shafiya","type":"section","seq":1092,"chapter":"تعريف التصريف","title":"1037-","page":"ص0","text":"(حروفه غين وقاف خاء ... والصاد والضاد وظاء طاء)","bab":"باب الإدغام"},{"id":"shafiya:1093","bookId":"shafiya","type":"section","seq":1093,"chapter":"تعريف التصريف","title":"1038-","page":"ص0","text":"(خالفها في الصفة المنخفضه ... فاستفل اللسان مما عرضه)","bab":"باب الإدغام"},{"id":"shafiya:1094","bookId":"shafiya","type":"section","seq":1094,"chapter":"تعريف التصريف","title":"1039-","page":"ص0","text":"(أما حروف بذلاقة تدل ... فستة يجمعها مر بنفل)","bab":"باب الإدغام"},{"id":"shafiya:1095","bookId":"shafiya","type":"section","seq":1095,"chapter":"تعريف التصريف","title":"1040-","page":"ص0","text":"(وهي التي لم يخل بالقياس ... عنها رباعي ولا خماسي)","bab":"باب الإدغام"},{"id":"shafiya:1096","bookId":"shafiya","type":"section","seq":1096,"chapter":"تعريف التصريف","title":"1041-","page":"ص0","text":"(وغيرها مصمتة إذ صمتا ... في صيغ النوعين عنها فاثبتا)","bab":"باب الإدغام"},{"id":"shafiya:1097","bookId":"shafiya","type":"section","seq":1097,"chapter":"تعريف التصريف","title":"1042-","page":"ص0","text":"(ينضم في القلقلة الضغطة في ... وقف إلى الشدة بالتعرف)","bab":"باب الإدغام"},{"id":"shafiya:1098","bookId":"shafiya","type":"section","seq":1098,"chapter":"تعريف التصريف","title":"1043-","page":"ص0","text":"(يجمعها قطب جد عند الثقه ... وقد تسمى بحروف اللقلقه)","bab":"باب الإدغام"},{"id":"shafiya:1099","bookId":"shafiya","type":"section","seq":1099,"chapter":"تعريف التصريف","title":"1044-","page":"ص0","text":"(وأحرف الصفير ما بها صفر ... صاد وزاي ثم سين فاعتبر)","bab":"باب الإدغام"},{"id":"shafiya:1100","bookId":"shafiya","type":"section","seq":1100,"chapter":"تعريف التصريف","title":"1045-","page":"ص0","text":"(حروف لين مدها سواء ... الواو والألف ثم الياء)","bab":"باب الإدغام"},{"id":"shafiya:1101","bookId":"shafiya","type":"section","seq":1101,"chapter":"تعريف التصريف","title":"1046-","page":"ص0","text":"(واللام في اصطلاحهم منحرف ... إذ اللسان عنده ينحرف)","bab":"باب الإدغام"},{"id":"shafiya:1102","bookId":"shafiya","type":"section","seq":1102,"chapter":"تعريف التصريف","title":"1047-","page":"ص0","text":"(والراء قد سمي بالمكرر ... فالنطق في ذلك بالتعسر)","bab":"باب الإدغام"},{"id":"shafiya:1103","bookId":"shafiya","type":"section","seq":1103,"chapter":"تعريف التصريف","title":"1048-","page":"ص0","text":"(والألف الهاوي لأنه اتسع ... به هواء الصوت عندما ارتفع)","bab":"باب الإدغام"},{"id":"shafiya:1104","bookId":"shafiya","type":"section","seq":1104,"chapter":"تعريف التصريف","title":"1049-","page":"ص0","text":"(ويجعل المهتوت وصف التاء ... لما به من هتة الخفاء)\nطريق إدغام المتقاربين","bab":"باب الإدغام"},{"id":"shafiya:1105","bookId":"shafiya","type":"section","seq":1105,"chapter":"تعريف التصريف","title":"1050-","page":"ص0","text":"(في المتقاربين حيث يدغم ... لا بد من قلب به ينتظم)","bab":"باب الإدغام"},{"id":"shafiya:1106","bookId":"shafiya","type":"section","seq":1106,"chapter":"تعريف التصريف","title":"1051-","page":"ص0","text":"(والأول القياس إن لم يعرض ... أمر كما في اذبحتودا إذ رضي)","bab":"باب الإدغام"},{"id":"shafiya:1107","bookId":"shafiya","type":"section","seq":1107,"chapter":"تعريف التصريف","title":"1052-","page":"ص0","text":"(وهكذا في بعض تاء افتعلا ... إذ كثر التغيير فيها كاصطلى)","bab":"باب الإدغام"},{"id":"shafiya:1108","bookId":"shafiya","type":"section","seq":1108,"chapter":"تعريف التصريف","title":"1053-","page":"ص0","text":"(يضعف محم مدغما في معهم ... في السدس ست شذ وهو يلزم)","bab":"باب الإدغام"},{"id":"shafiya:1109","bookId":"shafiya","type":"section","seq":1109,"chapter":"تعريف التصريف","title":"1054-","page":"ص0","text":"(ولم يجز إدغام ما يلتبس ... كمثل زنماء ففك يؤنس)","bab":"باب الإدغام"},{"id":"shafiya:1110","bookId":"shafiya","type":"section","seq":1110,"chapter":"تعريف التصريف","title":"1055-","page":"ص0","text":"(من ثم قالوا طدة لا وطدا ... لثقل أو لبس وألغوا وتدا)","bab":"باب الإدغام"},{"id":"shafiya:1111","bookId":"shafiya","type":"section","seq":1111,"chapter":"تعريف التصريف","title":"1056-","page":"ص0","text":"(ولم يبالوا في امحى واطيرا ... إذ أمن اللبس إذا تغيرا)","bab":"باب الإدغام"},{"id":"shafiya:1112","bookId":"shafiya","type":"section","seq":1112,"chapter":"تعريف التصريف","title":"1057-","page":"ص0","text":"(وجاء ود عن تميم في وتد ... إذ جمعه الأوتاد يكفي للسند)","bab":"باب الإدغام"},{"id":"shafiya:1113","bookId":"shafiya","type":"section","seq":1113,"chapter":"تعريف التصريف","title":"1058-","page":"ص0","text":"(لم يدغموا حروف مشفر ضوي ... فيما يدانيها لضعف يلتوي)","bab":"باب الإدغام"},{"id":"shafiya:1114","bookId":"shafiya","type":"section","seq":1114,"chapter":"تعريف التصريف","title":"1059-","page":"ص0","text":"(وسيد ولية قد أدغما ... حيث أعلا قبل أن يدغما)","bab":"باب الإدغام"},{"id":"shafiya:1115","bookId":"shafiya","type":"section","seq":1115,"chapter":"تعريف التصريف","title":"1060-","page":"ص0","text":"(والنون في لام وراء تدغم ... إذ كرهت نبرتها فيلزم)","bab":"باب الإدغام"},{"id":"shafiya:1116","bookId":"shafiya","type":"section","seq":1116,"chapter":"تعريف التصريف","title":"1061-","page":"ص0","text":"(وأدغمت في الميم حيث اشتركا ... في صفة الغنة حين أدركا)","bab":"باب الإدغام"},{"id":"shafiya:1117","bookId":"shafiya","type":"section","seq":1117,"chapter":"تعريف التصريف","title":"1062-","page":"ص0","text":"(وهكذا في الواو مثل الياء ... إذ أمكن الغنة بالإبقاء)","bab":"باب الإدغام"},{"id":"shafiya:1118","bookId":"shafiya","type":"section","seq":1118,"chapter":"تعريف التصريف","title":"1063-","page":"ص0","text":"(وقد أتى نخسف بهم واغفر لي ... لبعض شأنهم بغير المثل)","bab":"باب الإدغام"},{"id":"shafiya:1119","bookId":"shafiya","type":"section","seq":1119,"chapter":"تعريف التصريف","title":"1064-","page":"ص0","text":"(لا يدغمون أحرف الصفير ... في غيرها حفظا عن التغيير)","bab":"باب الإدغام"},{"id":"shafiya:1120","bookId":"shafiya","type":"section","seq":1120,"chapter":"تعريف التصريف","title":"1065-","page":"ص0","text":"(لم يدغموا المطبق في سواه ... من غير إطباق لما حواه)","bab":"باب الإدغام"},{"id":"shafiya:1121","bookId":"shafiya","type":"section","seq":1121,"chapter":"تعريف التصريف","title":"1066-","page":"ص0","text":"(ولا حروف الحلق فيما كانا ... أدخل منه بالذي استبانا)","bab":"باب الإدغام"},{"id":"shafiya:1122","bookId":"shafiya","type":"section","seq":1122,"chapter":"تعريف التصريف","title":"1067-","page":"ص0","text":"(لكنهم قد يدغمون الحاءا ... في العين والهاء ولا سواءا)","bab":"باب الإدغام"},{"id":"shafiya:1123","bookId":"shafiya","type":"section","seq":1123,"chapter":"تعريف التصريف","title":"1068-","page":"ص0","text":"(من ثم قالوا اذبحتودا مدغما ... كذلك إذ بحاذه لتدغما)","bab":"باب الإدغام"},{"id":"shafiya:1124","bookId":"shafiya","type":"section","seq":1124,"chapter":"تعريف التصريف","title":"1069-","page":"ص0","text":"(فالهاء في الحاء وعين في الحا ... والحاء في العين كذاك في الها)","bab":"باب الإدغام"},{"id":"shafiya:1125","bookId":"shafiya","type":"section","seq":1125,"chapter":"تعريف التصريف","title":"1070-","page":"ص0","text":"(فيقلبا حاء على ما ثبتا ... لكن فمن زحزح عن النار أتى)","bab":"باب الإدغام"},{"id":"shafiya:1126","bookId":"shafiya","type":"section","seq":1126,"chapter":"تعريف التصريف","title":"1071-","page":"ص0","text":"(والغين في الخاء كبلغ خدمك ... والخاء في الغين كسلخ غنمك)","bab":"باب الإدغام"},{"id":"shafiya:1127","bookId":"shafiya","type":"section","seq":1127,"chapter":"تعريف التصريف","title":"1072-","page":"ص0","text":"(والقاف في الكاف كما نخلقكم ... والكاف في القاف كذاك يدغم)","bab":"باب الإدغام"},{"id":"shafiya:1128","bookId":"shafiya","type":"section","seq":1128,"chapter":"تعريف التصريف","title":"1073-","page":"ص0","text":"(والجيم في الشين على ما جاءا ... في قول من أدغم أخرج شاءا) إدغام اللام المعرفة","bab":"باب الإدغام"},{"id":"shafiya:1129","bookId":"shafiya","type":"section","seq":1129,"chapter":"تعريف التصريف","title":"1074-","page":"ص0","text":"(واللام ذو التعريف في اللام وفي ... ثلاث عشر لازما من أحرف)","bab":"باب الإدغام"},{"id":"shafiya:1130","bookId":"shafiya","type":"section","seq":1130,"chapter":"تعريف التصريف","title":"1075-","page":"ص0","text":"(التاء والثاء وذال ظاء ... والراء والزاي ودال طاء)","bab":"باب الإدغام"},{"id":"shafiya:1131","bookId":"shafiya","type":"section","seq":1131,"chapter":"تعريف التصريف","title":"1076-","page":"ص0","text":"(والصاد والضاد كذا والنون ... والسين والشين فذا قانون)","bab":"باب الإدغام"},{"id":"shafiya:1132","bookId":"shafiya","type":"section","seq":1132,"chapter":"تعريف التصريف","title":"1077-","page":"ص0","text":"(وغير ذي التعريف في المثل لزم ... ونحو بل ران على ما قد علم)","bab":"باب الإدغام"},{"id":"shafiya:1133","bookId":"shafiya","type":"section","seq":1133,"chapter":"تعريف التصريف","title":"1078-","page":"ص0","text":"(وفي البواقي جائز كهل سأل ... كذاك هل تدري وهل شاع المثل) إدغام النون الساكنة","bab":"باب الإدغام"},{"id":"shafiya:1134","bookId":"shafiya","type":"section","seq":1134,"chapter":"تعريف التصريف","title":"1079-","page":"ص0","text":"(وفي السكون يدغمون النونا ... بالفرض في حروف يرملونا)","bab":"باب الإدغام"},{"id":"shafiya:1135","bookId":"shafiya","type":"section","seq":1135,"chapter":"تعريف التصريف","title":"1080-","page":"ص0","text":"(والأفصح الغنة عند الياء ... والواو لا في اللام أو في الراء)","bab":"باب الإدغام"},{"id":"shafiya:1136","bookId":"shafiya","type":"section","seq":1136,"chapter":"تعريف التصريف","title":"1081-","page":"ص0","text":"(والنون قبل الباء ميما يقلب ... كمنبر بعنبر يطيب)","bab":"باب الإدغام"},{"id":"shafiya:1137","bookId":"shafiya","type":"section","seq":1137,"chapter":"تعريف التصريف","title":"1082-","page":"ص0","text":"(والنون في غير حروف الحلق ... يخفى فخمس حاله للخلق)","bab":"باب الإدغام"},{"id":"shafiya:1138","bookId":"shafiya","type":"section","seq":1138,"chapter":"تعريف التصريف","title":"1083-","page":"ص0","text":"(ويدغم النون إذا تحركا ... على الجواز كالذي قد أدركا)","bab":"باب الإدغام"},{"id":"shafiya:1139","bookId":"shafiya","type":"section","seq":1139,"chapter":"تعريف التصريف","title":"1084-","page":"ص0","text":"(والتاء والطاء كذاك الدال ... والثاء والظاء كذا والذال)","bab":"باب الإدغام"},{"id":"shafiya:1140","bookId":"shafiya","type":"section","seq":1140,"chapter":"تعريف التصريف","title":"1085-","page":"ص0","text":"(فبعضها يدغم في البعض وفي ... صاد وزاي ثم سين يقتفي)","bab":"باب الإدغام"},{"id":"shafiya:1141","bookId":"shafiya","type":"section","seq":1141,"chapter":"تعريف التصريف","title":"1086-","page":"ص0","text":"(في نحو فرطت لدى الإطلاق ... إن كان إدغام مع الإطباق)","bab":"باب الإدغام"},{"id":"shafiya:1142","bookId":"shafiya","type":"section","seq":1142,"chapter":"تعريف التصريف","title":"1087-","page":"ص0","text":"(فذاك إتيان بطاء طار ... وجمع ساكنين في اعتبار)","bab":"باب الإدغام"},{"id":"shafiya:1143","bookId":"shafiya","type":"section","seq":1143,"chapter":"تعريف التصريف","title":"1088-","page":"ص0","text":"(ليست كذاك غنة في النون ... فيمن يبقيها على القانون)","bab":"باب الإدغام"},{"id":"shafiya:1144","bookId":"shafiya","type":"section","seq":1144,"chapter":"تعريف التصريف","title":"1089-","page":"ص0","text":"(والصاد ثم الزاي ثم السينا ... فبعضها في البعض يدغمونا)","bab":"باب الإدغام"},{"id":"shafiya:1145","bookId":"shafiya","type":"section","seq":1145,"chapter":"تعريف التصريف","title":"1090-","page":"ص0","text":"(والباء في الميم وفاء أدغما ... نحو يعذب من يشاء مدغما)","bab":"باب الإدغام"},{"id":"shafiya:1146","bookId":"shafiya","type":"section","seq":1146,"chapter":"تعريف التصريف","title":"1091-","page":"ص0","text":"(وجاز أن يدغم تاء افتعلا ... في مثلها كقتلا أو قتلا)","bab":"باب الإدغام"},{"id":"shafiya:1147","bookId":"shafiya","type":"section","seq":1147,"chapter":"تعريف التصريف","title":"1092-","page":"ص0","text":"(عليهما جاء مقتلونا ... بفتح قاف أو مقتلونا)","bab":"باب الإدغام"},{"id":"shafiya:1148","bookId":"shafiya","type":"section","seq":1148,"chapter":"تعريف التصريف","title":"1093-","page":"ص0","text":"(وقد أتى أيضا مرد فينا ... بالضم إتباعا كذا روينا)","bab":"باب الإدغام"},{"id":"shafiya:1149","bookId":"shafiya","type":"section","seq":1149,"chapter":"تعريف التصريف","title":"1094-","page":"ص0","text":"(والثاء في تاء افتعال أدغما ... فرضا على الوجهين كاثأرتما)","bab":"باب الإدغام"},{"id":"shafiya:1150","bookId":"shafiya","type":"section","seq":1150,"chapter":"تعريف التصريف","title":"1095-","page":"ص0","text":"(والسين فيها أدغمت شذوذا ... على شذوذ كاسمع مأخوذا)","bab":"باب الإدغام"},{"id":"shafiya:1151","bookId":"shafiya","type":"section","seq":1151,"chapter":"تعريف التصريف","title":"1096-","page":"ص0","text":"(ولا يجوز اتمعت إذ تذهب ... فضيلة الصفير وهي تطلب)","bab":"باب الإدغام"},{"id":"shafiya:1152","bookId":"shafiya","type":"section","seq":1152,"chapter":"تعريف التصريف","title":"1097-","page":"ص0","text":"(وتاء الافتعال بعد المطبقه ... تقلب طاء لترى منطبقه)","bab":"باب الإدغام"},{"id":"shafiya:1153","bookId":"shafiya","type":"section","seq":1153,"chapter":"تعريف التصريف","title":"1098-","page":"ص0","text":"(فيلزم الإدغام في يطعم ... وجوز الوجهان في يظطلم)","bab":"باب الإدغام"},{"id":"shafiya:1154","bookId":"shafiya","type":"section","seq":1154,"chapter":"تعريف التصريف","title":"1099-","page":"ص0","text":"(وجاءت الثلاث في فيظطلم ... في بيت شعر لزهير قد علم)","bab":"باب الإدغام"},{"id":"shafiya:1155","bookId":"shafiya","type":"section","seq":1155,"chapter":"تعريف التصريف","title":"1100-","page":"ص0","text":"(شذ على شذوذه في اصطبرا ... إذ لا يجوز للصفير اطبرا)","bab":"باب الإدغام"},{"id":"shafiya:1156","bookId":"shafiya","type":"section","seq":1156,"chapter":"تعريف التصريف","title":"1101-","page":"ص0","text":"(وهكذا على الشذوذ في اضطرب ... إذ لم يجز للاستطالة اطرب)","bab":"باب الإدغام"},{"id":"shafiya:1157","bookId":"shafiya","type":"section","seq":1157,"chapter":"تعريف التصريف","title":"1102-","page":"ص0","text":"(وتاء الافتعال دالا قلبا ... في الدال والذال وزاي فاقلبا)","bab":"باب الإدغام"},{"id":"shafiya:1158","bookId":"shafiya","type":"section","seq":1158,"chapter":"تعريف التصريف","title":"1103-","page":"ص0","text":"(وأدغمت على الوجوب ادثر ... وجاء الادغام قويا في ادكر)","bab":"باب الإدغام"},{"id":"shafiya:1159","bookId":"shafiya","type":"section","seq":1159,"chapter":"تعريف التصريف","title":"1104-","page":"ص0","text":"(وجاء بالذال كمثل اذكرا ... وجاء بالفك كمثل اذدكرا)","bab":"باب الإدغام"},{"id":"shafiya:1160","bookId":"shafiya","type":"section","seq":1160,"chapter":"تعريف التصريف","title":"1105-","page":"ص0","text":"(ويضعف الإدغام في يزدجر ... إذ لم يجز لما مضى يدجر)","bab":"باب الإدغام"},{"id":"shafiya:1161","bookId":"shafiya","type":"section","seq":1161,"chapter":"تعريف التصريف","title":"1106-","page":"ص0","text":"(وفي خبطت شذذت خبط ... كذاك فزد ثم عد حصط) إدغام تاء تتنزل وتتنابزوا","bab":"باب الإدغام"},{"id":"shafiya:1162","bookId":"shafiya","type":"section","seq":1162,"chapter":"تعريف التصريف","title":"1107-","page":"ص0","text":"(في تتنازلون عندما وصل ... أو تتنزلون إدغام نقل)","bab":"باب الإدغام"},{"id":"shafiya:1163","bookId":"shafiya","type":"section","seq":1163,"chapter":"تعريف التصريف","title":"1108-","page":"ص0","text":"(إن لم يصاحبه صحيح سكنا ... مقدما وكان معلوم البنا)","bab":"باب الإدغام"},{"id":"shafiya:1164","bookId":"shafiya","type":"section","seq":1164,"chapter":"تعريف التصريف","title":"1109-","page":"ص0","text":"(والتاء من تفعل قد تدغم ... في الأحرف التي بها تدغم)","bab":"باب الإدغام"},{"id":"shafiya:1165","bookId":"shafiya","type":"section","seq":1165,"chapter":"تعريف التصريف","title":"1110-","page":"ص0","text":"(فهمزة الوصل لها تجتلب ... كاثاقلوا وازينوا واطيبوا) إدغام سين الاستفعال)","bab":"باب الإدغام"},{"id":"shafiya:1166","bookId":"shafiya","type":"section","seq":1166,"chapter":"تعريف التصريف","title":"1111-","page":"ص0","text":"(ونحو ما اسطاعوا على الإدغام مع ... بقاء صوت السين نادرا وقع)","bab":"باب الإدغام"},{"id":"shafiya:1167","bookId":"shafiya","type":"section","seq":1167,"chapter":"تعريف التصريف","title":"1112-","page":"ص0","text":"(والحذف للإعلال سابقا ذكر ... والحذف للترخيم في النحو زبر)","bab":"باب الحذف"},{"id":"shafiya:1168","bookId":"shafiya","type":"section","seq":1168,"chapter":"تعريف التصريف","title":"1113-","page":"ص0","text":"(وجاء حذف التاء في تسربل ... تنازعون وهي لا تنزل)","bab":"باب الحذف"},{"id":"shafiya:1169","bookId":"shafiya","type":"section","seq":1169,"chapter":"تعريف التصريف","title":"1114-","page":"ص0","text":"(ظلتم ومستم كأحستم ثبتا ... واسطاع يسطيع ويستيع أتى)","bab":"باب الحذف"},{"id":"shafiya:1170","bookId":"shafiya","type":"section","seq":1170,"chapter":"تعريف التصريف","title":"1115-","page":"ص0","text":"(وفي على الماء أتى علماء ... وفي من الماء أتى ملماء)","bab":"باب الحذف"},{"id":"shafiya:1171","bookId":"shafiya","type":"section","seq":1171,"chapter":"تعريف التصريف","title":"1116-","page":"ص0","text":"(وفي بني العنبر بلعنبر قد ... جاء كبلحارث فيما قد ورد)","bab":"باب الحذف"},{"id":"shafiya:1172","bookId":"shafiya","type":"section","seq":1172,"chapter":"تعريف التصريف","title":"1117-","page":"ص0","text":"(شذ بتاء لم يشدد يتقي ... منه تق الله ببيت مرتقي)","bab":"باب الحذف"},{"id":"shafiya:1173","bookId":"shafiya","type":"section","seq":1173,"chapter":"تعريف التصريف","title":"1118-","page":"ص0","text":"(وليس منه قولهم قد تخذا ... يتخذ فتحا فهو أصل أخذا)","bab":"باب الحذف"},{"id":"shafiya:1174","bookId":"shafiya","type":"section","seq":1174,"chapter":"تعريف التصريف","title":"1119-","page":"ص0","text":"(ثم من استتخذ جاء استخذا ... وقيل إبدال لتاء اتخذا)","bab":"باب الحذف"},{"id":"shafiya:1175","bookId":"shafiya","type":"section","seq":1175,"chapter":"تعريف التصريف","title":"1120-","page":"ص0","text":"(وكيف يبنى من كذا مثل كذا ... يعني إذا منه وزان أخذا)","bab":"باب مسائل التمارين"},{"id":"shafiya:1176","bookId":"shafiya","type":"section","seq":1176,"chapter":"تعريف التصريف","title":"1121-","page":"ص0","text":"(ثم بمقتضى القياس صرفا ... كيف به ينطق حتى يعرفا)","bab":"باب مسائل التمارين"},{"id":"shafiya:1177","bookId":"shafiya","type":"section","seq":1177,"chapter":"تعريف التصريف","title":"1122-","page":"ص0","text":"(والفارسي قال في القياس ... تزيد ما قد زيد في الأساس)","bab":"باب مسائل التمارين"},{"id":"shafiya:1178","bookId":"shafiya","type":"section","seq":1178,"chapter":"تعريف التصريف","title":"1123-","page":"ص0","text":"(وهكذا تحذف ما قد حذفا ... في أصله على قياس عرفا)","bab":"باب مسائل التمارين"},{"id":"shafiya:1179","bookId":"shafiya","type":"section","seq":1179,"chapter":"تعريف التصريف","title":"1124-","page":"ص0","text":"(وعند آخرين حذف ما حذف ... قياسا أو غير قياس إذ تصف)","bab":"باب مسائل التمارين"},{"id":"shafiya:1180","bookId":"shafiya","type":"section","seq":1180,"chapter":"تعريف التصريف","title":"1125-","page":"ص0","text":"(مضربي محوي من ضرب ... أبو علي مضري في النسب)","bab":"باب مسائل التمارين"},{"id":"shafiya:1181","bookId":"shafiya","type":"section","seq":1181,"chapter":"تعريف التصريف","title":"1126-","page":"ص0","text":"(دعو ودعو من دعا كاسم وغد ... وادع دع للآخرين يعتقد)","bab":"باب مسائل التمارين"},{"id":"shafiya:1182","bookId":"shafiya","type":"section","seq":1182,"chapter":"تعريف التصريف","title":"1127-","page":"ص0","text":"(ثم دعايا باتفاق من دعا ... مثل صحائف على ما اخترعا)","bab":"باب مسائل التمارين"},{"id":"shafiya:1183","bookId":"shafiya","type":"section","seq":1183,"chapter":"تعريف التصريف","title":"1128-","page":"ص0","text":"(وعنمل كعنسل من عملا ... ومثله من قال جاء قنولا)","bab":"باب مسائل التمارين"},{"id":"shafiya:1184","bookId":"shafiya","type":"section","seq":1184,"chapter":"تعريف التصريف","title":"1129-","page":"ص0","text":"(لا يدغمون النون كي لا يلبسا ... بفعل المشدود مثل خمسا)","bab":"باب مسائل التمارين"},{"id":"shafiya:1185","bookId":"shafiya","type":"section","seq":1185,"chapter":"تعريف التصريف","title":"1130-","page":"ص0","text":"(ومثل قنفخر كذا عنمل ... للبس علكد كما قنول)","bab":"باب مسائل التمارين"},{"id":"shafiya:1186","bookId":"shafiya","type":"section","seq":1186,"chapter":"تعريف التصريف","title":"1131-","page":"ص0","text":"(لم يبن من نحو كسرت أو جعل ... مثل جحنفل للبس أو ثقل)","bab":"باب مسائل التمارين"},{"id":"shafiya:1187","bookId":"shafiya","type":"section","seq":1187,"chapter":"تعريف التصريف","title":"1132-","page":"ص0","text":"(ومن وأى أوء مثال أبلم ... ومن أوى أو بواو مدغم)","bab":"باب مسائل التمارين"},{"id":"shafiya:1188","bookId":"shafiya","type":"section","seq":1188,"chapter":"تعريف التصريف","title":"1133-","page":"ص0","text":"(ومن وأى إي وزان إجرد ... ومن أوى إي وإي فاقصد)","bab":"باب مسائل التمارين"},{"id":"shafiya:1189","bookId":"shafiya","type":"section","seq":1189,"chapter":"تعريف التصريف","title":"1134-","page":"ص0","text":"(ومنهما عند ولاة العزه ... إيئاة أو إياة من إوزه)","bab":"باب مسائل التمارين"},{"id":"shafiya:1190","bookId":"shafiya","type":"section","seq":1190,"chapter":"تعريف التصريف","title":"1135-","page":"ص0","text":"(وكاطلخم من وأى ايأيا ... ومن أوى وزانه ايويا)","bab":"باب مسائل التمارين"},{"id":"shafiya:1191","bookId":"shafiya","type":"section","seq":1191,"chapter":"تعريف التصريف","title":"1136-","page":"ص0","text":"(من أولق مثال ما شاء الله ... قال ابو علي إذ بناه)","bab":"باب مسائل التمارين"},{"id":"shafiya:1192","bookId":"shafiya","type":"section","seq":1192,"chapter":"تعريف التصريف","title":"1137-","page":"ص0","text":"(وزانه ما ألق الإلاق ... فالألق المقول ثم اللاق)","bab":"باب مسائل التمارين"},{"id":"shafiya:1193","bookId":"shafiya","type":"section","seq":1193,"chapter":"تعريف التصريف","title":"1138-","page":"ص0","text":"(ووجه ذاك أنه قد جعلا ... أولقا اذ أوغل فيه فوعلا)","bab":"باب مسائل التمارين"},{"id":"shafiya:1194","bookId":"shafiya","type":"section","seq":1194,"chapter":"تعريف التصريف","title":"1139-","page":"ص0","text":"(وهو على ذلك قد أجاب في ... اسم بألق أو بألق يقتفي)","bab":"باب مسائل التمارين"},{"id":"shafiya:1195","bookId":"shafiya","type":"section","seq":1195,"chapter":"تعريف التصريف","title":"1140-","page":"ص0","text":"(والفارسي لابن خالويه ... حاور في مسالة لديه)","bab":"باب مسائل التمارين"},{"id":"shafiya:1196","bookId":"shafiya","type":"section","seq":1196,"chapter":"تعريف التصريف","title":"1141-","page":"ص0","text":"(فقال زن من آءة مسطارا ... فظن مفعالا به فحارا)","bab":"باب مسائل التمارين"},{"id":"shafiya:1197","bookId":"shafiya","type":"section","seq":1197,"chapter":"تعريف التصريف","title":"1142-","page":"ص0","text":"(فقال الاستاذ له مساء ... فالأصل مستطار إذ يجاء)","bab":"باب مسائل التمارين"},{"id":"shafiya:1198","bookId":"shafiya","type":"section","seq":1198,"chapter":"تعريف التصريف","title":"1143-","page":"ص0","text":"(كذا أبو الفتح ابن جني سأله ... عن كوكب من لفظ وأي نقله)","bab":"باب مسائل التمارين"},{"id":"shafiya:1199","bookId":"shafiya","type":"section","seq":1199,"chapter":"تعريف التصريف","title":"1144-","page":"ص0","text":"(ثم بواو مع نون جمعه ... ثم إلى الياء أضافه معه)","bab":"باب مسائل التمارين"},{"id":"shafiya:1200","bookId":"shafiya","type":"section","seq":1200,"chapter":"تعريف التصريف","title":"1145-","page":"ص0","text":"(فحار أيضا في جواب ما سأل ... قال أبو الفتح أوي في المثل)","bab":"باب مسائل التمارين"},{"id":"shafiya:1201","bookId":"shafiya","type":"section","seq":1201,"chapter":"تعريف التصريف","title":"1146-","page":"ص0","text":"(من باع منسوجا كعنكبوت ... يجاب في ذاك ببيععوت)","bab":"باب مسائل التمارين"},{"id":"shafiya:1202","bookId":"shafiya","type":"section","seq":1202,"chapter":"تعريف التصريف","title":"1147-","page":"ص0","text":"(وكاطمأن وزنا ابيععا ... مصحح الياء فلا يدعا)","bab":"باب مسائل التمارين"},{"id":"shafiya:1203","bookId":"shafiya","type":"section","seq":1203,"chapter":"تعريف التصريف","title":"1148-","page":"ص0","text":"(من قلت كاغدودن فاقوول قل ... والأخفش اقويل فالواو ثقل)","bab":"باب مسائل التمارين"},{"id":"shafiya:1204","bookId":"shafiya","type":"section","seq":1204,"chapter":"تعريف التصريف","title":"1149-","page":"ص0","text":"(أظهر على اغدودن واو اقووولا ... كذلك ابيويع مثل اغووولا)","bab":"باب مسائل التمارين"},{"id":"shafiya:1205","bookId":"shafiya","type":"section","seq":1205,"chapter":"تعريف التصريف","title":"1150-","page":"ص0","text":"(من قوة مقوي المسفور ... وهكذا قوي العصفور)","bab":"باب مسائل التمارين"},{"id":"shafiya:1206","bookId":"shafiya","type":"section","seq":1206,"chapter":"تعريف التصريف","title":"1151-","page":"ص0","text":"(قضية من قضيت قذعمله ... وهو قض في عضد في المسأله)","bab":"باب مسائل التمارين"},{"id":"shafiya:1207","bookId":"shafiya","type":"section","seq":1207,"chapter":"تعريف التصريف","title":"1152-","page":"ص0","text":"(وكالقذعميلة في القضيه ... فالقضوية على الرويه)","bab":"باب مسائل التمارين"},{"id":"shafiya:1208","bookId":"shafiya","type":"section","seq":1208,"chapter":"تعريف التصريف","title":"1153-","page":"ص0","text":"(وكالحمصيصة في البناء ... فالقضوية على القضاء)","bab":"باب مسائل التمارين"},{"id":"shafiya:1209","bookId":"shafiya","type":"section","seq":1209,"chapter":"تعريف التصريف","title":"1154-","page":"ص0","text":"(في ملكوت كقضوت عملا ... جحمرش كقضيي قد جعلا)","bab":"باب مسائل التمارين"},{"id":"shafiya:1210","bookId":"shafiya","type":"section","seq":1210,"chapter":"تعريف التصريف","title":"1155-","page":"ص0","text":"(ومن حييت حيو كجحمرش ... وكالحلبلاب القضيضاء نقش)","bab":"باب مسائل التمارين"},{"id":"shafiya:1211","bookId":"shafiya","type":"section","seq":1211,"chapter":"تعريف التصريف","title":"1156-","page":"ص0","text":"(قرأيت في دحرجت من قراءه ... ثم قرأي كسبطر جاءه)","bab":"باب مسائل التمارين"},{"id":"shafiya:1212","bookId":"shafiya","type":"section","seq":1212,"chapter":"تعريف التصريف","title":"1157-","page":"ص0","text":"(أتوا على اطمأننت باقرأيأت ... ويقرئي حالهم أن يأتوا)","bab":"باب مسائل التمارين"},{"id":"shafiya:1213","bookId":"shafiya","type":"section","seq":1213,"chapter":"تعريف التصريف","title":"1158-","page":"ص0","text":"(تم بعون الله صرف الشافيه ... ورخته فقلت نظمي الوافيه)","bab":"باب مسائل التمارين"},{"id":"shafiya:1214","bookId":"shafiya","type":"section","seq":1214,"chapter":"تعريف التصريف","title":"1159-","page":"ص0","text":"(أبياتها بليغة عليه ... عدتها منظومة قويه)","bab":"باب مسائل التمارين"},{"id":"shafiya:1215","bookId":"shafiya","type":"section","seq":1215,"chapter":"تعريف التصريف","title":"1160-","page":"ص0","text":"(ناظمها في سلكها قوام ... والحمد كالمسك لها ختام)","bab":"باب مسائل التمارين"}]};